classdef ColorSpecEnum < matlab.mixin.SetGet

    enumeration
        Red('Red',[1 0 0])
        Magenta('Magenta',[178,0,255]/255)
        Orange('Orange', [255,131,0]/255)
        Yellow('Yellow', [255,216,0]/255)
        Green('Green', [76,220,0]/255)
        Cyan('Cyan',[0,210,255]/255)
        Blue('Blue',[0 0 1])
        Black('Black',[0 0 0])
        White('White',[1 1 1])
        Pink('Pink',[255,0,220]/255)
        Brown('Brown',[139,69,19]/255)
        DarkGrey('Dark Grey',[0.15 0.15 0.15]);
        Grey('Grey',[0.5, 0.5, 0.5])
        LightGrey('Light Grey',[223 223 223]/255);
        BrightGreen('Bright Green', [102, 255, 0]/255);
    end

    properties
        name char = '';
        color(1,3) double;

        iconBaseTemplateFile(1,:) char = 'square_gradient.png';
        iconImageHSV double
        iconImageRBG double
    end

    methods
        function obj = ColorSpecEnum(name,color)
            obj.name = name;
            obj.color = color;

            [A,~,~]=imread(obj.iconBaseTemplateFile, 'BackgroundColor',[1,1,1]);
            RGB = double(A)/255;
            obj.iconImageHSV = rgb2hsv(RGB);
            obj.iconImageRBG = obj.getIconForColorSpecEnum();
        end

        function RGB_color = getIconForColorSpecEnum(obj)

            enum = m(ind);
        end

        function bgColorRgb = getBestGreyBackgroundColor(colorEnums)
            arguments
                colorEnums ColorSpecEnum
            end

            cRGB = vertcat(colorEnums(:).color);
            cHSV = rgb2hsv(cRGB);

            origValues = cHSV(:,3);
            values = unique(sort([0;origValues;1]));
            valueDiffs = diff(values);
            [~,I] = max(valueDiffs);

            if(I == 1 && not(ismember(0,origValues)))
                useThisValue = 0;
            elseif(I == numel(valueDiffs) && not(ismember(1,origValues)))
                useThisValue = 1;
            else
                useThisValue = mean([values(I), values(I+1)]);
            end

            bgColorRgb = hsv2rgb([0,0,useThisValue]);
        end
    end
end

function colorsurface( ptch, cameras )


error( nargchk( 2, 2, nargin ) );

if ~ishandle( ptch ) || ~strcmpi( get( ptch, 'Type' ), 'patch' )
    error( 'COLORSURFACE:BadPatch', 'First argument must the handle to a patch object created using the PATCH command' );
end

vertices = get( ptch, 'Vertices' );
normals = get( ptch, 'VertexNormals' );
num_vertices = size( vertices, 1 );
[h, w] = size(cameras(1).Silhouette);

num_cameras = numel( cameras );
cam_normals = zeros( 3, num_cameras );
for ii=1:num_cameras
    cam_normals(:,ii) = spacecarving.getcameradirection( cameras(ii) );
end

vertexcdata = zeros( num_vertices, 3 );
for ii=1:num_vertices
    angles = normals(ii,:)*cam_normals./norm(normals(ii,:));
    while(1)
        [~,cam_idx] = min( angles );
        angles(cam_idx) = 360;
        [imx,imy] = spacecarving.project( cameras(cam_idx), ...
            vertices(ii,1), vertices(ii,2), vertices(ii,3) );
        if (imx >= 1 && imx <= w && imy >= 1 && imy <= h)
            vertexcdata(ii,:) = double( cameras(cam_idx).Image( round(imy), round(imx), : ) )/255;
            break;
        end
    end
end

set( ptch, 'FaceVertexCData', vertexcdata, 'FaceColor', 'interp' );

