function [outputNode] = combineChildren(CNFNode1,CNFNode2)

if isempty(CNFNode1.children)
    outputNode = CNFNode2;
    return
end

if isempty(CNFNode2.children)
    outputNode = CNFNode1;
    return
end

outputNode = AndNode();
childSets = {};
for child1 = 1:numel(CNFNode1.children)               
    for child2 = 1:numel(CNFNode2.children)
        if isa(CNFNode1.children(child1),'LiteralNode')
            c1node = OrNode();
            c1node.addChild(CNFNode1.children(child1).copy());
        else
            c1node = CNFNode1.children(child1).copy();
        end
        c2node = CNFNode2.children(child2).copy();
        c1node.addChild(c2node);
        currentLiterals = c1node.getLiterals();
        existing = cellfun(@(x) all(ismember(x,currentLiterals)),childSets); %Check if it already exists
        superseeded = cellfun(@(x) all(ismember(currentLiterals,x)),childSets); %Or if it contains clauses that can be removed.
        if any(superseeded)
            outputNode.children(superseeded) = [];
            childSets(superseeded) = [];
        end
        if ~any(existing)
            childSets{end+1} = currentLiterals;
            c1node.reduce();
            c1node.removeDuplicateLiterals();
            outputNode.addChild(c1node);
        end        
    end
end

function cluster = combineClusters(labelmat, spatdimneighbstructmat, total)



replaceby=1:total;
spatdimlength = size(labelmat, 1);
for spatdimlev=1:spatdimlength
  neighbours=find(spatdimneighbstructmat(spatdimlev,:));
  for nbindx=neighbours
    indx = find((labelmat(spatdimlev,:)~=0) & (labelmat(nbindx,:)~=0));
    for i=1:length(indx)
      a = labelmat(spatdimlev, indx(i));
      b = labelmat(nbindx, indx(i));
      if replaceby(a)==replaceby(b)
        continue;
      elseif replaceby(a)<replaceby(b)
        replaceby(find(replaceby==replaceby(b))) = replaceby(a); 
      elseif replaceby(b)<replaceby(a)
        replaceby(find(replaceby==replaceby(a))) = replaceby(b); 
      end
    end
  end
end

num = 0;
cluster = zeros(size(labelmat));
for uniquelabel=unique(replaceby(:))'
  num = num+1;
  cluster(ismember(labelmat(:),find(replaceby==uniquelabel))) = num;
end

end

