function [initmeans,finalmeans,dists,inds,iter]=COMKMeans(train,valid,K,NUMiter,NUMruns) 

  validists=+Inf;
  rand('state',100);
  [NUMdims,NUMpts]=size(train);
  for i=1:NUMruns,
    if (rand<0.5), % Randomly, either choose initmeans or initlabels
      initmeansi=train(:,COMuniquerand(K,[1,NUMpts]));
    else
      collapsed=1;
      while (collapsed==1),
	[initmeansi,collapsed]=maxparms(train,round(1+rand(1,NUMpts)*(K-1)),K);
      end;
    end;
    [finalmeansi,distsi,indsi,iteri]=MEXkmeans_faster2(train,initmeansi,NUMiter);
    if (isempty(valid)), 
      validistsi=sum(distsi.^2);
    else
      [x,validistsi,x,x]=MEXkmeans_faster2(valid,finalmeansi,0);
      validistsi=sum(validistsi.^2);
    end;
    if (validistsi<validists),
      initmeans=initmeansi;
      finalmeans=finalmeansi;
      dists=distsi;
      inds=indsi;
      iter=iteri;
      validists=validistsi;
    end;
  end;
end

function [means,BOOLcollapsed]=maxparms(datapts,labels,K)
  means=zeros(size(datapts,1),K);
  BOOLcollapsed=any(histc(labels,[1:K])==0);
  if (~BOOLcollapsed),
    for m=1:K, means(:,m)=mean(datapts(:,find(labels==m))')'; end;
  end;
end

function u0 = CommonIC(x,ICcase)
Lx=x(end)-x(1); xmid=0.5*(x(end)+x(1));
switch ICcase
    case 1 % Gaussian wave for [-1,1] 
        u0 = exp(-20*(x-xmid).^2);

    case 2 % Gaussian wave for [-3,3] 
        mu = 0.01;
        u0 = exp(-(x-xmid).^2/(4*mu));

    case 3 % Centered sinusoidal wave for [-1,1] for advection.
        u0 = sin(pi*x);

	case 4 % Lifted sinusoidal wave for [-1,1] for advection.
        u0 = 0.5 - sin(pi*x);

    case 5 % Hyperbolic Tangent in [-,2,2] 
        mu = 0.02;
        u0 = 0.5*(1-tanh(x/(4*mu)));

    case 6 % Riemann problem
        u0 = ones(size(x));
        u0(x<=xmid) = 2;

    case 7 % Hyperbolic Tangent
        a = x(1); b = x(end);
        xi = (4-(-4))/(b-a)*(x - a) - 4;
        u0 = 1/2*(tanh(-4*xi)+1);

    case 8 % Square Jump
        u0 = RectangularPulse(xmid-0.1*Lx,xmid+0.1*Lx,x)+1;

	case 9 % Displaced square Jump
        xmid = -0.25;
        u0 = RectangularPulse(xmid-0.125*Lx,xmid+0.125*Lx,x);

function YTan = commontangent(Z, YCar, YPax)


iCross = 2;
while YCar(iCross) > YPax(iCross), iCross = iCross + 1; end

dmin = 1e10;
for iCar = 2:iCross-1
    for iPax = iCross:length(YPax)-1
        ComTanSlope = (YPax(iPax) - YCar(iCar))/...
                        (Z(iPax) -   Z(iCar));

        CarSlopeUp = (YCar(iCar+1) - YCar(iCar))/...
                       (Z(iCar+1) -   Z(iCar));
        CarSlopeDn = (YCar(iCar) -   YCar(iCar-1))/...
                       (Z(iCar) -   Z(iCar-1));
        CarSlope = 0.5*(CarSlopeUp + CarSlopeDn);


        PaxSlopeUp = (YPax(iPax+1) - YPax(iPax))/...
                       (Z(iPax+1) -   Z(iPax));
        PaxSlopeDn = (YPax(iPax) -   YPax(iPax-1))/...
                       (Z(iPax) -   Z(iPax-1));


        PaxSlope = 0.5*(PaxSlopeUp + PaxSlopeDn);

        d = abs(CarSlope - ComTanSlope) + abs(PaxSlope - ComTanSlope);

        if d < dmin
            dmin = d;
            iCarMin = iCar;
            iPaxMin = iPax;
        end
    end
end

if exist('iPaxMin','var')
    ComTanSlope = (YPax(iPaxMin) - YCar(iCarMin))/...
               (Z(iPaxMin) -   Z(iCarMin));

