classdef ComparisonTypeEnum < matlab.mixin.SetGet

    enumeration
        Equals('Equals', '==');
        GreaterThan('Greater Than', ">");
        LessThan('Less Than', '<');
        GreaterThanOrEquals('Greater Than Or Equals', '>=');
        LessThanOrEquals('Less Than Or Equals', '<=');
    end

    properties
        name(1,1) string
        symbol(1,1) string
    end

