function R = ComplexSpectrum2SpatialCov(X, context_size, shift, useGPU)
if nargin<4
    useGPU = 1;
end

half_ctx = (context_size-1)/2;
[D, N, T] = size(X);    % D is number of freq bin, N is number of channel

if context_size == 0    % get global spatial covariance matrix
    X2 = permute(X, [2 1 3]);
    XX = outProdND(X2);
    R = mean(XX,4);
else    % get windowed spatial covariance
    if 0
        nBlock = length(1:shift:T);
        R = zeros(N,N,D,nBlock);
        for d = 1:D
            for t = 1:shift:T
                frame_selector = t-half_ctx:t+half_ctx;
                frame_selector = min(T,max(1,frame_selector));
                X2 = squeeze(X(d,:,frame_selector));
                R(:,:,d,(t-1)/shift+1) = X2*X2' / context_size;
            end
        end
    else
        X2 = permute(X, [2 1 3]);
        XX = outProdND(X2);
        XX2 = reshape(XX, N^2*D, T);
        if 1
            if useGPU
                XX2 = gpuArray(XX2);
            end
            idx = [ones(1,half_ctx) 1:T ones(1,half_ctx)*T];
            SCM = conv2(XX2(:,idx), ones(1,context_size, class(gather(X)))/context_size, 'valid');
        else
            fake_layer.a = XX2;
            XX3 = F_splice(fake_layer, context_size);
            XX4 = reshape(XX3,  N^2*D, context_size, T);
            SCM = mean(XX4,2);
        end
        SCM2 = reshape(SCM, N^2, D, T);
        SCM3 = reshape(SCM2, N, N, D, T);
        R = SCM3(:,:,:,1:shift:end);

function complextest_AD3()

    if isempty(which('spherecomplexfactory'))
        error(['You should first add Manopt to the Matlab path.\\n' ...
		       'Please run importmanopt.']);
    end

    assert(exist('dlarray', 'file') == 2, ['Deep learning tool box is '... 
    'needed for automatic differentiation.\\n Please install the'...
    'latest version of the deep learning tool box and \\nupgrade to Matlab'...
    ' R2021b if possible.'])

    n = 100;
    A = randn(n) + 1i*randn(n);
    A = .5*(A+A');

    S = spherecomplexfactory(n);
    P = powermanifold(S,1); % cell 
    X.x = S;
    X.y = P;
    problem.M = productmanifold(X); % struct


    problem.cost  = @(X) -creal(cprod(cprod(ctransp(X.x), A), X.y{1}));

    problem = manoptAD(problem);

    figure;
    checkgradient(problem);
    figure;
    checkhessian(problem);

    [x, xcost, info] = trustregions(problem);          %#ok<ASGLU>

    ground_truth = svd(A);
    distance = abs(ground_truth(1) - (-problem.cost(x)));
    fprintf('The distance between the ground truth and the solution is %e \\n',distance);


end

