function [Eout, Rout] = ComposeEuler(varargin)

	Num = length(varargin);
	if Num <= 0
		Eout = [0 0 0];
		Rout = eye(3);
	elseif Num == 1
		Eout = varargin{1};
		if nargout >= 2
			Rout = RotmatFromEuler(Eout);
		end
	else
		Rout = RotmatFromEuler(varargin{1});
		for k = 2:Num
			E = varargin{k};
			if numel(E) ~= 3
				warning('Ignoring an invalid rotation parameter!');
				continue;
			end
			Rout = Rout * RotmatFromEuler(E);
		end
		Eout = EulerFromRotmat(Rout);
	end

end

function [Fout, Rout] = ComposeFused(varargin)

	Num = length(varargin);
	if Num <= 0
		Fout = [0 0 0 1];
		Rout = eye(3);
	elseif Num == 1
		Fout = varargin{1};
		if nargout >= 2
			Rout = RotmatFromFused(Fout);
		end
	else
		Rout = RotmatFromFused(varargin{1});
		for k = 2:Num
			F = varargin{k};
			if numel(F) ~= 4
				warning('Ignoring an invalid rotation parameter!');
				continue;
			end
			Rout = Rout * RotmatFromFused(F);
		end
		Fout = FusedFromRotmat(Rout);
	end

end

