function [dxi, dgamma, dPhi] = computeGradientMFLDA (xi, gamma, Phi, auxdata)
  [nu eta L w] = deal(auxdata{1:4});

  D = length(L);    % The number of documents.
  K = length(nu);   % The number of topics.
  W = length(eta);  % The size of the vocabulary.
  M = length(w);    % The size of the corpus.

  c   = sum(Phi);
  Phi = Phi ./ repmat(c,K,1);  

  m   = computem(L,w,W,K,Phi);
  x   = repmat(eta,1,K) + m - xi;
  dxi = trigamma(xi).*x - repmat(trigamma(sum(xi)).*sum(x),W,1);

  dgamma = zeros(K,D);
  is     = 0;
  for d = 1:D
    is          = is(end) + (1:L(d));
    phi         = Phi(:,is);
    g           = gamma(:,d);
    x           = nu + row_sum(phi) - g;
    dgamma(:,d) = trigamma(g).*x - repmat(trigamma(sum(g))*sum(x),K,1);
  end

  dPhi = zeros(K,M);
  is   = 0;
  for d = 1:D
    is = is(end) + (1:L(d));
    g  = gamma(:,d);
    for i = is
      j         = w(i);
      dPhi(:,i) = digamma(xi(j,:))' - digamma(sum(xi))' + ...
                  digamma(g) - digamma(sum(g)) - log(Phi(:,i)) - 1;
    end
  end

  dPhi = (dPhi - repmat(sum(dPhi.*Phi),K,1)) ./ repmat(c,K,1);

  dxi    = -dxi;
  dgamma = -dgamma;
  dPhi   = -dPhi;

function [gradNorm, indNorms] = computeGradNorm(grad, batchSize, names)
  if ~exist('names', 'var')
    names = fields(grad);
  end

  gradNorm = 0;
  for ii=1:length(names)
    field = names{ii};
    if iscell(grad.(field)) % cell
      for jj=1:length(grad.(field))
        indNorms.(field){jj} = double(sum(grad.(field){jj}(:).^2));
        gradNorm = gradNorm + indNorms.(field){jj};
        indNorms.(field){jj} = sqrt(indNorms.(field){jj})/batchSize;
      end
    else
      indNorms.(field) = double(sum(grad.(field)(:).^2));
      gradNorm = gradNorm + indNorms.(field);
      indNorms.(field) = sqrt(indNorms.(field))/batchSize;
    end
  end

  gradNorm = sqrt(gradNorm)/batchSize;
end

