function [matching, objective] = greedy_matching_rowwise(iou_matrix)
  assert(size(iou_matrix, 1) <= size(iou_matrix, 2));
  n = size(iou_matrix, 1);
  matching = zeros(n, 1);
  objective = 0;
  for i = 1:n
    [max_per_row, max_col_per_row] = max(iou_matrix, [], 2);
    [max_iou,row] = max(max_per_row);
    if max_iou == -inf
      break
    end

    objective = objective + max_iou;
    col = max_col_per_row(row);
    matching(row) = col;
    iou_matrix(row,:) = -inf;
    iou_matrix(:,col) = -inf;
  end
end

function bel = compute_bel(msg_type, pi, lambda)

switch msg_type,
 case 'd', bel = normalise(pi .* lambda);
 case 'g',
  if isinf(lambda.precision) % ignore pi because lambda is completely certain (observed)
    bel.mu = lambda.mu;
    bel.Sigma = zeros(length(bel.mu)); % infinite precision => 0 variance
  elseif all(pi.Sigma==0) % ignore lambda because pi is completely certain (delta fn prior)
    bel.Sigma = pi.Sigma;
    bel.mu = pi.mu;
  elseif all(isinf(pi.Sigma)) % ignore pi because pi is completely uncertain
    bel.Sigma  = inv(lambda.precision);
    bel.mu = bel.Sigma * lambda.info_state;
  elseif all(lambda.precision == 0) % ignore lambda because lambda is completely uncertain
    bel.Sigma = pi.Sigma;
    bel.mu = pi.mu;
  else % combine both pi and lambda
    pi_precision = inv(pi.Sigma);
    bel.Sigma = inv(pi_precision + lambda.precision);
    bel.mu = bel.Sigma*(pi_precision * pi.mu + lambda.info_state);
  end
 otherwise, error(['unrecognized msg type ' msg_type])
end

function vertex1 = compute_bending_invariant(vertex,faces,options)


options.null = 0;
nlandmarks = getoptions(options, 'nlandmarks', 200);
nverts = max(size(vertex));
nlandmarks = min(nlandmarks,nverts);

Dland = [];
for i=1:nlandmarks
    if i==1
        landmarks = floor(rand*nverts)+1;
    else
        [tmp,landmarks(end+1)] = max( min(Dland, [], 2) );
    end
    progressbar(i,nlandmarks);
    [d,S,Q] = perform_fast_marching_mesh(vertex, faces, landmarks(i));
    Dland(:,end+1) = d(:);
end
fprintf('\\n');
Dland = Dland.^2;
D1 = Dland(landmarks,:); % reduced pairwise distances
D1 = (D1+D1')/2; % force symmetry
J = eye(nlandmarks) - ones(nlandmarks)/nlandmarks; % centering matrix
K = -1/2 * J*D1*J; % inner product matrix
opt.disp = 0;
[xy, val] = eigs(K, 3, 'LM', opt);
xy = xy .* repmat(1./sqrt(diag(val))', [nlandmarks 1]);
vertex1 = zeros(nverts,3);
deltan = mean(Dland,1);
for x=1:nverts
    deltax = Dland(x,:);
    vertex1(x,:) = 1/2 * ( xy' * ( deltan-deltax )' )';
end

return;

