function S = compute_LaplacianBasis(S,numEigs)
if nargin < 2, numEigs = 200; end
fprintf('Computing %d Eigen-functions...',numEigs); tic;

[W, A] = cotLaplacian(get_mesh_vtx_pos(S), S.surface.TRIV);

A = sparse(1:length(A), 1:length(A), A);
try
    [evecs, evals] = eigs(W, A, numEigs, 1e-6);
catch
    [evecs, evals] = eigs(W - 1e-8*speye(S.surface.nv), A, numEigs, 'sm');
end
evals = diag(evals);

[evals, order] = sort(abs(evals),'ascend');
S.evals = evals;
evecs = evecs(:,order);
S.evecs = evecs;
S.A = A;
S.W = W;
S.area = diag(S.A);
S.sqrt_area = sqrt(sum(S.area));
t =toc; fprintf('done:%.4fs\\n',t);
end

function S = compute_laplacian_basis(S1, numEigs, flag)

if nargin < 3
    flag = true;
end

	S.surface = S1.surface;

    T = S1.surface.TRIV; 
    area_S = sum(vertexAreas(S1.surface.VERT, S1.surface.TRIV));
    if flag 
        tau = sqrt(area_S); 
    else
        tau = 1; 
    end

    S.surface.X = S.surface.X/tau; 
    S.surface.Y = S.surface.Y/tau; 
    S.surface.Z = S.surface.Z/tau; 
    S.surface.VERT = S.surface.VERT/tau; 

    X = S.surface.VERT; 
    S.Nf = cross(X(T(:,1),:) - X(T(:,2),:), X(T(:,1),:) - X(T(:,3),:));
	S.normals_face = S.Nf./repmat(sqrt(sum(S.Nf.^2, 2)), [1, 3]);

    S.W = cotWeights(X, S.surface.TRIV);
	S.A = diag(vertexAreas(X, S.surface.TRIV)); 
    nv = size(S.A,1);

	try
	    [S.evecs, S.evals] = eigs(S.W, S.A, numEigs, 1e-6);
	catch
	    [S.evecs, S.evals] = eigs(S.W - 1e-8*speye(nv), S.A, numEigs, 'sm');
	end

    [S.evals, order] = sort(diag(S.evals), 'ascend');
    S.evecs = S.evecs(:,order);


	S.nv = nv; 
    S.nf = length(T);

function D = compute_levelset_shape(name, n, options)


options.null = 0;


[Y,X] = meshgrid(1:n,1:n);

switch lower(name)

    case 'circle'
        if isfield(options, 'center')
            center = options.center;
        else
            center = [n n]/2;
        end
        if isfield(options, 'radius')
            radius = options.radius;
        else
            radius = n/4;
        end
        D = sqrt( (X-center(1)).^2+(Y-center(2)).^2 ) - radius;
    case 'rectangle'
        if isfield(options, 'corner1')

        else
            center = [1 1]*n/2;
        end
        options.corner1 = center(:)-repmat(width,2,1)/2;
        options.corner2 = center(:)+repmat(width,2,1)/2;
        D = compute_levelset_shape('rectangle', n, options);

    case 'small-disks'
        D = Inf*ones(n);
        if isfield(options, 'nbdisks')
            nbdisks = options.nbdisks;
        else
            nbdisks = 5;
        end
        x = linspace(0,n,nbdisks+1); x(end) = []; x = x+n/(2*nbdisks);
        options.radius = 0.75*n/(2*nbdisks);
        for i=1:nbdisks
            for j=1:nbdisks
                options.center = [x(i) x(j)];
                D = min(D, compute_levelset_shape('circle', n, options) );
            end
        end
    otherwise 
        error('Unknown shape.');
end

