function [ feature ] = comp_object_3d_feature( obj_xyz, room_xyz, obj_ori_size, obj_angle )
if nargin==0
    feature = 55;
    return;
end

obj_ctr = (obj_xyz(1:3)+obj_xyz(4:6))/2;
