function res = contractInterval(f,dom,jacHan,varargin)



    method = 'taylm';
    if nargin >= 4 && ~isempty(varargin{1})
       method = varargin{1}; 
    end

    mi = center(dom);
    A = jacHan(mi);

    if strcmp(method,'taylm')
       try
           tay = taylm(dom);
           J = interval(jacHan(tay));
       catch
           J = jacHan(dom); 
       end
    else
        J = jacHan(dom);
    end

    b = f(mi) - A * mi + (J - A) * (dom - mi);

    for i = 1:length(dom)

        for j = 1:size(A,1)

           if abs(A(j,i)) > 1e-10

              a = A(j,:); 
              a(i) = 0;
              temp = -(b(j) + a*dom)/A(j,i);
              dom_ = dom(i) & temp;

              if ~representsa_(dom_,'emptySet',eps)
                  dom(i) = dom_;
              else
                  res = []; return; 
              end
           end
        end
    end

    res = dom;
end

