function best_acc = COPAR_top(dataset, N_train, k, k0, lambda, eta)
    addpath(genpath('utils'));  
    addpath(genpath('DLSI'));      
    addpath(genpath('COPAR'));      
    addpath('ODL')
    if nargin == 0 
        dataset = 'myYaleB';
        N_train = 10;
        k = 8;
        k0 = 5;
        lambda = 0.001;
        eta = 0.01;
    end 
    t = getTimeStr();
    [dataset, Y_train, Y_test, label_train, label_test] = ...
        train_test_split(dataset, N_train);
    [acc, rt] = COPAR_wrapper(Y_train, label_train, Y_test , label_test, ...
                            k, k0, lambda, eta);
    disp(rt);
    if ~exist('results', 'dir')
        mkdir('results');
    end 
    if ~exist(fullfile('results', 'COPAR'), 'dir')
        mkdir('results', 'COPAR');
    end 
    fn = fullfile('results', 'COPAR', strcat(dataset, '_N_', ...
        num2str(N_train), '_k_', num2str(k), '_k0_', num2str(k0), ...
        '_l_', num2str(lambda), '_e_', num2str(eta), '_', t, '.mat'));
    disp(fn);
    save(fn, 'acc', 'rt'); 
    best_acc = max(acc);
end

function D = COPAR_updateD(Y, Y_range, D, X, opts) % and DCp1 
    if nargin == 0 
        clc;
        addpath(fullfile('..', 'utils'));
        addpath(fullfile('..', 'DLSI'));
        C = 10;    N = 7;    d = 300;      
        k = 7;
        opts.k0          = 10;
        opts.lambda      = 0.01;
        opts.eta         = 0.1;
        opts.D_range     = k* (0:C);
        opts.D_range_ext = [opts.D_range opts.D_range(end)+opts.k0];
        opts.max_iter    = 10;
        opts.verbose      = true;


        load('tmp2.mat', 'Y', 'Y_range', 'D', 'X');
    end         

    C              = numel(Y_range) - 1;
    D_range_ext    = opts.D_range_ext;    
    DCp1           = get_block_col(D, C+1, D_range_ext);
    optsD          = opts;
    optsD.verbose   = false;
    optsD.max_iter = 100;    
    Yhat           = zeros(size(Y));
    for c = 1: C 
        Dc_range = D_range_ext(c)+1: D_range_ext(c+1);
        Yc_range = Y_range(c)+1: Y_range(c+1);
        Yc       = Y(:, Yc_range);
        Dc       = D(:, Dc_range);
        Xc       = X(:, Yc_range);
        Xcc      = get_block_row(Xc, c, D_range_ext);
        XCp1c    = get_block_row(Xc, C+1, D_range_ext);
        Ychat    = Yc - D*Xc + Dc*Xcc;
        Ycbar    = Yc - DCp1*XCp1c;
        E        = (Ychat + Ycbar)*Xcc';
        F        = 2*Xcc*Xcc';
        A        = D;
        A(:,Dc_range)     = []; 
        D(:, Dc_range)    = DLSI_updateD(Dc, E, F, A', opts.eta, optsD);
        Yhat(:, Yc_range) = Yc - D(:, Dc_range)*Xcc;            
    end 
    XCp1       = X(D_range_ext(C+1) + 1 : D_range_ext(C+2), :);
    Ybar       = Y - D(:, 1: D_range_ext(end-1))*X(1: D_range_ext(end-1), :);
    E          = (Ybar + Yhat)*XCp1';
    F          = 2*XCp1*XCp1';
    A          = D(:, 1: D_range_ext(C+1));
    DCp1_range = D_range_ext(C+1) + 1: D_range_ext(C+2);
    D(:, DCp1_range) = DLSI_updateD(D(:, DCp1_range), E, F, A', opts.eta,  optsD);

