        Dc    = get_block_col(D, c, D_range_ext);
        DCp1  = get_block_col(D, C+1, D_range_ext);
        cost = cost + normF2(Yc - Dc *Xcc - DCp1*XCp1c);
        for i = 1 : C 
            if i == c 
                continue
            end 
            Xic = get_block_row(Xc, i, D_range_ext);
            cost = cost + normF2(Xic);
        end

