function [acc, rt] = COPAR_wrapper(Y_train, label_train, Y_test , label_test, ...
                            k, k0, lambda, eta)
    if nargin == 0 % test mode
        dataset = 'myYaleB';
        N_train = 10;        
        [~, Y_train, Y_test, label_train, label_test] = ...
            train_test_split(dataset, N_train);        
        k = 8;
        k0 = 5;
        lambda = 0.001;
        eta = 0.01;        
    end 
    opts.k = k;
    opts.k0 = k0;
    C                = max(label_test);
    D_range_ext = [k*(0:C), k*C + k0];
    opts.lambda      = lambda;
    opts.eta         = eta;    
    train_range      = label_to_range(label_train);
    opts.show        = false;
    opts.max_iter    = 10;        
    opts.verbose      = true;
    opts = initOpts(opts);
    [D, X, rt] = COPAR(Y_train, train_range, opts);
    acc = [];
    for vgamma = [0.0001, 0.001, 0.005, 0.01]
        opts.gamma = vgamma;
        fprintf('gamma %5f\\n', vgamma);
        opts.classify_mode = 'LC';
        pred = COPAR_pred(Y_test, D, D_range_ext, opts);
        acc = [acc double(sum(pred == label_test))/numel(label_test)];
        fprintf('LC mode, acc = %5f\\n', acc(end));

        opts.classify_mode = 'GC';
        pred = COPAR_pred(Y_test, D, D_range_ext, opts);
        acc = [acc double(sum(pred == label_test))/numel(label_test)];
        fprintf('GC mode, acc = %5f\\n', acc(end));        
    end
    acc = max(acc);
end

classdef CoPeakGen < dagnn.ElementWise
    properties
        Kernal = ones(3, 3, 3, 3, 'double')
        BatchSize = [];
        PeakMasks = [];
        ThresholdFun = @(X)median(X);
        NumPositiveData = [];
    end

    methods
        function outputs = forward(obj, inputs, params)
            obj.BatchSize = size(inputs{1});
            if length(obj.BatchSize) == 4
                obj.BatchSize = [obj.BatchSize 1];
            end
            obj.PeakMasks = gpuArray.false(obj.BatchSize);
            obj.NumPositiveData = zeros(1,  obj.BatchSize(end));
            PositiveData = gpuArray.zeros(obj.BatchSize(end), 1, 'single');
            for i = 1:obj.BatchSize(end)
                TempMap = inputs{1}(:,:,:,:,i);
                obj.PeakMasks(:,:,:,:,i) = gpuArray(imregionalmax(gather(TempMap), obj.Kernal)) ...
                    & TempMap >= obj.ThresholdFun(TempMap(:));
                TeampData = TempMap(obj.PeakMasks(:,:,:,:,i));

classdef CopeakLoss < dagnn.Loss
    properties
        eps = 10^-5;
        NumInputs = [];
        c = [];
        x = [];
    end

    methods
        function outputs = forward(obj, inputs, params)
            if length(inputs) == 2
                obj.NumInputs = [length(inputs{1}) length(inputs{2})];
                obj.c = cat(1, gpuArray.ones(obj.NumInputs(1), 1), -gpuArray.ones(obj.NumInputs(2), 1));
                obj.x = cat(1, inputs{1}, inputs{2});
                a = -obj.c.*obj.x ;
                b = max(0, a) ;
                t = b + log(exp(-b) + exp(a-b)) ;
                outputs{1} = mean(t(1:obj.NumInputs(1))) + mean(t(obj.NumInputs(1)+1:end));
                NumData = length(inputs{1}) + length(inputs{2});
            else
                obj.NumInputs = length(inputs{1});
                obj.c = gpuArray.ones(obj.NumInputs(1), 1);
                obj.x = inputs{1};
                a = -obj.c.*obj.x ;

