function fh = copyfig(fh)



    if nargin == 0
        fh = gcf;
    end
    if isempty(findall(fh, 'Type', 'axes', 'Tag', 'legend'))
        oldWarn = warning('off'); %#ok<WNOFF>  %Suppress warnings during copyobj (Dun Kirk comment on FEX page 2013-10-02)
        fh = copyobj(fh, 0);
        warning(oldWarn);
    else
        tmp_nam = [tempname '.fig'];
        try
            fid = fopen(tmp_nam,'w');
            fwrite(fid,1);
            fclose(fid);
            delete(tmp_nam);  % cleanup
        catch
            [dummy,fname,fext] = fileparts(tmp_nam); %#ok<ASGLU>
            fpath = pwd;
            tmp_nam = fullfile(fpath,[fname fext]);
        end
        hgsave(fh, tmp_nam);
        fh = hgload(tmp_nam);
        delete(tmp_nam);
    end
end

function objnew = CopyHandles(varargin)

if nargin==1
    obj = varargin{1};
elseif nargin==2
    obj    = varargin{1};
    objnew = varargin{2};
end

if isempty(obj)
    objnew = obj;
    return
end

if isa(obj, 'handle')
    objnew = obj(1).copy;
    for ii=2:length(obj)
        objnew(ii) = obj(ii).copy;
    end
else
    objnew = obj;
end

props = properties(obj(1));

for ii=1:length(obj)   
    for iProp=1:length(props)
        if isa( eval( sprintf('obj(ii).%s', props{iProp}) ), 'handle')
            for kk=1:eval( sprintf('length(obj(ii).%s)', props{iProp}) )
                eval( sprintf('objnew(ii).%s(kk) = CopyHandles(obj(ii).%s(kk));', props{iProp}, props{iProp}) );
            end
        else
            eval( sprintf('objnew(ii).%s = obj(ii).%s;', props{iProp}, props{iProp}) );
        end
    end
end

