function [L,U] = bounds(xL,xU)
if xU-xL >= 2*pi
    L = -1;
    U = 1;
else
    xL = xL + pi/2;
    xU = xU + pi/2;
    n = floor(( (xL + xU)/2/(2*pi)));
    xL = xL - n*2*pi;
    xU = xU - n*2*pi;
    yL = sin(xL);
    yU = sin(xU);
    L = min([yL yU]);
    U = max([yL yU]);
    if (xL<pi/2 & xU>pi/2) |  (xL<-3*pi/2 & xU>-3*pi/2)

    end
end

function inflections = inflection(xL,xU)
if isinf(xL) || isinf(xU)
    inflections = [];
    return
end
r = floor(xU/(pi/2));
t = ceil(xL/(pi/2));
spots = [t:r];
spots = spots(rem(spots,2)~=0);
dir = -double(abs(rem((spots-1)/2,2))==1);
dir(dir==0)=1;
xS = spots*pi/2;
if isempty(xS)
    inflections = [];
else
    xS = [-inf xS];
    dir = [-dir(1) dir];
    inflections = reshape([xS;dir],1,[]);
end

