function L = cotmatrix(V,F)

  ss = size(F,2);
  switch ss
  case 2
    G = grad(V,F);
    A = diag(sparse(edge_lengths(V,F)));
    L = -G'*A*G;
  case 3

    if(size(F,1) == 3)
      warning('F seems to be 3 by #F, it should be #F by 3');
    end
    F = F';

    i1 = F(1,:); i2 = F(2,:); i3 = F(3,:); 
    v1 = V(i3,:) - V(i2,:);  v2 = V(i1,:) - V(i3,:); v3 = V(i2,:) - V(i1,:);
    if size(V,2) == 2
        dblA = abs(v1(:,1).*v2(:,2)-v1(:,2).*v2(:,1));
    elseif size(V,2) == 3

        n  = cross(v1,v2,2); 

        dblA = (sqrt(sum((n').^2)))';
    else 
        error('unsupported vertex dimension %d', size(V,2))
    end
    cot12 = -dot(v1,v2,2)./dblA/2; cot23 = -dot(v2,v3,2)./dblA/2; cot31 = -dot(v3,v1,2)./dblA/2;
    diag1 = -cot12-cot31; diag2 = -cot12-cot23; diag3 = -cot31-cot23;
    i = [i1 i2 i2 i3 i3 i1  i1 i2 i3];
    j = [i2 i1 i3 i2 i1 i3  i1 i2 i3];
    v = [cot12 cot12 cot23 cot23 cot31 cot31 diag1 diag2 diag3];
    L = sparse(i,j,v,size(V,1),size(V,1));
  case 4
    if(size(F,1) == 4 && size(F,2) ~=4)
      warning('F seems to be 4 by #F, it should be #F by 4');
    end
    n = size(V,1);
    C = cotangent(V,F);
    L = sparse(F(:,[2 3 1 4 4 4]),F(:,[3 1 2 1 2 3]),C,n,n);
    L = L + L';
    L = L - diag(sum(L,2));

function [count] = countall3graphlets(L)


n=length(L); % number of nodes
count=zeros(1,4);
w=[1/6, 1/4, 1/2];
for v1=1:n
  for v2=L{v1}
    cardinalities=card_inter(L{v1}, L{v2}, length(L{v1}), length(L{v2}));
    count(1)=count(1)+w(1)*cardinalities(3);
    count(2)=count(2)+w(2)*(cardinalities(1)+cardinalities(2)-2);
    count(3)=count(3)+w(3)*(n-sum(cardinalities));
  end
end
count(4)=n*(n-1)*(n-2)/6-sum(count(1:3));
end

function [n] = card_inter(o_set1, o_set2, l1, l2)
n=zeros(1,3);
i=1; j=1;

while i<=l1 && j <=l2
  if o_set1(i)<o_set2(j) n(1)=n(1)+1; i=i+1;
  else
    if o_set1(i)>o_set2(j) n(2)=n(2)+1; j=j+1;
    else i=i+1; j=j+1; n(3)=n(3)+1;
    end
  end
end
n(1)=n(1)+l1-i+1;
n(2)=n(2)+l2-j+1;
end

