function rvec=round2set(vec, set)
nset=length(set);
nvec=size(vec,1);
rvec=zeros(nvec,1);
for in1=1:nvec
    dval=abs(vec(in1)-set(1));
    val=set(1);
    for in2=1:nset
        if abs(vec(in1)-set(in2))<dval
            val=set(in2);
            dval=abs(vec(in1)-set(in2));
        elseif abs(vec(in1)+set(in2))<dval
            val=-set(in2);
            dval=abs(vec(in1)+set(in2));
        end
    end
    rvec(in1)=val;

