function price = CrankNicolsonFD_BlackScholes_func( S_0, K, r, T, sigma, call, dS, dt, Smax, Smin)
M = round((Smax - Smin)/dS); % grid points
N = round(T/dt); % time steps

dS = (Smax - Smin) / M; % readjust
dt = T / N;  % readjust

vals = zeros(M+1, N+1);
vS = linspace(Smin, Smax, M+1)';
vI = vS / dS;
vJ = 0:N;

if call == 1  % call option
    vals(:, N+1) = max(vS - K, 0);  
    vals(1, :) = 0;
    vals(M+1, :) = Smax - K*exp(-r*dt*(N - vJ)); 
else % put option
    vals(:, N+1) = max(K - vS, 0);  
    vals(1, :) = K*exp(-r*dt*(N - vJ));
    vals(M+1, :) = 0; 
end

a = 0.25 * dt * (sigma^2 *(vI.^2) - r*vI);
b = -dt*0.5*(sigma^2*(vI.^2) + r);
c = 0.25*dt*(sigma^2*(vI.^2) + r*vI);

M1 = -diag(a(3:M), -1) + diag(1 - b(2:M)) - diag(c(2:M-1),1);
[L,U] = lu(M1);
M2 = diag(a(3:M), -1) + diag(1 + b(2:M)) + diag(c(2:M-1),1);

for j = N:-1:1
    vals(2:M,j) = U \\ (L \\ (M2*vals(2:M,j+1)));
end

price = interp1(vS, vals(:,1), S_0);

end

function [CRB, FIM] = crb_uc_sto_1d(design, wavelength, doas, p, noise_var, snapshot_count)
if design.dim ~= 1
    error('1D array expected.');
end
if nargin <= 5
    snapshot_count = 1;
end
m = design.element_count;
k = length(doas);
p = unify_source_power_vector(p, k);
[A, DA] = steering_matrix(design, wavelength, doas);
R = A * bsxfun(@times, p, A') + noise_var * eye(m);
R_inv = eye(m) / R;
R_inv = 0.5 * (R_inv + R_inv');
DRD = DA' * R_inv * DA;
DRA = DA' * R_inv * A;
ARD = A' * R_inv * DA;
ARA = A' * R_inv * A;
PP = p*p';
FIM_tt = 2*real((DRD.' .* ARA + conj(DRA) .* ARD) .* PP);
FIM_pp = real(ARA.' .* ARA);
R_inv2 = R_inv * R_inv;
FIM_ss = real(sum(diag(R_inv2)));
FIM_tp = 2*real(conj(DRA) .* (bsxfun(@times, p, ARA)));
FIM_ts = 2*real(p .* sum(conj(DA) .* (R_inv2 * A), 1)');
FIM_ps = real(sum(conj(A) .* (R_inv2 * A), 1)');
FIM = [...
    FIM_tt  FIM_tp  FIM_ts; ...
    FIM_tp' FIM_pp  FIM_ps; ...
    FIM_ts' FIM_ps' FIM_ss] * snapshot_count;
CRB = eye(2*k+1) / FIM;
CRB = 0.5 * (CRB + CRB');
CRB = CRB(1:k, 1:k);
end

