function transfo = createBasisTransform(source, target)


t1 = eye(3);
t2 = eye(3);

if nargin == 2
    t1(1:2, 1) = source(3:4);
    t1(1:2, 2) = source(5:6);
    t1(1:2, 3) = source(1:2);
else
    target = source;
end

t2(1:2, 1) = target(3:4);
t2(1:2, 2) = target(5:6);
t2(1:2, 3) = target(1:2);

transfo = zeros(3, 3);
maxSz = 1;
for i = 1:maxSz
    po = t1(1:2, 3, i)';
    px = po + t1(1:2, 1, i)';
    py = po + t1(1:2, 2, i)';

    t2i = inv(t2(:,:,i));
    pot = transformPoint(po, t2i);
    pxt = transformPoint(px, t2i);
    pyt = transformPoint(py, t2i);

    vx = pxt - pot;
    vy = pyt - pot;

    transfo(:,:,i) = [vx' vy' pot' ; 0 0 1];
end

function [stat, cellPix, cellMasks] = createCellMasks(stat, Ny, Nx, allow_overlap)

if nargin > 3
    aov = allow_overlap;
else
    aov = 0;
end

Nk = length(stat);
cellPix = zeros(Ny, Nx);
cellMasks = zeros(Nk, Ny, Nx, 'single');
for k = 1:Nk
    ipix = stat(k).ipix(stat(k).isoverlap==0);
    ypix = stat(k).ypix(stat(k).isoverlap==0);
    xpix = stat(k).xpix(stat(k).isoverlap==0);
    lam  = stat(k).lam(stat(k).isoverlap==0);

    stat(k).radius = NaN;
    if ~isempty(ipix)
        params      = FitMVGaus(ypix, xpix, lam, 2);

        stat(k).radius = sqrt(mean(params.eval));
        stat(k).radius = max(3, stat(k).radius);

        cellMasks(k, ipix) = lam / sum(lam);
    else
        stat(k).radius = 0;
    end
    temp        = zeros(Ny, Nx);
    ipix = stat(k).ipix;
    lam  = stat(k).lam;
    temp(ipix)  = lam;

    cellPix = cellPix + (temp > 0);
end

cellPix = min(1, cellPix);

