    So.id    = Si.id;
    So.name  = Si.name;
    So.type  = Si.type;

    So.robot = Si.robot;

    ep = [Si.position;deg2rad(Si.orientationDegrees)];
    EP = diag([Si.positionStd;deg2rad(Si.orientationStd)].^2);

