function [G]=create_SBM(N,q,c,epsi,com_size)


if sum(com_size)~=N
    error('error in create_SBM.m : sum(com_size)~=N!')
end

pin=(q*c)/(N-q+(q-1)*epsi*N);
pout=(q*c*epsi)/(N-q+(q-1)*epsi*N);

rng('shuffle');

I=[]; J=[]; truth=zeros(N,1);
for k=1:q
    truth(sum(com_size(1:k-1))+1:sum(com_size(1:k)))=k;
    Numedgesk=my_binornd(com_size(k).*(com_size(k)-1)/2,pin); %normal approx
    while Numedgesk>com_size(k).*(com_size(k)-1)/2
        Numedgesk=my_binornd(com_size(k).*(com_size(k)-1)/2,pin); %normal approx
    end
    edges = randperm(com_size(k).*(com_size(k)-1)/2,Numedgesk);
    [Inew, Jnew] = ind2sub4up(edges);
    I=[I;Inew+sum(com_size(1:k-1))];
    J=[J;Jnew+sum(com_size(1:k-1))];
end


for k=1:q-1
    Numedgesk=my_binornd(com_size(k)*sum(com_size(k+1:end)),pout); %normal approx
    edges = randperm(com_size(k)*sum(com_size(k+1:end)),Numedgesk);
    [Inew, Jnew] = ind2sub([com_size(k),sum(com_size(k+1:end))],edges);
    I=[I;Inew'+sum(com_size(1:k-1))];
    J=[J;Jnew'+sum(com_size(1:k))];
end

A=sparse(I,J,1,N,N);
A=A+A';

function [p_sdpknapsackcuts,p_binarycut,p_lp_contcut] = create_sdpknapsack_cuts(p,x_trial,poriginal,upper)

p_sdpknapsackcuts = emptyNumericalModel;
p_binarycut = emptyNumericalModel;
p_sdpcuts = emptyNumericalModel;
x_trial(x_trial < p.lb) = p.lb(x_trial < p.lb);
x_trial(x_trial > p.ub) = p.ub(x_trial > p.ub);

for sdpcount = 1:length(p.K.s)
    ptemp = emptyNumericalModel;
    ptemp.options = p.options;   
    [X,p_lp_contcut] = add_one_sdp_cut(p,ptemp,x_trial,sdpcount,p);
    if ~isempty(p_lp_contcut.F_struc)
        for j = 1:p_lp_contcut.K.l
            row = p_lp_contcut.F_struc(j,:);
            row = fix_continuous_in_row_at_best_possible(row,poriginal,upper);                        
            row(1) = row(1) + 1e-8; 
             if all(row(2:end) >= 0) && row(1) < 0
                 row(2:end) = min(row(2:end),-row(1));
             end
             used = find(row(2:end));
             if all(p.isbinary(used)) && all(row(2:end)==round(row(2:end)))
                 row(1) = floor(row(1));
             end
            p_binarycut = addInequality(p_binarycut,row);

            cut = knapsack_create_cover_cut(-row(2:end),row(1),x_trial,'gu');
            cut2 = knapsack_cheapcut(row);            
            ptemp.F_struc = [ptemp.F_struc;cut;cut2];
            ptemp.K.l = ptemp.K.l + size(cut,1)+size(cut2,1);            
        end
        if ptemp.K.l>0
            p_sdpknapsackcuts = addInequality(p_sdpknapsackcuts,ptemp.F_struc);           
        end
    end
end

function create_setup_files(diff_parameter_names, diff_parameter_values, setup, setup_name, level, folder_setup_files)

    if ~exist(folder_setup_files, 'dir')
        mkdir(folder_setup_files);
    end

    if level > length(diff_parameter_names)
        setup_name = strrep(setup_name, '.', '-');
        if isempty(setup_name) 
            setup_name = 'default';
        end
        setup.setup_name = setup_name;
        WriteYaml(strcat(folder_setup_files, '/', setup.setup_name, '.yaml'), setup);
    else
        values = diff_parameter_values{level};
        for i = 1:length(values)
            if iscell(values)
                value = values{i};
            else
                value = values(i);
            end
            parameter_name = diff_parameter_names(level);
            setup.(parameter_name{1}) = value;
            if isempty(setup_name)
                new_setup_name = num2str(value);
            else
                new_setup_name = strcat(setup_name, '_', num2str(value));
            end
            create_setup_files(diff_parameter_names, diff_parameter_values, setup, new_setup_name, level+1, folder_setup_files)
        end
    end
end

