function [OUT, W] = CrossWeightAverage(DATA,WEIGHT)



[r1, c1] = size(DATA);
[r2, c2] = size(WEIGHT);
if r2==1 && c2==c1 
    aux = [];
    for ii=1:r1
        aux = [aux; WEIGHT];
    end
    WEIGHT = aux;
end

[r1, c1] = size(DATA);
[r2, c2] = size(WEIGHT);
if r1~=r2 || c1~=c2
    disp(' ')
    disp('The matrices of data and weights are not conformable.')
    return
end

[nobs, nvars] = size(DATA);
nans = isnan(DATA);
WEIGHT(nans) = NaN;

OUT(1:nobs,1) = NaN;
W(1:nobs,1:nvars) = NaN;

for ii=1:nobs
    aux_weight = WEIGHT(ii,:)./nansum(WEIGHT(ii,:));
    W(ii,:) = aux_weight;
    aux_weight(nans(ii,:)) = 0;
    DATA(ii,nans(ii,:)) = 0;
    if sum(nans(ii,:))==nvars
        OUT(ii,1) = NaN;
    else
        OUT(ii,1) = DATA(ii,:) * aux_weight';
    end
end

function varargout = cross_corr(z, x, c, der_y)


if nargin < 4
    der_y = [];
end

z_sz = size_min_ndims(z, 4);
x_sz = size_min_ndims(x, 4);
assert(all(z_sz(1:2) <= x_sz(1:2)), 'exemplar z has to be smaller than instance x');

r_sz = [x_sz(1:2) - z_sz(1:2) + 1, 1, x_sz(4)];
x_ = reshape(x, [x_sz(1:2), prod(x_sz(3:4)), 1]);

if isempty(der_y)
    r_ = vl_nnconv(x_, z, []);
    assert(isequal(size_min_ndims(r_, 4), [r_sz(1:2), r_sz(4), 1]));
    r = reshape(r_, r_sz);
    if isempty(c)
        y = r;
    else
        y = bsxfun(@plus, r, c);
    end
    varargout = {y};
else
    der_r = der_y;
    if ~isempty(c)
        der_c = sum(sum(der_y, 1), 2);
    end
    der_r_ = reshape(der_r, [r_sz(1:2), r_sz(4), 1]);
    [der_x_, der_z] = vl_nnconv(x_, z, [], der_r_);
    der_x = reshape(der_x_, x_sz);
    if isempty(c)
        varargout = {der_z, der_x};
    else
        varargout = {der_z, der_x, der_c};
    end
end

end

