function frontiers_picked = crowding_pick(archive, picks, mode)


if numel(archive) < picks
    frontiers_picked = archive;
else
    O = normalize([archive.objs]);
    if strcmp(mode, 'precise')
        index_pick = true(1, numel(archive));
        while numel(find(index_pick == true)) > picks % Optimizable
            CD = NaN(1, numel(archive));
            CD(index_pick) = crowding_dist(O);
            [~, index] = min(CD);
            index_pick(index) = false;
            O = normalization([archive(index_pick).objs]);
        end
        frontiers_picked = archive(index_pick);
    elseif strcmp(mode, 'fast')
        CD = crowding_dist(O);
        [~, I] = sort(CD, 'descend');
        frontiers_picked = archive(I(1: picks));
    end

function f = crowd_distance(population,Nvar,Nfun)


K = Nvar+Nfun;


max_rank = max(population(K+1,1,:));

previous_index=0;
for i=1:max_rank
    current_index = max(find(population(K+1,1,:)==i));

    temp_pop = population(:,:,previous_index+1:current_index);

    for j=1:Nfun
        [~,index_obj] = sort(temp_pop(Nvar+j,1,:));

        sorted_based_objective = [];
        for k=1:length(index_obj)
            sorted_based_objective(:,:,k) = temp_pop(:,:,index_obj(k));
        end

        fmax = sorted_based_objective(Nvar+j,1,length(index_obj));
        fmin = sorted_based_objective(Nvar+j,1,1);

        temp_pop(K+1+j,1,index_obj(length(index_obj))) = Inf;
        temp_pop(K+1+j,1,index_obj(1)) = Inf;

        for k=2:length(index_obj)-1
            next_obj = sorted_based_objective(Nvar+j,1,k+1);
            previous_obj = sorted_based_objective(Nvar+j,1,k-1);
            if (fmax - fmin == 0)
                temp_pop(K+1+j,1,index_obj(k)) = Inf;
            else
                temp_pop(K+1+j,1,index_obj(k)) = 100*(next_obj - previous_obj)/(fmax - fmin);
            end
        end
    end
    distance = zeros(1,1,current_index);
    for j = 1:Nfun
        distance(1,1,:) = distance(1,1,:) + temp_pop(K+1+j,1,:);
    end
    temp_pop(K+3,1,:) = distance;
    y = temp_pop;%(K+3,1,:);
    z(:,:,previous_index+1:current_index) = y;
end
f = z();

function [Chrom, Lind, BaseV] = crtbp(Nind, Lind, Base)
nargs = nargin ;


if nargs >= 1, [mN, nN] = size(Nind) ; end
if nargs >= 2, [mL, nL] = size(Lind) ; end
if nargs == 3, [mB, nB] = size(Base) ; end

if nN == 2
   if (nargs == 1) 
      Lind = Nind(2) ; Nind = Nind(1) ; BaseV = crtbase(Lind) ;
   elseif (nargs == 2 & nL == 1) 
      BaseV = crtbase(Nind(2),Lind) ; Lind = Nind(2) ; Nind = Nind(1) ; 
   elseif (nargs == 2 & nL > 1) 
      if Lind ~= length(Lind), error('Lind and Base disagree'); end
      BaseV = Lind ; Lind = Nind(2) ; Nind = Nind(1) ; 
   end
elseif nN == 1
   if nargs == 2
      if nL == 1, BaseV = crtbase(Lind) ;
      else, BaseV = Lind ; Lind = nL ; end
   elseif nargs == 3
      if nB == 1, BaseV = crtbase(Lind,Base) ; 
      elseif nB ~= Lind, error('Lind and Base disagree') ; 
      else BaseV = Base ; end
   end
else
   error('Input parameters inconsistent') ;
end

function [CE,PC] = crust(P)
  dim = size(P,2);
  switch dim
  case 3
    Tri = delaunayTriangulation(P);
    [VV,VR] = Tri.voronoiDiagram;
    n = size(P,1);
    I = zeros(n,2);

    counts = cellfun(@(r) numel(r),VR);
    J = cumsum([1;sparse(cumsum(counts),1,1)])';
    J = J(1:end-1);
    VRA = [VR{:}];
    U = VV(VRA,:) - P(J,:);
    D = normrow(U);
    S = sparse(VRA,J,D,size(VV,1),size(P,1));
    [~,I(:,1)] = max(S);
    Y = VV(I(:,1),:)-P;
    D = sign(sum(U.*Y(J,:),2)).*D;
    S = sparse(VRA,J,D,size(VV,1),size(P,1));
    [~,I(:,2)] = minnz(S);

    I = unique(I(:));
    C = VV(I,:);
    C = C(~any(isnan(C)|isinf(C),2),:);
    PC = [P;C];
    Tri = delaunayTriangulation(PC);
    FF = Tri.ConnectivityList;
    E = [ ...
      FF(:,[4 2 3]); ...
      FF(:,[3 1 4]); ...
      FF(:,[2 4 1]); ...
      FF(:,[1 3 2])];
    E = unique(sort(E,2),'rows');
    CE = E(all(E<=size(P,1),2),:);

