function K = curvature_2D_diff(x,y)


niter = 5;
begx = x(1); endx = x(end);
begy = y(1); endy = y(end);
for ii=1:niter
    x = filter2([1/4;1/2;1/4],x(:),'valid')';
    y = filter2([1/4;1/2;1/4],y(:),'valid')';
    x = [begx,x,endx];
    y = [begy,y,endy];
end



dx = compute_diff(x);
dy = compute_diff(y);

s = sqrt( dx.^2 + dy.^2 );
dx = dx./s; dy = dy./s; 
p = length(dx);
K = zeros(p,1);
for k=1:p
    if k>1 && k<p
        K(k) = dx(k-1)*dx(k+1)+dy(k-1)*dy(k+1);
    elseif k==1
        K(k) = dx(k)*dx(k+1)+dy(k)*dy(k+1);
    elseif k==p
        K(k) = dx(k-1)*dx(k)+dy(k-1)*dy(k);
    end
end

function dx = compute_diff(x)


h = 1; % step size
D1 = [x(2:end),x(end)];
D2 = [x(1),x(1:end-1)];
dx = (D1-D2)/(2*h); 
dx(1) = ( 4*x(2) - 3*x(1) - x(3) )/(2*h);
dx(end) = -( 4*x(end-1) - 3*x(end) - x(end-2) )/(2*h);

end %  function

end %  function

