                    s.levelSet          = cParams.levelSet;
                    c = CutMeshProvisionalLine(s);
                case {'TRIANGLE','TETRAHEDRA'}
                    s.backgroundMesh = bCutMesh;
                    s.cutCells       = cParams.cutCells;
                    s.levelSet       = cParams.levelSet;
                    c = CutMeshComputerProvisional(s);

                case 'QUAD'
                    s.backgroundMesh    = bCutMesh;
                    s.cutCells          = cParams.cutCells;
                    s.levelSet          = cParams.levelSet;
                    s.lastNode          = max(cParams.backgroundMesh.connec(:));
                    c = CutMeshProvisionalQuadrilater(s);
                otherwise
                    s.backgroundMesh    = bCutMesh;
                    s.cutCells          = cParams.cutCells;
                    s.levelSet          = cParams.levelSet;
                    c = CutMeshProvisionalOthers(s);
            end

            nAllEdges = size(obj.isEdgeCut,1);
            cutPoint = zeros(nAllEdges,1);
            cutPoint(obj.isEdgeCut) = 1:obj.nCutEdges;
            edgeCutPoint = zeros(obj.nElem,obj.all2Cut.nCutEdgeByElem);
            for iedge = 1:obj.all2Cut.nCutEdgeByElem
                edge = cEdgeInElem(:,iedge);
                edgeCutPoint(:,iedge) = cutPoint(edge);
            end
            obj.edgeCutPointInElem = edgeCutPoint;
        end

        function computeAllNodesInElem(obj)
            edge = obj.edgeCutPointInElem;
            s = obj.allNodesinElemParams;
            s.firstCutEdge = edge;
            aComputer = AllNodesInElemComputer(s);
            aComputer.compute();
            obj.allNodesInElem = aComputer.allNodesInElem;
            obj.cutNodesInElem = aComputer.cutNodesInElem;
        end

        function computeXallNodesInElemAndXcut(obj)
            s = obj.allNodesInElemCoordParams;
            s.all2Cut               = obj.all2Cut;
            s.edgeCutPointInElem    = obj.edgeCutPointInElem;
            a = AllNodesInElemCoordinatesComputer(s);
            a.compute();
            obj.xAllNodesInElem = a.xAllNodesInElem;
            obj.xCutInElem = a.xCutInElem;
            obj.nodesInCutEdges = a.nodesInCutEdges;
        end

    end

end

function MimgR = cutZstack(Mimg, A, Ly, Lx, zspread)

[Ny Nx Nz] = size(Mimg);

[Y X]      = ndgrid([1:Ly], [1:Lx]);

yxz        = round(A * [Y(:)'; X(:)'; ones(1, numel(Y))]);
yxz        = yxz';
yxz        = min(yxz, repmat(size(Mimg), size(yxz,1), 1));
yxz        = max(1, yxz);

if nargin > 4
    minZ   = min(yxz(:,3));
    maxZ   = max(yxz(:,3));
    MimgR  = NaN*zeros(Ly, Lx, 2*zspread + 1);
    zinds  = [-1*zspread + max(0, zspread-minZ + 1) : zspread - max(0, (maxZ+zspread)-Nz)];
    for j = [1:length(zinds)]
        zval = zinds(j) + yxz(:,3);
        ipix = sub2ind([Ny Nx Nz], yxz(:,1), yxz(:,2), zval);
        MimgR(:,:, j + max(0,zspread-minZ+1)) = reshape(Mimg(ipix), Ly, Lx);
    end
else
    ipix       = sub2ind([Ny Nx Nz], yxz(:,1), yxz(:,2), yxz(:,3));
    MimgR      = reshape(Mimg(ipix), Ly, Lx);
end

