    theta = [repmat(theta(1),1,n)  theta(2)];
elseif  lt ~= n+1
    error(sprintf('Length of theta must be 2 or %d',n+1))
else
    theta = theta(:).';
end

pow = theta(end);   tt = repmat(-theta(1:n), m, 1);
td = abs(d).^pow .* tt;
r = exp(sum(td,2));

if  nargout > 1
    dr = pow  * tt .* sign(d) .* (abs(d) .^ (pow-1)) .* repmat(r,1,n);
end

return

