    Id=dct2(x);
    temp{k}=idct2(Id(1:arow,1:acol)); %% Approximate Coeff. is stored in First Cell.
    xwt=temp{k};
    k=k+1;
    for i = 1:nlevel
        rr=arow*2^(i-1);
        cc=acol*2^(i-1);
        temp{k}=idct2(Id(1:rr,cc+1:2*cc)); %% Vertical
        temp{k+1}=idct2(Id(rr+1:2*rr,1:cc)); %% Horizontal
