        xwt=[xwt temp{k}; temp{k+1} temp{k+2}];
        k=k+3;
    end
    c=xwt;
    len=size(temp,2);
    for i=1:len
        C{i}=temp{len-i+1}; %% Now Approximate Coeff. is stored in Last Cell.
    end

else
    k=size(x,2);

