classdef Derivative < Algorithm

    properties (Access = public)    
        order = 1;
        delta = 1;
        inPlaceComputation = true;
    end

    methods (Access = public)
        function obj = Derivative(order, delta)
            if nargin > 0
                obj.order = order;
                if nargin > 1
                    obj.delta = delta;
                end
            end
            obj.name = 'derivative';
            obj.inputPort = DataType.kSignal;
            obj.outputPort = DataType.kSignal;
        end

        function derivative = compute(obj, data)
            if size(data,1) == 1
                derivative = data;
            else
                if obj.order == 1
                    derivative = obj.computeFirstOrderDerivative(data);
                elseif obj.order == 2
                    derivative = obj.computeSecondOrderDerivative(data);
                else
                    derivative = [];
                end
            end
        end

        function derivative = computeFirstOrderDerivative(obj,data)
            n = length(data);
            derivative = zeros(n,1);
            for i = 2 : n
                derivative(i) = (data(i) - data(i-1)) / obj.delta;
            end
        end

