function cliques = derivecliques(a,b)

a = a(:)';
[a_,index] = sort(a,'ascend');
if a_(end-1)+a_(end) <= b
    cliques = {};
else
    j = 1;
    n = length(a);
    while 1
        if a_(j)+a_(j+1) > b
            break
        end
        j = j+1;
    end
    cliquestart = j;
    cliques{1} = sort(index(cliquestart:end));    
    for outside = 1:j-1
        for k = cliquestart:n
            if a_(outside) + a_(k) > b
                cliques{end+1} = sort([index(outside) index(k:end)]);
                break
            end
        end
    end
end

