function detection = detectAtMultipleScales(im, w, hogCellSize, scales)

modelWidth = size(w, 2) ;
modelHeight = size(w, 1) ;
bestScore = -inf ;
minScore = +inf ;
maxScore = -inf ;
h = [] ;

for s = scales
  t = imresize(im, 1/s) ;

  hog = vl_hog(t, hogCellSize) ;

  scores = vl_nnconv(hog, w, []) ;

  [score, index] = max(scores(:)) ;
  if score > bestScore
    bestScore = score ;
    [hy, hx] = ind2sub(size(scores), index) ;
    x = (hx - 1) * hogCellSize * s + 1 ;
    y = (hy - 1) * hogCellSize * s + 1 ;
    detection = [
      x - 0.5 ;
      y - 0.5 ;
      x + hogCellSize * modelWidth * s - 0.5 ;
      y + hogCellSize * modelHeight * s - 0.5 ;] ;
  end

  vl_tightsubplot(numel(scales),find(s==scales)) ;
  imagesc(scores) ; axis off square ;
  h(end+1) = gca;
  minScore = min([minScore;scores(:)]) ;
  maxScore = max([maxScore;scores(:)]) ;
end

function [ cycleCount, pathsList, cycleBlocks ] = detectCycles( connMatrix )

try
    cycleCount = 0;
    accessMatrix = connMatrix;
    stepCount = 1;
    cycleBlocks = [];
    numOfNodes = length(connMatrix);
    pathsList = cell(numOfNodes, 0);

    while ~isempty(find(accessMatrix, 1)) && stepCount < numOfNodes
        pathsList{stepCount} = accessMatrix;
        for m = 1:length(connMatrix)
            if accessMatrix(m, m) > 0 && isempty(find(cycleBlocks == m, 1))
                fprintf('! Detected cycle from %d to itself in %d steps\\n', m, stepCount);
                cycleCount = cycleCount + 1;
                cycleBlocks = [cycleBlocks, m];
                break;
            end
        end
        stepCount = stepCount + 1;
        accessMatrix = connMatrix^stepCount;
    end
    if stepCount < numOfNodes
        pathsList(stepCount + 1:end) = [];

