function p = detect_quadratic_disjoints_generalized(p)

p.quadraticdisjoints = [];
if any(p.K.l)
    top = startofLPCone(p.K);
    for i = 1:p.K.l
        row = p.F_struc(top,:);
        if row(1)<0
            [Q, c] =  compileQuadratic(row(2:end),p,0); 
            Q = -Q;
            c = -c;
            if ~any(c)
                used = find(any(Q,2));
                Q = Q(used,used);
                if ~(min(eig(Q))>=0)
                    for r = 1:length(used)
                        s = -row(1);
                        k = -Q(r,r);
                        a = Q(:,r);
                        a(r,:) = [];
                        Qsub=Q;Qsub(r,:)=[];Qsub(:,r)=[];
                        if min(eig(Qsub))>0
                            w = sqrt(s/(k+a'*inv(Qsub)*a));
                            p.quadraticdisjoints = [p.quadraticdisjoints [used(r);(w);-(w)]];
                        end
                    end
                end

function p = detect_sdpmonotonicity(p)
p.sdpmonotinicity = [];
if p.options.cutsdp.nodefix && (p.K.s(1)>0)
    top = startofSDPCone(p.K);
    for i=1:length(p.K.s)
        n=p.K.s(i);
        for j=1:size(p.F_struc,2)-1
            X=full(reshape(p.F_struc(top:top+n^2-1,j+1),p.K.s(i),p.K.s(i)));
            X=(X+X')/2;
            v=real(eig(X+sqrt(eps)*eye(length(X))));
            if all(v>=0)
                sdpmonotinicity(i,j)=-1;
            elseif all(v<=0)
                sdpmonotinicity(i,j)=1;
            else
                sdpmonotinicity(i,j)=nan;
            end
        end
        top=top+n^2;
    end
else
    sdpmonotinicity=[];
end

