            if ~isempty(obj.BhatSeq)
               BhatSeq = obj.BhatSeq;
               blkB = blkdiag(BhatSeq{:}, zeros(size(Bhat)));
            else
               blkB = blkdiag(kron(eye(T), Bhat), zeros(size(Bhat)));
            end

			Id = eye((T + 1)*n);
            if opt.keepAffine
                constr = [constr, (Id - Z*blkA)*Phi_x - Z*blkB*Phi_u == Id];

