function Y = coldwtfilt(X, h, offset)

[r,c] = size(X);
if rem(r,2) > 0
   error('No of rows in X must be a multiple of 2!');
end

m = length(h);
m2 = fix(m/2);

if any(X(:))
   if rem(m,2),  % Odd length h.
      xe = reflect([(1-m2):(r+m2)], 1, r); % Use 'reflect' so r < m2 works OK.
      t1 = [1:2:(r+m-2)] + offset; 
      t2 = [2:2:(r+m-3)] + offset;
   else          % Even length h.
      xe = reflect([(1-m2):(r+m2)], 0.5, r+0.5); % Use 'reflect' so r < m2 works OK.
      t2 = 2:2:(r+m-2); 
      t1 = 3:2:(r+m-1);
   end 

   ho = h(1:2:m); 
   he = h(2:2:m);

   Y = conv2(X(xe(t1),:),ho(:),'valid') + conv2(X(xe(t2),:),he(:),'valid');
else
   Y = zeros(r/2,c);
end

function Y = colifilt(X, ha, hb)


[r,c] = size(X);
if rem(r,2) > 0
   error('No of rows in X must be a multiple of 2!');
end

m = length(ha);
if m ~= length(hb)
   error('Lengths of ha and hb must be the same!');
end

if rem(m,2) > 0
   error('Lengths of ha and hb must be even!');
end
m2 = fix(m/2);

Y = zeros(r*2,c);
if ~any(X(:)), return; end

if rem(m2,2) == 0,

   xe = reflect([(1-m2):(r+m2)], 0.5, r+0.5); % Use 'reflect' so r < m2 works OK.


   t = [4:2:(r+m)];
   if sum(ha.*hb) > 0,
      ta = t; tb = t - 1;
   else
      ta = t - 1; tb = t;
   end

   hao = ha(1:2:m);
   hae = ha(2:2:m);
   hbo = hb(1:2:m);
   hbe = hb(2:2:m);

   s = 1:4:(r*2);

   Y(s,:)   = conv2(X(xe(tb-2),:),hae(:),'valid');
   Y(s+1,:) = conv2(X(xe(ta-2),:),hbe(:),'valid');
   Y(s+2,:) = conv2(X(xe(tb),:),hao(:),'valid');
   Y(s+3,:) = conv2(X(xe(ta),:),hbo(:),'valid');

function Y = coliwtfilt(X, h, offset)

[r,c] = size(X);
m = length(h);
m2 = fix(m/2);

Y = zeros(r*2,c);

if any(X(:))
   if rem(m,2),  % Odd length h.
      m4 = fix((m+1)/4);
      if offset
         xe = reflect([(1-m4):(r+m4)], 0.5, r);
         if rem(m2,2)
            h1 = h(1:2:m); h2 = h(2:2:m);
            t1 = 1:(r+m2); t2 = 2:(r+m2);
         else
            h1 = h(2:2:m); h2 = h(1:2:m);
            t1 = 1:(r+m2-1); t2 = 1:(r+m2);
         end
      else
         xe = reflect([(1-m4):(r+m4)], 1, r+0.5);
         if rem(m2,2)
            h1 = h(2:2:m); h2 = h(1:2:m);
            t1 = 2:(r+m2); t2 = 2:(r+m2+1);
         else
            h1 = h(1:2:m); h2 = h(2:2:m);
            t1 = 1:(r+m2); t2 = 2:(r+m2);
         end
      end
   else          % Even length h.
      m4 = fix(m/4);
      xe = reflect([(1-m4):(r+m4)], 0.5, r+0.5);
      if rem(m2,2)
         h1 = h(1:2:m); h2 = h(2:2:m);
         t1 = 1:(r+m2-1); t2 = t1;
      else
         h1 = h(2:2:m); h2 = h(1:2:m);
         t1 = 1:(r+m2-1); t2 = 2:(r+m2);
      end
   end 

   s = 1:2:(r*2);
   Y(s,:) = conv2(X(xe(t1),:),h1(:),'valid');
   Y(s+1,:) = conv2(X(xe(t2),:),h2(:),'valid');
end
return;

function [vertices, faces] = collapseEdgesWithManyFaces(vertices, faces, varargin)


verbose = false;
while length(varargin) > 1 && ischar(varargin{1})
    name = varargin{1};
    if strcmpi(name, 'verbose')
        verbose = varargin{2};
    else
        error(['Unknown optional argument: ' name]);
    end
    varargin(1:2) = [];
end

while true
    edges = meshEdges(faces);

    edgeFaces = trimeshEdgeFaces(faces);
    edgeFaceDegrees = sum(edgeFaces > 0, 2);

    inds = find(edgeFaceDegrees > 2);

    if isempty(inds)
        break;
    end

    edge = edges(inds(1), :);
    if verbose
        fprintf('remove edge with index %d: (%d, %d)\\n', inds(1), edge);
    end
    [vertices, faces] = mergeMeshVertices(vertices, faces, edge);
end

[vertices, faces] = trimMesh(vertices, faces);

