    pos_colon = regexp(str_rec,':*');
    for p = 1 : numel(pos_colon)
        id_before = find(pos_ids(:) < pos_colon(p), 1, 'last');
        id_after = find(pos_ids(:) > pos_colon(p), 1, 'first');
