function createOrthotropicConstitutiveTensor(obj)
    C = zeros(3,3);
    C(1,1) = rand(1,1);
    C(2,2) = rand(1,1);

    C(1,1) = 1;
    C(2,2) = 1;
    C(1,2) = nu;
    C(2,1) = C(1,2);
    C(3,3) = (1-nu)/2;
    C = E*C;
    obj.Ctensor = C;
end

function computeConstitutiveCoeficient(obj)
    C = obj.Ctensor;
    C11 = C(1,1);
    C22 = C(2,2);
    C12 = C(1,2);
    C66 = C(3,3);
    obj.coef = (C11 - C22)/((C11+C22)-2*(C12 + 2*C66));
end

