        t = scenario.getTime() ;
        i = scenario.getIndex() ;
        if t == 1
            cntr = x([1 4 8]) >= 0 ;
            obj = sum(x([1 4 8])) ;
        elseif t == 2
            if i == 1
                cntr = sum(x([2 9 10])) <= x(4) ;
            elseif i == 2
                cntr = sum(x([2 9 10])) <= 2*x(4) ;
            end
