                cntr = z <= x ;
                obj = z ;
            end                                        
        end
    end
    function [cntr, obj] = nlds3(scenario)
        t = scenario.getTime() ;
        i = scenario.getIndex() ;
        if t == 1
            cntr = x >= 0 ;
            obj = x ;
        elseif t == 2
            if i == 1
                cntr = [y <= x ; ...
