function M = ComputeApproxMarginalsBP(F,E)


    clusterGraph = CreateClusterGraph(F,E);

    P = ClusterGraphCalibrate(clusterGraph);

    N = unique([P.clusterList(:).var]);

    M = repmat(struct('var', 0, 'card', 0, 'val', []), length(N), 1);

    for i = 1:length(N),

	indx = FindPotentialWithVariable(P,N(i));
	V = setdiff(P.clusterList(indx).var,N(i));
	M(i) = FactorMarginalization(P.clusterList(indx),V);
	M(i).val = M(i).val/sum(M(i).val);
    end



return;

function indx = FindPotentialWithVariable(P, V)

indx = 0;
for i = 1:length(P.clusterList),
    if (any(P.clusterList(i).var == V)),
        indx = i;
        return;
    end;
end;

return;

function ri = computeARI(c1, c2)
if length(c1)~=numel(c1)
	c1 = c1(:);
end
if length(c2)~=numel(c2)
    c2 = c2(:);
end

N = length(c1);
[~, ~, c1] = unique(c1);
N1 = max(c1);
[~, ~, c2] = unique(c2);
N2 = max(c2);

for i=1:1:N1
    for j=1:1:N2
        G1 = find(c1==i);
        G2 = find(c2==j);
        n(i,j) = length(intersect(G1,G2));
    end
end

ssm = 0;
sm1 = 0;
sm2 = 0;
for i=1:1:N1
    for j=1:1:N2
        ssm = ssm + nchoosek2(n(i,j),2);
    end
end
