    assert (varsList(i) == i);
    if (i == 1)
        clique = PCalibrated.cliqueList(i);
        M(i) = FactorMarginalization(clique, 2);
    else
        clique = PCalibrated.cliqueList(i-1);
        M(i) = FactorMarginalization(clique, i-1);
    end

