function J = computeJGJacobian (qR, qS, returnStructureOnly, auxdata)
  [K C f Rv Rf Sv Sf NS d] = deal(auxdata{:});

  nr  = length(Rv);  % The number of large regions.
  ns  = length(Sv);  % The number of small regions.
  nqr = length(qR);  % The number of variables associated with the
  nqs = length(qS);  % The number of variables associated with the

  qR = reshapemarginals(qR,Rv,K);
  qS = reshapemarginals(qS,Sv,K);

  rows = zeros(1,nqr);
  is   = 0;
  for r = 1:nr
    tablesize = numel(qR{r});
    is        = is(end) + (1:tablesize);
    rows(is)  = r;
  end
  JR = sparse(rows,1:nqr,ones(1,nqr),nr,nqr);

  rows = zeros(1,nqs);
  is   = 0;
  for s = 1:ns
    tablesize = numel(qS{s});
    is        = is(end) + (1:tablesize);
    rows(is)  = s;
  end
  JS = sparse(rows,1:nqs,ones(1,nqs),ns,nqs);

  JCS = cell(1,ns);
  for s = 1:ns
    w      = numel(qS{s});  % The width of the Jacobian subblock.
    h      = d(s) * w;      % The height of the Jacobian subblock.
    cols   = repmat(1:w,1,d(s));
    JCS{s} = sparse(1:h,cols,-ones(1,h),h,w);
  end

  JCR = cell(sum(d),1);
  t   = 1;  % The row of the current subblock.
  for s = 1:ns
    for r = NS{s}
      h      = numel(qS{s});  % The height of the Jacobian subblock.
      w      = numel(qR{r});  % The width of the Jacobian subblock.
      rows   = multiplyfactors(ones([K(Rv{r}) 1]),Rv{r},...
                               reshape(1:h,[K(Sv{s}) 1]),Sv{s});
      JCR{t} = sparse(rows(:)',1:w,ones(1,w),h,w);
      t      = t + 1;         % Move to the next row.
    end
  end

function F = computeJGObjective (qR, qS, auxdata)
  [K C f Rv Rf Sv Sf NS d] = deal(auxdata{:});

  qR = reshapemarginals(qR,Rv,K);
  qS = reshapemarginals(qS,Sv,K);

  F = computefreeenergy(C,f,Rv,Rf,Sv,Sf,qR,qS,d);

function F = computefreeenergy (C, f, Rv, Rf, Sv, Sf, qR, qS, d)
  nr = length(Rv);   % The number of large regions.
  ns = length(Sv);   % The number of small regions.
  F  = 0;            % The return value.

  for r = 1:nr
    for j = Rf{r}
      table = multiplyfactors(qR{r},Rv{r},log(f{j}),C{j});
      F     = F - sum(table(:));
    end
  end

  for s = 1:ns
    for j = Sf{s}
      table = multiplyfactors(qS{s},Sv{s},log(f{j}),C{j});
      F     = F - (1 - d(s)) * sum(table(:));
    end
  end

  for r = 1:nr
    table = qR{r} .* log(qR{r});
    F     = F + sum(table(:));
  end

  for s = 1:ns
    table = qS{s} .* log(qS{s});
    F     = F + (1 - d(s)) * sum(table(:));
  end

function [ KCcorrection, phi_ssa ] = computeKCcorrection( PSD )


PSD  = PSD(:);
PSD = PSD(PSD ~= 0);
nPSD = length(PSD);

for iPSD = 2:nPSD
    r1 = PSD(iPSD-1);
    r2 = PSD(iPSD);
    saSlice(iPSD-1) = pi.*(r2 + r1).*sqrt((r2-r1).^2 + 1^2);
end

pv = pi.*sum(PSD.^2);       % Pore volume
sa = sum(saSlice);          % Surface Area

phi_ssa = pv/sa;            % Pore volume/Surface area ratio

rH = 2.*pv./sa;

rC = sqrt(sum(PSD.^2)/nPSD);

rA = sqrt(rH.*rC);


permTheo = nPSD./(sum(1./PSD.^4));
permKC = (rA).^4;

KCcorrection = permTheo./permKC;


end

