function [ SCDs, SCDKernel ] = ComputeSCDs( Histograms, r )


if nargin < 2 || isempty(r)
    r = 1;
end

if r > 0
    rowHistograms = double(cat(1, Histograms{:}));

    H = mean(rowHistograms, 1);
    [E, ~] = eig(cov(rowHistograms));

    SCDKernel = struct('H', H, 'E', E(:, end:-1:(end-r+1)));

    SCDs = cellfun(@(x) bsxfun(@minus,double(x),SCDKernel.H)*SCDKernel.E, Histograms, 'UniformOutput', false);
else
    SCDs = {};
    SCDKernel = [];
end

end

function [featMap, featChnMaps, nFilters] = computeSelectedFeaturesMap(detector)


wl_weights = detector.clf.wl_weights;
wl_weights = wl_weights ./ sum(wl_weights);
wl_weights = repmat(wl_weights(:)', size(detector.clf.fids,1), 1);

chnSizes  = detector.opts.modelDsPad / detector.opts.pPyramid.pChns.shrink;
nFilters = 1;
if (isfield(detector.opts, 'filters'))
  if (~isempty(detector.opts.filters))
    nFilters = size(detector.opts.filters,4);
    chnSizes = floor(chnSizes / 2);
  end
end
chnLength = chnSizes(1)*chnSizes(2);
nChns = 0;
for i=1:length(detector.info)
  nChns = nChns + detector.info(i).nChns;
end


fids = detector.clf.fids(detector.clf.fids > 0);
wl_weights = wl_weights(detector.clf.fids > 0);

featMap = zeros(chnSizes);
for i=1:length(fids)
  id = mod(double(fids(i)-1),chnLength)+1;
  featMap(id) = featMap(id) + wl_weights(i); 
end

featChnMaps = cell(nChns*nFilters, 1);
thOld = 1;
for c=1:nChns*nFilters
  th = c*chnLength;
  chnFids = fids((fids>thOld) & (fids<=th));
  chnWeights = wl_weights((fids>thOld) & (fids<=th));
  chnWeights = chnWeights ./ sum(chnWeights);
  featMapAux = zeros(chnSizes);
  for i=1:length(chnFids)
    id = mod(double(chnFids(i)-1),chnLength)+1;
    featMapAux(id) = featMapAux(id) + chnWeights(i); 
  end  
  featChnMaps{c} = featMapAux;
  thOld = th;
end

function [] = computeSentRepresentations(modelFile, outputFile,varargin)

  addpath(genpath(sprintf('%s/..', pwd)));

  p = inputParser;
  addRequired(p,'modelFile',@ischar);
  addRequired(p,'outputFile',@ischar);

  addOptional(p,'gpuDevice', 0, @isnumeric); % choose the gpuDevice to use: 0 -- no GPU 
  addOptional(p,'align', 0, @isnumeric); % 1 -- output aignment from attention model
  addOptional(p,'assert', 0, @isnumeric); % 1 -- assert
  addOptional(p,'debug', 0, @isnumeric); % 1 -- debug
  addOptional(p,'testPrefix', '', @ischar); % to specify a different file for decoding
  addOptional(p,'continueId', 0, @isnumeric); % > 0: start decoding from this continueId (base 1) sent and append the results

  addOptional(p,'reuseEncoder', 0, @isnumeric);

  p.KeepUnmatched = true;
  parse(p,modelFile,outputFile,varargin{:})
  decodeParams = p.Results;

  decodeParams.isGPU = 0;
  if decodeParams.gpuDevice
    n = gpuDeviceCount;  
    if n>0 % GPU exists
      fprintf(2, '# %d GPUs exist. So, we will use GPUs.\\n', n);
      decodeParams.isGPU = 1;
      gpuDevice(decodeParams.gpuDevice)
      decodeParams.dataType = 'single';
    else
      decodeParams.dataType = 'double';
    end
  else
    decodeParams.dataType = 'double';
  end
  printParams(2, decodeParams);

  [model] = loadDecodeModel(decodeParams.modelFile, decodeParams);
  params = model.params;

  if params.continueId > 0 % appending
    fileOpt = 'a';
  else

    if params.reuseEncoder
      encoderInfo.prevStates = prevStates;
      encoderInfo.modelData = modelData;
      encoderInfo.srcInput = data.srcInput;
    end

    for ii=1:(endId-startId+1)
      fprintf(params.fid, '%f ', prevStates{1}{end}.h_t(:, ii));
      fprintf(params.fid, '\\n');
    end

    if mod(batchId, 100) == 0
      fprintf(2, '# Batch %d\\n', batchId);
    end
  end

  endTime = clock;
  timeElapsed = etime(endTime, startTime);
  fprintf(2, '# Complete encoding %d sents, num predict %d, ppl %g, time %.0fs, %s\\n', numSents, totalPredict, ...
    timeElapsed, datestr(now));
  fprintf(params.logId, '# Complete encoding %d sents, num predict %d, ppl %g, time %.0fs, %s\\n', numSents, totalPredict, ...
    timeElapsed, datestr(now));

  fclose(params.fid);
  fclose(params.logId);
end

