if(numel(traj_to_compute)~=size(P0.pts,2)) % we got duplicate
    traj_to_compute = sort(traj_to_compute);
    Ptmp = Sselect(P0,traj_to_compute);
    Ptmp = ComputeTrajSensi(Sys,Ptmp,tspan,i_params);

    Pf = P0;
    Pf.traj = Ptmp.traj; % copy the computed fields
    Pf.Xf = Ptmp.Xf;
    Pf.XSf = Ptmp.XSf;
    Pf.ExpaMax = Ptmp.ExpaMax;
    [~,Pf.traj_ref] = ismember(Pf.pts(1:Pf.DimP,:)',Ptmp.pts(1:Ptmp.DimP,:)','rows'); % link all param vect to computed traj and sensi
    Pf.traj_ref = reshape(Pf.traj_ref,1,[]); % set traj_ref in a line shape

function factors = ComputeTripletFactors (images, tripletList, K)


n = length(images);

if (n < 3)
    factors = [];
    return
end

factors = repmat(struct('var', [], 'card', [], 'val', []), n - 2, 1);

val = ones(K*K*K,1);% to be computed
m = length(tripletList);
for i = 1:m
	val(AssignmentToIndex(tripletList(i).chars,[K,K,K])) = tripletList(i).factorVal;
end
for i = 1:n-2
	factors(i).var = [i,i+1,i+2];
	factors(i).card = [K,K,K];
	factors(i).val = val;
end
end

function computeUptakeSecretion(modelFolder,propertiesFolder,reconVersion,metList,numWorkers)

dInfo = dir(modelFolder);
modelList={dInfo.name};
modelList=modelList';
modelList(~(contains(modelList(:,1),{'.mat','.sbml','.xml'})),:)=[];

mkdir([propertiesFolder filesep 'ComputedFluxes'])

uptakeFluxes = {};
secretionFluxes = {};

if ~isempty(metList)
    allExch={};
    for i=1:length(metList)
        allExch{i}=['EX_'  metList{i} '(e)'];
    end
else
    if isfile([propertiesFolder filesep 'ComputedFluxes' filesep 'uptakeFluxes_' reconVersion  '.txt'])
        uptakeFluxes = readInputTableForPipeline([propertiesFolder filesep 'ComputedFluxes' filesep 'uptakeFluxes_' reconVersion  '.txt']);
        allExch=uptakeFluxes(1,2:end)';
        secretionFluxes = readInputTableForPipeline([propertiesFolder filesep 'ComputedFluxes' filesep 'secretionFluxes_' reconVersion  '.txt']);

        modelsRenamed=strrep(modelList(:,1),'.mat','');
        modelsRenamed=strrep(modelsRenamed,'.sbml','');
        modelsRenamed=strrep(modelsRenamed,'.xml','');
        [C,IA]=intersect(modelsRenamed,uptakeFluxes(2:end,1));
        modelList(IA,:)=[];
    else
        if isfile([propertiesFolder filesep 'Reactions_' reconVersion '.txt'])
            reactions = readInputTableForPipeline([propertiesFolder filesep 'Reactions_' reconVersion '.txt']);
            allExch=reactions(find(strncmp(reactions(:,1),'EX_',3)),1);
        else
            allExch={};
            for i=1:length(modelList)
                i
                try
                    model=readCbModel([modelFolder filesep modelList{i}]);
                catch
                    model=load([modelFolder filesep modelList{i}]);
                    model = model.model;
                end
                exRxns=model.rxns(find(strncmp(model.rxns,'EX_',3)));
                allExch=unique(vertcat(allExch,exRxns));
            end
        end

modelsToLoad={};
for j=i:i+endPnt
    if j <= length(modelList)
        modelsToLoad{j}=[modelFolder filesep modelList{j}];
    end
end

parfor j=i:i+endPnt
    restoreEnvironment(environment);
    changeCobraSolver(solver, 'LP', 0, -1);
    if strcmp(solver,'ibm_cplex')
        changeCobraSolverParams('LP', 'logFile', 0);
    end
    try
        model=readCbModel(modelsToLoad{j});
    catch
        model=load(modelsToLoad{j});
        model = model.model;
    end
    exRxns=model.rxns(find(strncmp(model.rxns,'EX_',3)));
    model = changeRxnBounds(model, exRxns, -1000, 'l');
    model = changeRxnBounds(model, exRxns, 1000, 'u');

    exRxns=intersect(exRxns,allExch);

    if ~isempty(exRxns)

        currentDir=pwd;
        try
            [minFlux, maxFlux, ~, ~] = fastFVA(model, 0, 'max', 'ibm_cplex', ...
                exRxns, 'S');
        catch
