H_bc = setxor(H, H_b);
V = 1 : (hei - 1);
V_b = B : B : (hei - 1);
V_bc = setxor(V, V_b);

D_b = 0;
D_bc = 0;

for i = H_b
    diff = im(: , i) - im(: , i + 1);
    D_b = D_b + sum(diff.^2);
end

for i = H_bc
    diff = im(: , i) - im(: , i + 1);
    D_bc = D_bc + sum(diff.^2);
end

for j = V_b
    diff = im(j , :) - im(j + 1 , :);
    D_b = D_b + sum(diff.^2);
end

for j = V_bc
    diff = im(j , :) - im(j + 1 , :);
    D_bc = D_bc + sum(diff.^2);
end

