function [Bp] = compute_B_primary(coils, dipoles, projections)

if size(coils,2)~=3
  error('Column size of coils must be 3.')
end

if size(dipoles,2)~=6
  error('Column size of dipoles must be 6.')
end

if size(projections,2)~=3
  error('Column size of projections must be 3.')
end


dip_pos = dipoles(:,1:3);
dip_mom = dipoles(:,4:6);
Bp = zeros(size(coils,1), size(dipoles,1));
for i = 1:size(coils,1)
  for j = 1 : size(dip_pos,1)
    R = coils(i,:);
    R_0 = dip_pos(j,:);
    A = R - R_0;
    a = norm(A);
    aa = A./(a^3);

    BpHelp = cross(dip_mom(j,:),aa);
    Bp(i,j) = BpHelp * projections(i, :)'; % projection of the primary B-field along the coil orientations
  end
end

function cmap = compute_circular_jet_hue(u, v)



    nanIdx = isnan(u) | isnan(v);
    u(nanIdx) = 0;
    v(nanIdx) = 0;

    colorwheel = make_colour_wheel();
    ncols = size(colorwheel, 1);

    rad = sqrt(u.^2 + v.^2);
    a = atan2(-v, -u)/pi;
    fk = (a+1) /2 * (ncols-1) + 1;  % -1~1 maped to 1~ncols
    k0 = floor(fk);                 % 1, 2, ..., ncols
    k1 = k0+1;
    k1(k1==ncols+1) = 1;
    f = fk - k0;

    for i = 1:size(colorwheel,2)
        tmp = colorwheel(:, i);
        col0 = tmp(k0)/255;
        col1 = tmp(k1)/255;
        col = (1-f).*col0 + f.*col1;   

        idx = rad <= 1;   
        col(idx) = 0.85-rad(idx).*(1-col(idx));    % increase saturation with radius

        col(~idx) = col(~idx)*0.45;             % out of range

        cmap(:, :, i) = uint8(floor(255*col.*(1-nanIdx)));
    end

