        w = prob;
        w = w./sum(w);

        loc_refine = squeeze(dets.locationRefine(idxsc(idxsp), lp+1, :));
        if size(loc_refine, 2) == 1
            loc_refine = loc_refine';
        end
        pos = sum((dets.unPos(idxsc(idxsp),:) + loc_refine).*[w w],1);

        keypoints(lp+1, :) = pos;
    end

    people{j} = keypoints;
end

