function D = compute_geodesic_dist_matrix(S, samples)
M = S.surface;
M.n = S.nv;

if nargin==1 || isempty(samples)
    samples = 1:M.n;
end

fprintf('Compute geodesic distance matrix for %d samples...',length(samples)); tic;

march = fastmarchmex('init', int32(M.TRIV-1), double(M.VERT(:,1)), double(M.VERT(:,2)), double(M.VERT(:,3)));

D = zeros(length(samples));

for i=1:length(samples)
    source = inf(M.n,1);
    source(samples(i)) = 0;
    d = fastmarchmex('march', march, double(source));
    D(:,i) = d(samples);
end

fastmarchmex('deinit', march);

D = 0.5*(D+D');
t = toc; fprintf('done:%.4fs\\n',t);
end

function [path,vlist,plist] = compute_geodesic_mesh(D, vertex, face, x, options)


options.null = 0;
verb = getoptions(options, 'verb', 1);

if length(x)>1
    path = {}; vlist = {}; plist = {};
    for i=1:length(x)
        if length(x)>5     
            if verb
                progressbar(i,length(x));  
            end
        end
        [path{i},vlist{i},plist{i}] = compute_geodesic_mesh(D, vertex, face, x(i), options);
    end
    return;
end

method = getoptions(options, 'method', 'continuous');

[vertex,face] = check_face_vertex(vertex,face);

if strcmp(method, 'discrete')
    if isfield(options, 'v2v')
        vring = options.v2v;
    else
        vring =  compute_vertex_ring(face);
    end
    vlist = x;
    vprev = D(x);
    while true
        x0 = vlist(end);
        r = vring{x0};
        [v,J] = min(D(r));
        x = r(J);
        if v>=vprev || v==0
            break;

    etas = -y/ny;
    etat = -x/nx;
    s = x + etas*nx;
    t = y + etat*ny;
    if etas<0 && s>=0 && s<=1 && f1>0
        plist(end+1) = s;
        vlist(:,end+1) = [i k];
        f = f1;
    elseif etat<0 && t>=0 && t<=1 && f2>0
        plist(end+1) = t;
        vlist(:,end+1) = [j k];
        f = f2;
    else
        if a<=b
            z = i;            
        else
            z = j;
        end
        [w,f] = vertex_stepping( face, z, e2f, v2v, D);
        vlist(:,end+1) = [z w];  
        plist(end+1) = 1;   
    end
    Dnew = D(vlist(1,end))*plist(end) + D(vlist(2,end))*(1-plist(end));
    if Dnew==0 || (Dprev==Dnew && length(plist)>1)
        break;
    end
