       warning('not implemented!'); 
    case 'spring'
        W = compute_point_weight_spring(pts, rings);        
    case {'conformal','dcp'} % conformal laplacian  
        W = compute_point_weight_dcp(pts, rings);
    case 'laplace-beltrami' %
        W = compute_point_weight_dcp(pts, rings)*0.5;
