function[RR] = compute_RR(params)
rs = params.rs;
cs = params.cs;
Operator = params.Operator;
redundancy = params.Wavelet.redundancy;
includeApprox = params.Wavelet.includeApprox;
nlev = params.Wavelet.nlev;

[WRA] = compute_SWTFiltResp(params);
DCR = ones(rs,cs) - WRA(:,:,3*nlev+1);

Rh = fft2([-1 1], rs, cs);
Rv = fft2([-1 1]', rs, cs);
Rabs = abs(Rh).^2 + abs(Rv).^2;

switch(Operator)
    case{'FD'}
        RR = Rabs;

    case{'W'}
        switch(redundancy)
            case{'undecimated'}
                if(includeApprox)
                    RR = 1;
                else
                    RR = DCR;
                end
        end
    case{'WFD'}
        switch(redundancy)
            case{'undecimated'}
                if(includeApprox)
                    RR = Rabs + 1;
                else
                    RR = Rabs + DCR;
                end
        end
end

