for i=1:n
    sigma_points(:,i+1) = mu + sqrtm_matrix(:,i);
endfor
for i=n+1:2*n
    sigma_points(:,i+1) = mu - sqrtm_matrix(:,i-n);
endfor

w_m = zeros(1, 2*n+1);
w_c = zeros(1, 2*n+1);
w_m(1,1) = lambda / (n + lambda);
w_c(1, 1) = w_m(1, 1) + (1 - power(alpha, 2) + beta);
w_m(1, 2:end) = 1 / (2 * (n + lambda));
w_c(1, 2:end) = w_m(1, 2:end);

end

