n = length(tr(1,:));
half_window = window * 0.5;
tr_mean = zeros(1,n);

for i = (1 + half_window):(n - half_window)
    window_start = i - half_window;
    window_end = i + half_window;
    tr_mean(i) = sum(tr(1,window_start:window_end)) * 1/n;
end

