if ~isempty(mTime)
   gtime = cellfun(@(gEl) gEl.h, g(mTime),'UniformOutput',0);

   gskip = cellfun(@(gEl) gEl.offset ,g(mTime));
   c(mTime) = comp_filterbank_td(f,gtime,a(mTime),gskip,'per');
