d = trigs(2:end) - trigs(1:end-1);

samps = [];
tss = [];

for i = find(d > BASELINE * sfreq)
    ts = read_timestamp(d, i, TRAIN_STEP*sfreq, NBITS);
    if ts ~= -1
        samps(end+1) = trigs(i+1);
        tss(end+1) = ts;
    end
end

