        end

        if nargin < 3 || (~isempty(reset_count) && reset_count >= 0)
            switch (this.nch_wait)
                case 0, fprintf('Waiting'); this.nch_wait = 7;
                otherwise, fprintf('.'); this.nch_wait = this.nch_wait + 1;
