    hist2 = sum(Hist2) + eps;
    Hist2 = Hist2 ./ repmat(hist2, nB, 1);
end

D = zeros(n1, n2);
for iB = 1 : nB
    H1 = repmat(Hist1(iB, :)', 1, n2);
    H2 = repmat(Hist2(iB, :), n1, 1);
