            obj.OperatorPaddingRules = operatorPaddingRules;
            obj.SpecialRules = specialRules;
            obj.KeywordPaddingRules = keywordRules;
            obj.OperatorPaddingRuleNamesInOrder = operatorPaddingRuleNamesInOrder;
        end
