        H_W_inner = zeros(dim,dim);
        for i = 0:k-1
            H_W_partial = Lambda{i+1}.'*P*Lambda{i+1};
            H_W_inner = H_W_inner + H_W_partial;
        end
        H_W = diag(diag(G.W.'*H_W_inner*G.W)); 
    else
        H_W = zeros(nrOfGen.W,nrOfGen.W);
    end
    H_V = diag(diag(G.V.'*P*G.V));
    H_tilde = blkdiag(H_X, H_W, H_V);
end

