function [Z,f] = conic(varargin)

  FF = varargin{1};
  c = varargin{2};
  Aeq = varargin{3};
  beq = varargin{4};
  Aleq = varargin{5};
  bleq = varargin{6};
  lx = varargin{7};
  ux = varargin{8};
  b = varargin{9};
  bc = varargin{10};

  param = default_quadprog_param();
  quiet = 'echo(0)';
  opt_type = 'conic';

  ii = 11;
  while(ii <= nargin)
    switch varargin{ii}
    case 'Quiet'
      ii = ii + 1;
      assert(ii<=nargin);
      quiet = varargin{ii};
    case 'Param'
      ii = ii + 1;
      assert(ii<=nargin);
      param = varargin{ii};
    case 'OptType'
      ii = ii + 1;
      assert(ii<=nargin);
      opt_type = varargin{ii};
    otherwise
      error(['Unsupported parameter: ' varargin{ii}]);
    end
    ii = ii + 1;
  end
  if isfield(param,'Diagnostics');
    param = rmfield(param,'Diagnostics');
  end

  n = size(FF,2);
  nt = size(FF,1);
  I = speye(nt,nt);
  neq = size(Aeq,1);
  nleq = size(Aleq,1);

      FF -I; ...
      Aeq  sparse(neq,nt)  ; ...
      Aleq sparse(nleq,nt) ; ...
      ];
    prob.blc = [zeros(nt,1);beq;-Inf(nleq,1)];
    prob.buc = [zeros(nt,1);beq;bleq];
    prob.blx = [lx;-Inf(nt,1)];
    prob.bux = [ux;Inf(nt,1)];

    prob.bux(b) = bc;
    prob.blx(b) = bc;

  case 'quad'

    prob = [];
    [prob.qosubi,prob.qosubj,prob.qoval] = find(tril(FF'*FF));
    prob.c = c;
    prob.a = [Aeq; Aleq];
    prob.blc = [beq;-Inf(nleq,1)];
    prob.buc = [beq;bleq];
    prob.blx = lx;
    prob.bux = ux;

    prob.bux(b) = bc;
    prob.blx(b) = bc;
  end

  if isfield(param,'Display');
    param = rmfield(param,'Display');
  end

  [r,res]=mosekopt(['minimize ' quiet],prob,param);
  report_mosek_error(r,res);
  x = res.sol.itr.xx;
  Z = x(1:n);
  f = 0.5*sum((FF*Z).^2) + c'*Z;
end

