function [inc corr]=coning_minor(data, alg)
inlen=size(data,2);
switch (alg)
    case(0)
        inc=data;
        corr=zeros(size(data));
    case(1)
        outlen=floor((inlen-3)/3)+1;
        inc=zeros(3,outlen);
        corr=zeros(3,outlen);

        ind=1;
        for i=3:3:inlen
            inc(:,ind)=sum(data(:,i-2:i),2);
            corr(:,ind)=(33/80)*cross(data(:,i-2), data(:,i))+(57/80)*cross(data(:,i-1),data(:,i)-data(:,i-2));
            ind=ind+1;
        end
    case(2)
        outlen=floor((inlen-3)/3)+1;
        inc=zeros(3,outlen);
        corr=zeros(3,outlen);

        ind=1;
        for i=3:3:inlen
            inc(:,ind)=sum(data(:,i-2:i),2);
            corr(:,ind)=(9/20)*cross(data(:,i-2), data(:,i))+(27/40)*cross(data(:,i-1),data(:,i)-data(:,i-2));
            ind=ind+1;
        end
    case(3)
        outlen=floor((inlen-4)/2)+1;
        inc=zeros(3,outlen);
        corr=zeros(3,outlen);

        ind=1;
        for i=4:2:inlen
            vr_a=sum(data(:,i-1:i),2);
            vr_b=sum(data(:,i-3:i-2),2);
            inc(:,ind)=var_a;
            corr(:,ind)=(32/45)*cross(data(:,i-1), data(:,i))+(-1/180)*cross(vr_b,vr_a);
            ind=ind+1;
        end
    case(4)
        outlen=floor((inlen-3)/2)+1;

            inc(:,ind)=sum(data(:,i-2:i),2);
            corr(:,ind)=cross(((3/280)*data(:,i-3)+(57/140)*data(:,i-2)+(393/280)*data(:,i-1)), data(:,i));
            ind=ind+1;
        end
    case (8)
        outlen=floor((inlen-5)/3)+1;
        inc=zeros(3,outlen);
        corr=zeros(3,outlen);

        ind=1;
        for i=5:3:inlen
            inc(:,ind)=sum(data(:,i-2:i),2);
            corr(:,ind)=cross(((-1/420)*data(:,i-4)+(1/40)*data(:,i-3)+(157/420)*data(:,i-2)+(1207/840)*data(:,i-1)), data(:,i));
            ind=ind+1;
        end   
    case (9)
        outlen=floor((inlen-4)/4)+1;
        inc=zeros(3,outlen);
        corr=zeros(3,outlen);

        ind=1;
        for i=4:4:inlen
            inc(:,ind)=sum(data(:,i-3:i),2);
            corr(:,ind)=cross(((54/105)*data(:,i-3)+(92/105)*data(:,i-2)+(214/105)*data(:,i-1)), data(:,i));
            ind=ind+1;
        end
    otherwise
        disp('Undefined Algorithm (Perhaps, someone else adds it later)');
end

function [inc, corr]=coning(data, mint, alg)

[minc mcorr]=coning_minor_v000(data, alg);

len=size(minc,2);
outlen=floor(len/mint);
inc=zeros(3,outlen);
corr=zeros(3,outlen);

ind=1;
for i=mint:mint:len
    tinc=minc(:,i-mint+1);
    tcorr=mcorr(:,i-mint+1);
    for k=i-mint+2:i
        tcorr=tcorr+mcorr(:,k)+0.5*cross(tinc, minc(:,k));
        tinc=tinc+minc(:,k);
    end
    inc(:,ind)=tinc;
    corr(:,ind)=tcorr;
    ind=ind+1;
end

