        timeMask(i,j,k) = timeMask(i,j,k)+d(fp+2);
        npData(i,j,k) = npData(i,j,k)+1;
        fp = fp+2+numstats+3*npoints;
        pp=1+pp;
    end
    [lastPercent] = progress(nn,lastPercent,ticPercent,length(pathNames));
end
