function vs = conRbfChi(X0, Y0, weis, sig, varargin)

len = ps(varargin, 'len', 4000);

nX = size(X, 2);
nY = size(Y, 2);

X0 = X0 ./ 

XX = sum(X .* X);
YY = sum(Y .* Y); 

[idxXs, mX] = divCo2(nX, len);
[idxYs, mY] = divCo2(nY, len);

vs = zeros(nX, 1);
for iX = 1 : mX
    idxX = idxXs{iX};
    nXi = length(idxX);

    Xi = X(:, idxX);
    XXi = XX(:, idxX);
    for iY = 1 : mY
        idxY = idxYs{iY};
        nYi = length(idxY);

        Yi = Y(:, idxY);
        YYi = YY(:, idxY);

        weiY = weis(idxY);

        XY = Xi' * Yi;
        D = repmat(XXi', [1, nYi]) + repmat(YYi, [nXi, 1]) - 2 * XY;
