function [sym] = modulate(obj, bits)
    sym = zeros(floor(length(bits)/obj.n_bits), 1);
    for i = 1 : 1 : length(bits)/obj.n_bits
        symbol = 0;
        for j = 1 : obj.n_bits
            symbol = symbol + 2^(j-1) * bits((i-1)*obj.n_bits+j);
        end
        sym(i) = obj.constellation_points(symbol + 1);                    
    end
end

