    llr_mlc = llr_mlc .* (1 - 2*bits);
    mean_llr = zeros(obj.n_bits, 1);
    for i_bit = 1 : obj.n_bits
        mean_llr(i_bit) = mean(llr_mlc(i_bit: obj.n_bits:end));
    end

end


