function [x,z]=constrainedLSEq(A,b,B,d,algorithm)

if(nargin<5||isempty(algorithm))
    algorithm=0;
end

switch(algorithm)
    case 0%Algorithm 6.2.2 in Chapter 6.2.3 of [1].
        [~,n1]=size(A);
        [m2,~]=size(B);

        [Q,R]=qr(B');
        opts.UT=false;
        opts.LT=true;
        opts.RECT=false;
        y=linsolve(R(1:m2,1:m2)',d,opts);

        A=A*Q;
        z=linearLeastSquares(A(:,(m2+1):n1),b-A(:,1:m2)*y);
        x=Q(:,1:m2)*y+Q(:,(m2+1):n1)*z;
    case 1%From Chapter 14 of [2].
        m=size(A,2);
        p=size(B,1);
        H=A'*A;
        c=A'*b;
        xz=[H,B';
            B,zeros(p,p)]\\[c;d];

        x=xz(1:m);
        z=xz((m+1):end); %The Lagrangian multipliers.
    case 2%The GSVD approach of Chapter 6.2.5 of [1].
        [~,n1]=size(A);
        [m2,~]=size(B);

        [U1,U2,X,DA,DB]=gsvd(A,B);
        bTilde=U1'*b;
        dTilde=U2'*d;

function [x,t,intersects]=constrainedLSLineSpher(a,b,alphaVal)

if(nargin<3||isempty(alphaVal))
    alphaVal=1; 
end

if(all(b==0))
    normA=norm(a);
    intersects=normA==1;

    x=sqrt(alphaVal)*(a/normA);
    t=0;%t does not matter.
    return; 
end

xDim=size(a,1);

aMag2=dot(a,a);
bMag2=dot(b,b);
ab=dot(a,b);
t=roots([bMag2,2*ab,aMag2-alphaVal]).';
if(~isempty(t)&&isreal(t))
    numSol=length(t);
    x=zeros(xDim,numSol);

    for curSol=1:numSol
       x(:,curSol)=a+b*t(curSol);
       x(:,curSol)=sqrt(alphaVal)*(x(:,curSol)/norm(x(:,curSol)));
    end

function [x,lambda,exitFlag]=constrainedLSSpher(A,b,alpha,varargin)

if(nargin<4)
    varargin{1}=[];
end

if(nargin<3||isempty(alpha))
    alpha=1;
end

r=rank(A);

[U,Sigma,V]=svd(A,0);
sigma=diag(Sigma);

U=U(:,1:r);
V=V(:,1:r);
sigma=sigma(1:r);

bTilde=U'*b;
x=V*(bTilde./sigma);

if(norm(x)>alpha)
    upperBound=2*max((abs(bTilde.*sigma)*sqrt(r)-alpha*sigma.^2)./alpha);
    f=@(lambda)objFun(lambda,alpha,bTilde,sigma);
    [lambda,~,exitFlag]=fzero(f,[0,upperBound],varargin{:});
    x=V*((sigma.*bTilde)./(sigma.^2+lambda));
else
    lambda=0;
    exitFlag=0;
end
end

function val=objFun(lambda,alpha,bTilde,sigma)

    val=sum(((sigma.*bTilde)./(sigma.^2+lambda)).^2)-alpha^2;
end

