			surf(X,Y,Z,'FaceColor',this.bodyB.color);
			X = R.*cos(T);
			Y = R.*sin(T);
			Z = h/2*ones(size(R));
			X = reshape(X,1,2*(n+1));
			Y = reshape(Y,1,2*(n+1));
			Z = reshape(Z,1,2*(n+1));
			XYZ = E*[X;Y;Z;ones(1,2*(n+1))];
			X = reshape(XYZ(1,:),2,n+1);
			Y = reshape(XYZ(2,:),2,n+1);
			Z = reshape(XYZ(3,:),2,n+1);
			surf(X,Y,Z,'FaceColor',this.bodyB.color);
		end
	end
end

