function [A,b,Ae,be] = constraints(P)



if P.isHRep.val
    A = P.A_.val; b = P.b_.val; Ae = P.Ae_.val; be = P.be_.val;
    return
end

V = P.V_.val;

[n,nrVert] = size(V);

if nrVert == 1
    A = zeros(0,n); b = []; Ae = eye(n); be = V;
elseif n == 1
    [A,b,Ae,be] = aux_1D(P.V_.val);
elseif n == 2 && (nrVert <= 2 || rank(V) < 2)
    [A,b,Ae,be] = aux_2D_degenerate(P.V_.val);
else
    [A,b,Ae,be] = aux_nD(V,n);    
end

P.A_.val = A; P.b_.val = b; P.Ae_.val = Ae; P.be_.val = be;
P.isHRep.val = true;

end

minV_inf = minV == -Inf;

if maxV_inf && minV_inf
    A = zeros(0,1); b = [];
    Ae = zeros(0,1); be = [];

elseif maxV_inf && ~minV_inf
    A = -1; b = -minV;
    Ae = zeros(0,1); be = [];

elseif ~maxV_inf && minV_inf
    A = 1; b = maxV;
    Ae = zeros(0,1); be = [];

elseif withinTol(maxV,minV)
    A = zeros(0,1); b = [];
    Ae = 1; be = maxV;

else
    A = [1; -1]; b = [maxV; -minV];
    Ae = zeros(0,1); be = [];
end

end

function [A,b,Ae,be] = aux_nD(V,n)

c = mean(V,2);

H = Hall; H(s.lin, :) = [];
A = H(:,1:end-1);
if r == n
    b = H(:,end) + A*c;
else
    b = H(:,end);
end

He = Hall(s.lin, :);
Ae = He(:,1:end-1);
if r == n
    be = He(:,end) + Ae*c;
else
    be = He(:,end);
end

if r < n
    nrIneq = size(A,1);
    A = [A, zeros(nrIneq,n-r)];
    A = A * Umat';
    b = b + A*c;

    Ae = Umat(:,r+1:n)';
    be = Ae*c;
end

end

