function [ws_clean] = clean_watersheds(ws)

ws_clean = ws;

c = bwmorph(ws_clean == 0, 'clean', inf);

artifacts = ( c==0 & ws_clean==0 );
R = regionprops(artifacts, 'PixelList');

for r = 1 : numel(R),
