function ksi_dot = controller_dfs_variant(t,ksi,K1_single,Formations,h,Tconv,v_x,alter_a)



    index=dfs(t,ksi,Formations,h,Tconv);
    L=Formations.Laplacians;

    target=Formations.Targets(:,:,index);
    target(:,1) = target(:,1) + v_x*t;
    n=size(target,1);
    H=zeros(4*n,1);
    for i=1:n
        H(4*i-3,:)=target(i,1);
        H(4*i-2,:)=v_x;
        H(4*i-1,:)=target(i,2);
        H(4*i,:)=0;
    end

    Hv_dot=zeros(2*Formations.robot_number,1);

    N=size(ksi,1)/4;

    B2_single=[0;1];
    B1_single=[1;0];

    B2 = kron(eye(2),B2_single);
    B1 = kron(eye(2),B1_single);

    P_single = solveP(K1_single);

    K1 = kron(eye(2),K1_single);
    P=kron(eye(2),P_single);

    lamda = lamda_min(L);
    K2_single = (2*lamda)^(-1)*B2_single'*P_single;

    K2 = kron(eye(2),K2_single);


    ksi_dot = (kron(eye(N),(B2*K1+B1*B2'))-kron(L(:,:,index),B2*K2))*ksi...

function Actuators = Controller_PD(States,Control,Phase)


S = convert(States);   

C = Control.footOne;
pos = S.th1;    
vel = S.dth1;
A.T1 = C.Kp*(C.nomPos-pos) + C.Kd*(C.nomVel-vel);
if strcmp(Phase,'F') || strcmp(Phase,'S2')
    A.T1 = 0*A.T1;    %Can't use ankle torques in mid-air!
end

C = Control.footTwo;
pos = S.th2;    
vel = S.dth2;
A.T2 = C.Kp*(C.nomPos-pos) + C.Kd*(C.nomVel-vel);
if strcmp(Phase,'F') || strcmp(Phase,'S1')
    A.T2 = 0*A.T2;    %Can't use ankle torques in mid-air!
end

C = Control.legOne;
pos = S.L1;    
vel = S.dL1;
A.F1 = C.Kp*(C.nomPos-pos) + C.Kd*(C.nomVel-vel);

C = Control.legTwo;

function [ p ] = controlPolygon( P, i )

n = size(P, 2)-1;
dim = size(P, 1);
t = 0.5;
b = zeros(dim, n + 1, n + 1);
b(:, :, 1) = P;
c = zeros(dim, n + 1);
c(:,1) = P(:,1);
d = zeros(dim, n + 1);
d(:, n + 1) = P(:, n + 1); 

for j = 1 : n

    for k = 1 : n + 1 - j 
        b(:, k, j + 1) = (1 - t) * b(:, k, j) + t * b(:, k + 1, j);
    end

    c(:, j + 1) = b(:,1, j + 1);

    d(:, n + 1 - j) = b(:, n + 1 - j , j + 1);
end

if (i > 1)
    c = controlPolygon(c, i-1);
    d = controlPolygon(d, i-1);
end

p = [c d(:,2:end)];

end

