function eta_dot = calc_eta_dot(phi, theta, phi_dot, theta_dot)
    eta_dot_11 = 0;
    eta_dot_12 = sin(phi)*(tan(theta)^2 + 1)*theta_dot + cos(phi)*tan(theta)*phi_dot;
    eta_dot_13 = cos(phi)*(tan(theta)^2 + 1)*theta_dot - sin(phi)*tan(theta)*phi_dot;

    eta_dot_21 = 0;
    eta_dot_22 = -phi_dot*sin(phi);
    eta_dot_23 = -phi_dot*cos(phi);

    eta_dot_31 = 0;
    eta_dot_32 = (cos(phi)*phi_dot)/cos(theta) + (sin(phi)*sin(theta)*theta_dot)/cos(theta)^2;
    eta_dot_33 = (cos(phi)*sin(theta)*theta_dot)/cos(theta)^2 - (sin(phi)*phi_dot)/cos(theta);

    eta_dot = [eta_dot_11 eta_dot_12 eta_dot_13;
               eta_dot_21 eta_dot_22 eta_dot_23;
               eta_dot_31 eta_dot_32 eta_dot_33];
end

function [gear, shift_request] = control_AutomaticGearbox(drive_request, gear_in, ...
                            w_engine_radps, n_ub_rpm, i_gearset, shift_delay_s)

radps_lb = i_gearset(3, gear_in+1) * ((2*pi)/60);
radps_ub = n_ub_rpm * ((2*pi)/60);

persistent current_request 

if(isempty(current_request))
    current_request = int16(-1);
end

if(w_engine_radps > 50 && current_request == -1)
    current_request = gear_in;
end

if current_request ~= -1
    if shift_delay_s >= 1.2
        if w_engine_radps>=radps_ub && i_gearset(1, gear_in+1) < i_gearset(1, end)
           current_request = gear_in + 1;
           shift_request = 1;
        elseif w_engine_radps<=radps_lb && i_gearset(1, gear_in+1) > 1
           current_request = gear_in - 1;
           shift_request = 1;
        else
           shift_request = 0;
        end
    else
        if (shift_delay_s >= 0.7 && current_request ~= gear_in)
            current_request = gear_in;
        end
        shift_request = 0;
    end
    gear = current_request;
else 
    gear = gear_in;
    shift_request = 0;
end

