                tau_temp = tau_(1)+(tau1_std*randn);
            end 
            tau_(1) = tau_temp;
            gr_ = exp(Dt*(-1./tau_));
            s_1_ = zeros(T,1);
            s_1_(trunc_spikes) = exp((spiketimes_ - Dt*trunc_spikes)/tau_(1));
