RHS(2:Nr+1) = -(1./(DXp.*r)).*(re.*(ue_max.*psi_p(2:Nr+1)+ue_min.*psi_m(2:Nr+1))- ...
              rw.*(uw_max.*psi_p(1:Nr)+uw_min.*psi_m(1:Nr)));

end

