            res = polytope(-c,-(obj.rhs-d));

        case '>='
            [c,d] = aux_getHalfspace(obj.lhs,n,vars);
            res = polytope(-c,-(obj.rhs-d));

        otherwise
            throw(CORAerror('CORA:notSupported',...
                  'Conversion to set not supported for these type of stl objects!'));
    end
end

