function [M, S] = convertOperator(disc, item)

    dim = disc.dimension;
    dom = disc.domain;

    tech = disc.returnTech;
    tech = tech();
    valsDisc = tech.returnValsDisc;
    valsDisc = valsDisc(item, dim, dom);
    M = matrix(valsDisc);
    S = [];

    M = tech.vals2coeffs(tech.coeffs2vals(M.').');

    M_flat = M(:);
    tol = norm(M_flat, inf)*1e-10;        
    if ( norm(imag(M_flat), inf) < 10*tol )
        M = real(M);
    elseif ( norm(real(M_flat), inf) < 10*tol )
        M = imag(M);
    end      
    M(abs(M)<tol) = 0;
    if ( nnz(M)/numel(M) < .1 )
        M = sparse(M);
    end

end

function pose = convertOxtsToPose(oxts)

scale = latToScale(oxts{1}(1));

pose     = [];
Tr_0_inv = [];

for i=1:length(oxts)

  if isempty(oxts{i})
    pose{i} = [];
    continue;
  end

  [t(1,1) t(2,1)] = latlonToMercator(oxts{i}(1),oxts{i}(2),scale);
  t(3,1) = oxts{i}(3);

  rx = oxts{i}(4); % roll
  ry = oxts{i}(5); % pitch
  rz = oxts{i}(6); % heading 
  Rx = [1 0 0; 0 cos(rx) -sin(rx); 0 sin(rx) cos(rx)]; % base => nav  (level oxts => rotated oxts)
  Ry = [cos(ry) 0 sin(ry); 0 1 0; -sin(ry) 0 cos(ry)]; % base => nav  (level oxts => rotated oxts)
  Rz = [cos(rz) -sin(rz) 0; sin(rz) cos(rz) 0; 0 0 1]; % base => nav  (level oxts => rotated oxts)
  R  = Rz*Ry*Rx;

  if isempty(Tr_0_inv)
    Tr_0_inv = inv([R t;0 0 0 1]);
  end

  pose{i} = Tr_0_inv*[R t;0 0 0 1];
end

