function imgOut = ConvertXYZtoCIELab(img, inverse, conv_whitePoint)

check3Color(img);

imgOut = zeros(size(img));

if(~exist('conv_whitePoint', 'var'))
    conv_whitePoint = [1, 1, 1];
end

if(inverse == 0)%forward transform
    for i=1:3
        img(:,:,i) = img(:,:,i) / conv_whitePoint(i);
    end

    fY = CIELabFunction(img(:,:,2), 0);
    imgOut(:,:,1) = 116 * fY - 16;
    imgOut(:,:,2) = 500 * (CIELabFunction(img(:,:,1), 0) - fY);
    imgOut(:,:,3) = 200 * (fY - CIELabFunction(img(:,:,3), 0));   
end

function imgOut = ConvertXYZtoCIELCh(img, inverse, conv_whitePoint)

check3Color(img);

imgOut = zeros(size(img));

if(~exist('conv_whitePoint', 'var'))
    conv_whitePoint = [1, 1, 1];
end

if(inverse == 0)%forward transform
    imgLab = ConvertXYZtoCIELab(img, 0, conv_whitePoint);

    imgOut(:,:,1) = imgLab(:,:,1);
    imgOut(:,:,2) = sqrt(imgLab(:,:,2).^2 + imgLab(:,:,3).^2);

    rad_to_deg = 180 / pi;
    tmp = atan2(imgLab(:,:,3), imgLab(:,:,2)) * rad_to_deg;
    tmp(tmp < 0) = tmp(tmp < 0) + 360;
    imgOut(:,:,3) = tmp;
end

if(inverse == 1)%inverse transform    
    imgLab(:,:,1) = img(:,:,1);
    deg_to_rad = pi / 180;
    rad = img(:,:,3) * deg_to_rad;

