function [L,U] = power_bound(xL,xU,power)
if xL >= 0
    if power > 0
        L = xL^power;
        U = xU^power;
    else
        L = xU^power;
        U = xL^power;
    end
else
    if power < 0 & xU > 0
        U = inf;
        L = -inf;
    else
        if even(power)
            L = 0;
            U = max([xL^power xU^power]);
        elseif even(power+1)
            L = xL^power;
            U = xU^power;
        else
        disp('Not implemented yet')
        error
        end
    end
end

