dfU = power*xU^(power-1);
if xL<0 & xU>0
    Ax = [];
    Ay = [];
    b = [];  
    K = []; 
    return
elseif fU-fL < 1e-4
    Ax = [];
    Ay = [];
    b = [];
    K = []; 
    return
end

