    if length(transf) == 7, transf(8:9) = transf(7); end
    transf = checktransf(transf, elec1, elec2);

    dpre = mean(sqrt(sum((elec1.pnt(ind1,:) - elec2.pnt(ind2,:)).^2, 2)));
