if(nargin < 4)
    SD_atlas = CreateDefaultAtlasParm('lh');                %left hemisphere ('lh') or right hemisphere ('rh')
    SD_atlas.parms.SUBJECTS_DIR = fullfile('..','..','example_surfaces'); % directory that contains subjects
