    dt_ph = drifting + dt_ph_dj;
    dt_pr = drifting + dt_pr_dj;

    t_offset = round(mean(dt_pr(jmp) - time_desync(jmp) + ddrifting(jmp)/2) * 1e7) * 1e-7;
    dt_ph = dt_ph - t_offset;
    dt_pr = dt_pr - t_offset;

