    else
        time = [];
    end
end

function time = getLastEpochCoord(this)
    if ~isempty(this.time_ref_coord)
        time = this.time_ref_coord.getCopy();
        time.addSeconds((size(this.coord, 1) - 1) * this.coord_rate);
    else
        time = [];
    end
end

