function [xe, ye] = ellipse(x, y, major, minor, az)
    center = [x, y];
    theta = 90 - az;

    t = linspace(0, 2*pi);
    xe = center(1) + major*cos(t)*cosd(theta) - minor*sin(t)*sind(theta);
    ye = center(2) + major*cos(t)*sind(theta) + minor*sin(t)*cosd(theta);
end

