function [iA] = inverseByPartsDiag(A,idx1,idx2)
    sz1 = sum(idx1);
    sz2 = sum(idx2);
    A11 = A(idx1, idx1);
    A22 = A(idx2, idx2);
    A21 = A(idx2, idx1);
    A12 = A(idx1, idx2);
    iA11 = spdiags(1./diag(A11), 0, sz1, sz1);
    iA22 = spdiags(1./diag(A22), 0, sz2, sz2);
    r1 = A12*iA22*A21;
    r2 = A21*iA11*A12;
    A21 = -iA22*A21;
    A12 = -iA11*A12;
    A11 = A11 - r1;
    A22 = A22 - r2;
    iA11 = spdiags(1./diag(A11), 0, sz1, sz1);
    iA22 = spdiags(1./diag(A22), 0, sz2, sz2);
    iA = sparse(size(A));
    iA(idx1,idx1) = iA11;
    iA(idx1,idx2) = A12*iA22;
    iA(idx2,idx1) = A21*iA11;
    iA(idx2,idx2) = iA22;
end

function [iA] = inverseByRecPartsDiag(A,indices)
    n_blk = length(indices);

    part1 = 1:ceil(n_blk/2);
    part2 = (ceil(n_blk/2)+1):n_blk;
    if length(part1) > 1
        composite1 = true;
    else
        composite1 = false;
        sz1 = sum(indices{part1});

        iA22 = spdiags(1./diag(A22), 0, sz2, sz2);
    end
    r1 = A12*iA22*A21;
    r2 = A21*iA11*A12;
    A21 = -iA22*A21;
    A12 = -iA11*A12;
    A11 = A11 - r1;
    A22 = A22 - r2;
    if composite1
        iA11 = Core_Utils.inverseByRecPartsDiag(A11,new_indeces1);
    else
        iA11 = spdiags(1./diag(A11), 0, sz1, sz1);
    end
    if composite2
        iA22 = Core_Utils.inverseByRecPartsDiag(A22,new_indeces2);
    else
        iA22 = spdiags(1./diag(A22), 0, sz2, sz2);
    end
    iA = sparse(size(A));
    iA(idx1,idx1) = iA11;
    iA(idx1,idx2) = A12*iA22;
    iA(idx2,idx1) = A21*iA11;
    iA(idx2,idx2) = iA22;

end

