  robot = particles(i).pose;
  for j = 1:m
    l = z(j).id;


    if (particles(i).landmarks(l).observed == false)

      robot_x = robot(1);
      robot_y = robot(2);
      robot_r = robot(3);
      particles(i).landmarks(l).mu = [ robot_x + z(j).range * cos(normalize_angle(z(j).bearing + robot_r));
