  j = j+1;
end
if nl+2 <= size(Seg,1)
  top = nl+2;
else
  top = size(Seg,1);
end
j = 1;
while j < 3 && isempty(Seg{top})
  top = top-1;
  j = j+1;
end

if top > bot
  Bot = average(Ce(Seg{bot},:));
  Top = average(Ce(Seg{top},:));
  V = Top-Bot;
  D = V'/norm(V);
else
  D = zeros(3,1);
end


