  methods
    function outputs = forward(obj, inputs, params)
      obj.BatchSize = size(inputs{1});
      obj.ImageArea =  obj.BatchSize(1) * obj.BatchSize(2);
      InputsAll = gpuArray.zeros(obj.ImageArea * obj.BatchSize(end), 1, obj.BatchSize(3), 1, 'single');
      for i = 1:obj.BatchSize(end)
          Start = (i - 1) * obj.ImageArea + 1;
          End =  i * obj.ImageArea;
          InputsAll(Start:End,:,:) = reshape(inputs{1}(:,:,:,i), [obj.ImageArea  1 obj.BatchSize(3)]);
      end
      outputs = obj.CorrelateFoward({InputsAll});
    end

    function outputs = CorrelateFoward(obj, inputs)
        [h,w,d,batchsize]= size(inputs{1});
        inputsfilter = reshape(permute(inputs{1},[3,1,2,4]),1,1,d,h*w,[]);
        outputs{1} = gpuArray.zeros(h,w,h*w,batchsize,'single');
        for i=1:batchsize
            outputs{1}(:,:,:,i) = vl_nnconv(inputs{1}(:,:,:,i), inputsfilter(:,:,:,:,i),[]) ;
        end
    end

    function [derInputs, derParams] = backward(obj, inputs, params, derOutputs)
      InputsAll = gpuArray.zeros(obj.ImageArea * obj.BatchSize(end), 1, obj.BatchSize(3), 1, 'single');
      for i = 1:obj.BatchSize(end)
          Start = (i - 1) * obj.ImageArea + 1;
          End =  i * obj.ImageArea;
          InputsAll(Start:End,:,:) = reshape(inputs{1}(:,:,:,i), [obj.ImageArea  1 obj.BatchSize(3)]);
      end
      derInputsAll = obj.CorrelateBackward({InputsAll}, derOutputs);
      derInputs{1} = gpuArray.zeros(obj.BatchSize, 'single');
      for i = 1:obj.BatchSize(end)
          Start = (i - 1) * obj.ImageArea + 1;
          End =  i * obj.ImageArea;
          derInputs{1}(:,:,:,i) = reshape(derInputsAll(Start:End,:,:), obj.BatchSize(1:3));
      end

      derParams = {} ;
    end


    function derInputs = CorrelateBackward(obj, inputs, derOutputs)
        [h,w,d,batchsize]= size(inputs{1});

function Correlated(M, MFilter)


kf = 50; % number of time steps in simulation
phi = 0.8; % system matrix
H = 1; % measurement matrix
Q = 1; % process noise covariance
R = 0.1; % measurement noise covariance

Q1 = [Q M; M' R];
[d, lambda] = eig(Q1);
if (lambda(1) < 0) || (lambda(2) < 0)
    disp('Q1 is not positive semidefinite');
    return;
end
ddT = d * d';
if (norm(eye(size(ddT)) - ddT) > eps)
   disp(['d is not orthogonal. d = ',d]);
   return;
end

x = 0; % initial state
xhatplus = x; % initial state estimate
Pplus = 0; % initial uncertainty in state estimate

xArray = [];
xhatArray = [];
KArray = [];
PArray = [];
zArray = [];

randn('state', 0); % initialize random number generator

for k = 1 : kf
   v = [sqrt(lambda(1,1))*randn; sqrt(lambda(2,2))*randn];
   Dv = d * v;
   w = Dv(1);
   n = Dv(2);
   x = phi * x + w;
   z = H * x + n;
   Pminus = phi * Pplus * phi' + Q;
   K = inv(H * Pminus * H' + H * MFilter + MFilter' * H' + R);
   K = (Pminus * H' + MFilter) * K;
   xhatminus = phi * xhatplus;
   xhatplus = xhatminus + K * (z - H * xhatminus);
   Pplus = Pminus - K * (H * Pminus + MFilter');
   xArray = [xArray x];
   xhatArray = [xhatArray xhatplus];
   KArray = [KArray K];

