function [CORR, OUT] = CorrUnbalanced(DATA,labels)



[nobs, nvar] = size(DATA);

if ~exist('labels','var')
    labels(1,1:nvar) = {'Variable'};
end

if size(labels,1) > 1
    labels = labels';
end

CORR = nan(nvar,nvar);
OUT.N = nan(nvar,nvar);
for ii=1:nvar
    X1 = DATA(:,ii);
    for jj=1:nvar
        X2 = DATA(:,jj);
        Y = CommonSample([X1 X2]);
        if isempty(Y)
            CORR(ii,jj) = NaN;
            OUT.N(ii,jj) = 0;
        else
            aux = corr(Y(:,1),Y(:,2));
            OUT.N(ii,jj) = length(Y);
            if isnan(aux)
                if ii==jj
                    CORR(ii,jj) = 1; % Even if there is no variation the corr of each column with itself is seto to 1
                else
                    CORR(ii,jj) = NaN;
                end
            else
                CORR(ii,jj) = aux;
            end
        end
    end
end

function [L,P,Lc,Pc]=corr_meas(rtk,obs,nav,dantr,dants,phw)

global glc
lam=nav.lam(obs.sat,:);
L=zeros(glc.NFREQ,1);P=zeros(glc.NFREQ,1);Lc=0;Pc=0;

for i=1:glc.NFREQ
    L(i)=0; P(i)=0;
    if lam(i)==0||obs.L(i)==0||obs.P(i)==0,continue;end

    L(i)=obs.L(i)*lam(i)-dants(i)-dantr(i)-phw*lam(i);
    P(i)=obs.P(i)       -dants(i)-dantr(i);

end

[cbias,~]=getdcb(nav,obs,rtk.opt);
for i=1:glc.NFREQ
    if P(i)~=0,P(i)=P(i)-cbias(i);end
end
C1= lam(2)^2/(lam(2)^2-lam(1)^2);
C2=-lam(1)^2/(lam(2)^2-lam(1)^2);

if L(1)~=0&&L(2)~=0,Lc=C1*L(1)+C2*L(2);end
if P(1)~=0&&P(2)~=0,Pc=C1*P(1)+C2*P(2);end

return

