function [jV, djV] = computeValueAndGradient(obj, x, compFunc)
    nF  = length(obj.shapeFunctions);
    bDa  = length(obj.shapeFunctions);
    Jc  = cell(nF,1);
    dJc = cell(nF,1);
    for iF = 1:nF
        shI = obj.shapeFunctions{iF};
        if nargout(compFunc) == 2
            [j,dJ]  = compFunc(shI,x);
            bDa(iF) = false;
        else
            [j,dJ,bD]  = compFunc(shI,x,obj.moveBatch);
            bDa(iF) = bD;
        end
        Jc{iF}  = j;
        dJc{iF} = obj.mergeGradient(dJ);
    end

    jV  = 0;
    djV = zeros(size(dJc{1}));
    for iF = 1:nF
        wI  = obj.weights(iF);
        jV  = jV  + wI*Jc{iF};
        djV = djV + wI*dJc{iF};

function [A,C,b_srtd,J] = cost_func(PATH,ts,gamma)
A = A_const(ts);
Ae = eig(A);
  if (min(Ae) < 0)
    A = A + eye(size(A))*(abs(min(Ae)) + .001);
  end
C = permut_mat(ts);
Q = cost_mat(ts);
R = C/A'*Q/A*C';
Re = eig(R);
  if (min(Re) < 0)
    R = R + eye(size(R))*(abs(min(Re)) + .001);
  end
J = 0;
b_srtd = [];
[Rff,Rfp,Rpf,Rpp] = seg_R(R);
for i=1:size(PATH,2)
    bf = const_bf(PATH(:,i));
    bp_star = -Rpp\\Rfp'*bf;
    b_srtd(:,i) = [bf;bp_star];
    J = J + b_srtd(:,i)'*R*b_srtd(:,i) + gamma*ts(end);
end

end

