function SStar=covMatEstShrinkage(x,centerData,algorithm)

if(nargin<3||isempty(algorithm))
    algorithm=0;
end

if(nargin<2||isempty(centerData))
    centerData=true;
end

if(centerData)
    x=bsxfun(@minus,x,mean(x,2)); 
end

p=size(x,1);
n=size(x,2);
S=(1/n)*(x*x');

switch(algorithm)
    case 0%The Ledoit-Wolf covariance estimator.
        m=trace(S)/p;

        d2=norm(S-diag(m),'fro')^2;

        b2Bar=0;
        for k=1:n
            b2Bar=b2Bar+norm(x(:,k)*x(:,k)'-S,'fro')^2;
        end
        b2Bar=(1/n^2)*b2Bar;
        b2=min(b2Bar,d2);

        a2=d2-b2;

        SStar=(b2/d2)*diag(m)+(a2/d2)*S;
    case 1%The empirical Bayesian estimator (Haff estimator).
        mEB=det(S)^(1/p);
        if(mEB<=0||~isreal(mEB))
            mEB=trace(S)/p;
        end

        SStar=((p*n-2*n-2)/(p*n^2))*diag(mEB)+(n/(n+1))*S;

function K = covNNone(hyp, x, z, i)


if nargin<2, K = '2'; return; end                  % report number of parameters
if nargin<3, z = []; end                                   % make sure, z exists
xeqz = isempty(z); dg = strcmp(z,'diag');                       % determine mode

n = size(x,1);
ell2 = exp(2*hyp(1));
sf2 = exp(2*hyp(2));

sx = 1 + sum(x.*x,2);
if dg                                                               % vector kxx
  K = sx./(sx+ell2);
else
  if xeqz                                                 % symmetric matrix Kxx
    S = 1 + x*x';
    K = S./(sqrt(ell2+sx)*sqrt(ell2+sx)');
  else                                                   % cross covariances Kxz
    S = 1 + x*z'; sz = 1 + sum(z.*z,2);
    K = S./(sqrt(ell2+sx)*sqrt(ell2+sz)');
  end
end

if nargin<4                                                        % covariances
  K = sf2*asin(K);
else                                                               % derivatives
  if i==1                                                          % lengthscale
    if dg
      V = K;
    else
      vx = sx./(ell2+sx);
      if xeqz
        V = repmat(vx/2,1,n) + repmat(vx'/2,n,1);
      else  
        vz = sz./(ell2+sz); nz = size(z,1);
        V = repmat(vx/2,1,nz) + repmat(vz'/2,n,1);
      end
    end
    K = -2*sf2*(K-K.*V)./sqrt(1-K.*K);
  elseif i==2                                                        % magnitude
    K = 2*sf2*asin(K);
  else
    error('Unknown hyperparameter')
  end
end

