out.raw = mean((yn1-yn).^3)/(mean((yn1-yn).^2))^(3/2);

out.abs = abs(out.raw);

out.num = mean((yn1-yn).^3);
out.absnum = abs(out.num);

out.denom = (mean((yn1-yn).^2))^(3/2);

end

