function Pi = tt_calcpi_prowsubprob(X, isSparse, M, R, n, N, sparse_indices)



    if (isSparse)
        num_row_nnz = length(sparse_indices);

        Pi = ones(num_row_nnz, R);
        for nn = [1:n-1,n+1:N]
            Pi = M{nn}(X.subs(sparse_indices,nn),:) .* Pi;
        end
    else
        U = M.U;
        Pi = khatrirao(U{[1:n-1,n+1:N]},'r');
    end

end


