                cp_values = pts_x(1:2*this.cp(i_cp)-1);
                meth = this.method{i_cp};
                pts_x = pts_x(2*this.cp(i_cp):end);

                t_cp = [0; cp_values(2:2:end-1)];
                x_values = cp_values(1:2:end);
                if numel(t_cp)==1
                    x = x_values(end)*ones(numel(time),1);
                else
                    x_values = x_values(1:min([numel(t_cp) numel(x_values)]));
                    t_cp = t_cp(1:min([numel(t_cp) numel(x_values)]));
                    [t_cp, order] = sort(t_cp);
                    x_values = x_values(order);
                    x = interp1(t_cp, x_values, time', meth, 'extrap');
                end
                X(i_cp,:) = x';
            end
        end

        function type = getType(this)
            type = 'varstep';
        end
    end
end

function P2fine = cp_subpixelFine(P1,P2)
len = length(P1);
affmat = fitgeotrans(P1,P2,'projective');
P2pro = [P1 ones(len,1)] * affmat.T;
P2pro = P2pro(:,1:2) ./ P2pro(:,3);
devia_P = (P2 - P2pro).^2;
devia_P = sqrt(sum(devia_P,2));
max_Devia = max( devia_P );
iteration = 0;
P2fine = P2;
while max_Devia > 0.05 && iteration < 20
    iteration = iteration+1;
    fprintf('\\nsubpixel iteration = %d\\tmax_devia=%f\\n',iteration,max_Devia);
    [~,index] = sort(devia_P);
    ind1 = round( 1/4 * length(index));
    P2fine(index(ind1:end),:)    =  P2pro(index(ind1:end),:);
    affmat = fitgeotrans(P1,P2fine,'projective');
    P2pro = [P1 ones(len,1)] * affmat.T;
    P2pro = P2pro(:,1:2) ./ P2pro(:,3);
    devia_P = (P2fine - P2pro).^2;
    devia_P = sqrt(sum(devia_P,2));
    max_Devia = max( devia_P );
end
fprintf('\\nsubpixel iteration = %d\\tmax_devia=%f\\n',iteration,max_Devia);

function [T1 Mls]=cp_T(M, R, mtd)
if (size(M,1)>size(M,2))
	[u,s,v]=svd(M);
	T1=u(:,size(M,2)+1:size(M,1))';

	if (mtd==0)
		R_inv=inv(R);
		Mls=inv(M'*R_inv*M)*M'*R_inv;
	elseif (mtd==1)
		T2=u(:,1:size(M,2))';   
		mx_a=inv(T1*R*T1');
		mx_b=inv(T2*M);
		Mls=mx_b*(T2-T2*R*T1'*mx_a*T1);
	end
elseif (size(M,1)==size(M,2))
	T1=[]; %No redundancy
	R_inv=inv(R);
	Mls=inv(M'*R_inv*M)*M'*R_inv;
else
	disp('Error cp_T:M is not full col rank');
end

