function [creak_pp,creak_bin] = creaky_voice_do_detection(FeatTot,ANN)

Maxis=ANN.Maxis.Maxis;
Minis=ANN.Minis.Minis;
net=ANN.net.net;

ANN_decision_threshold=0.3; % Optimised in publication
med_len=3; % Length of median filtering

m=size(FeatTot);
X=zeros(m(2),m(1));
for k=1:m(2)
    X(k,:)=FeatTot(:,k)';    
end

m=size(X);

for k=1:m(1)
    vec=X(k,:);

    mini=Minis(k);
    maxi=Maxis(k);

    pos=isnan(vec);
    vec(pos)=mini;

    X(k,:)=-1+((vec-mini)/(maxi-mini))*2;
end

creak_pp=sim(net,X);

creak_pp2=medfilt1(creak_pp,med_len); % Median filtering to remove transients

creak_bin=zeros(1,length(creak_pp));
creak_bin(creak_pp2>ANN_decision_threshold)=1;

function create(obj,wrt)



for i=1:numel(obj)

    o = obj(i);

    if ~isa(o.dat,'file_array'), error('Data must be a file_array.'); end

    fname = o.dat.fname;
    if isempty(fname), error('No filename to write to.'); end

    sts = write_hdr_raw(fname, o.hdr, o.dat.dtype(end-1)=='B');
    if ~sts, error('Unable to write header for "%s".',fname); end

    write_extras(fname,o.extras);

    if nargin>1 && any(wrt==1)
        [pth,nam] = fileparts(fname);
        if any(strcmp(o.hdr.magic(1:3),{'n+1','n+2'}))
            ext = '.nii';
        else
            ext = '.img';
        end
        o.dat.fname = fullfile(pth,[nam ext]);

        initialise(o.dat);
    end

end

