function bilevelMILPproblem = createBilevelMILPproblem(model, cLinear, cInteger, selRxns, selRxnMatch, constrOpt, measOpt, options, selPrevSol)

S = model.S;
ub = model.ub;
c = model.c;
clp = cLinear;
cip = cInteger;
sel_int = selRxns;
rev_int = selRxnMatch;
if (~isempty(constrOpt))
    ind_ic = constrOpt.rxnInd;
    b_ic = constrOpt.values;
    csense_ic = constrOpt.sense;
else
    ind_ic = [];
    b_ic = [];
    csense_ic = [];
end
if (~isempty(measOpt))
    sel_m = measOpt.rxnSel;
    b_m = measOpt.values;
    wt_m= measOpt.weights;
else
    sel_m = [];
    b_m = [];
    wt_m = [];
end
H = options.vMax;
K = options.numDel;
ksense = options.numDelSense;
if (nargin < 9)
    sel_int_prev = [];
else
    sel_int_prev = selPrevSol;
end

Iint = selMatrix(sel_int);
Inint = selMatrix(~sel_int & ~sel_ic);
n_nint = size(Inint, 1);
Iic = sparse(n_ic,n);
for i = 1:length(ind_ic)
    idx_ic = ind_ic(i);
    Iic(i,idx_ic) = 1;
end
Im = selMatrix(sel_m);

A_bl = [S sparse(m,2*n_int+n+m+n_ic+2*n_m)];
b_bl = zeros(m,1);
csense_bl(1:m) = 'E';

A_bl = [A_bl; Iic sparse(n_ic,2*n_int+m+n+n_ic+2*n_m)];
b_bl = [b_bl; b_ic];
csense_bl(end+1:end+n_ic) = csense_ic;

A_bl = [A_bl; c' sparse(1,n_int+m) -ub' sparse(1,n_int) -b_ic' sparse(1,2*n_m)];
b_bl = [b_bl; 0];
csense_bl(end+1) = 'E';

A_bl = [A_bl; Iint sparse(diag(-ub(sel_int == 1))) sparse(n_int,m+n+n_int+n_ic+2*n_m)];
b_bl = [b_bl; zeros(n_int,1)];
csense_bl(end+1:end+n_int) = 'L';

A_bl = [A_bl; Inint sparse(n_nint,m+n+2*n_int+n_ic+2*n_m)];
b_bl = [b_bl; ub(~sel_int & ~sel_ic)];
csense_bl(end+1:end+n_nint) = 'L';

A_bl = [A_bl; sparse(n_ic,n+n_int) S(:,ind_ic)' Iic sparse(n_ic,n_int) speye(n_ic) sparse(n_ic,2*n_m)];
b_bl = [b_bl; c(ind_ic)];
csense_bl(end+1:end+n_ic) = 'G';

A_bl = [A_bl; sparse(n_nint,n+n_int) S(:,sel_int == 0 & sel_ic == 0)' Inint sparse(n_nint,n_int+n_ic+2*n_m)];
b_bl = [b_bl; zeros(n_nint,1)];
csense_bl(end+1:end+n_nint) = 'G';

A_bl = [A_bl; sparse(n_int,n) -H*speye(n_int) S(:,sel_int == 1)' Iint sparse(n_int,n_int+n_ic+2*n_m)];
b_bl = [b_bl; -H*ones(n_int,1)];
csense_bl(end+1:end+n_int) = 'G';

A_bl = [A_bl; sparse(n_int,n) H*speye(n_int) S(:,sel_int == 1)' sparse(n_int,n) speye(n_int) sparse(n_int,n_ic+2*n_m)];
b_bl = [b_bl; zeros(n_int,1)];
csense_bl(end+1:end+n_int) = 'G';

function  H = CreateBlurAndDecimationOperator(scale, lr_im_sz, psf)

hr_im_sz = lr_im_sz*scale;

offset = (size(psf, 1)-1)/2;
cntr = ceil(size(psf, 1)/2);

tot_numel = size(psf, 1)^2 * lr_im_sz(1)*lr_im_sz(2);
row_locs = zeros(tot_numel, 1);
col_locs = zeros(tot_numel, 1);
values = zeros(tot_numel, 1);
cnt_numel = 1;

locs = 1 : 1 : (hr_im_sz(1)*hr_im_sz(2));
locs = reshape(locs, [hr_im_sz(1), hr_im_sz(2)]);

for lr_row = 1 : 1 : lr_im_sz(1)

    for lr_col = 1 : 1 : lr_im_sz(2)

        hr_row = (lr_row-1)*scale + 1;
        hr_col = (lr_col-1)*scale + 1;        

        row_idx = (lr_col-1)*lr_im_sz(1) + lr_row;
        rows_vec = max(hr_row - offset,1) : min(hr_row + offset,hr_im_sz(1));
        cols_vec = max(hr_col - offset,1) : min(hr_col + offset,hr_im_sz(2));
        col_idx = reshape(locs(rows_vec, cols_vec), [],1);
        cur_numel = size(col_idx,1);        
        row_locs(cnt_numel : cnt_numel+cur_numel-1) = row_idx;
        col_locs(cnt_numel : cnt_numel+cur_numel-1) = col_idx;

        rows_vec = cntr - (hr_row - max(hr_row - offset,1)) : cntr + min(hr_row + offset,hr_im_sz(1)) - hr_row;
        cols_vec = cntr - (hr_col - max(hr_col - offset,1)) : cntr + min(hr_col + offset,hr_im_sz(2)) - hr_col;
        crop_psf = reshape( psf(rows_vec,cols_vec), [], 1);
        values(cnt_numel : cnt_numel+cur_numel-1) = crop_psf/sum(crop_psf);

        cnt_numel = cnt_numel + cur_numel;

    end

end

row_locs = row_locs(1:cnt_numel-1);
col_locs = col_locs(1:cnt_numel-1);
values = values(1:cnt_numel-1);

