function newRoute = createNeibor(route,model,mode)
while(1)
    switch mode
        case 1
            newRoute = Swap(route);
        case 2
            newRoute=Reversion(route);

        case 3
            newRoute=Insertion(route);
    end

    if(isFeasible(newRoute,model)) 
        break; 
    end
end
end

