    center = line(1:3);
    vector = line(4:6);
else
    vector = line;
end

v = normalizeVector3d(vector);

P = v'*v;
Q = [0 -v(3) v(2) ; v(3) 0 -v(1) ; -v(2) v(1) 0];
I = eye(3);

mat = eye(4);
mat(1:3, 1:3) = P + (I - P)*cos(theta) + Q*sin(theta);

mat = recenterTransform3d(mat, center);

function trans = createRotationOx(varargin)


