        Q_new = reshape(Q_new,length(BlockedQ{i}{j}),length(BlockedQ{i}{j}));
        obj = obj+trace(Q_new);
        [F_sos,Q_new,infeasible] = trivialReduce(F_sos,Q_new);
        if ~infeasible && ~isa(Q_new,'double')            
            switch options.sos.model
                case {2,4}
                    F_sos = F_sos + [Q_new>=0];
