    if(iteration > 1)

        policy_vector = new_policy_vector;
    end

    for s = 1 : K - 2

        a        = policy_vector(s);
        sum_term = 0;

        for s_prime = 1 : K

            sum_term = sum_term + transition_matrix(s, s_prime, a)*value_vector_old(s_prime);
        end

        expected_reward = transition_matrix(s, :, a) * reward;
        value_vector(s) = gamma*sum_term + expected_reward;
    end

