function [w,per_cor] = CS4300_perceptron_learning(X,y,alpha,max_iter,rate)

n = length(X(:,1));
m = length(X(1,:));
w = 0.02 * rand(m+1,1) - 0.01;
iter = 0;
counter = 1;
per_cor = [];
X = [ones(n,1) X];
for i = 1: max_iter
    j = randi(n);
    y_ = y(j);
    x_ = X(j,:);
        if rate
            alpha = 1000/(1000 + iter);
        end

        h = (x_ * w) >= 0;
        w = w + ((alpha * (y_ - h)) * x_)';
        per_cor(counter) = sum(((X * w) > 0) == y)/n;
        counter = counter + 1;

    iter = iter + 1;
end

