function  [stx,fx,dx,sty,fy,dy,stp,fp,dp,brackt,info] ...
  = cstep(stx,fx,dx,sty,fy,dy,stp,fp,dp,brackt,stpmin,stpmax)



      p66 = 0.66;
      info = 0;
      if ((brackt & (stp <= min(stx,sty) | ...
          stp >= max(stx,sty))) | ...
          dx*(stp-stx) >= 0.0 | stpmax < stpmin) 
         return
      end
      sgnd = dp*(dx/abs(dx));
      if (fp > fx) 
         info = 1;
         bound = 1;
         theta = 3*(fx - fp)/(stp - stx) + dx + dp;
         s = norm([theta,dx,dp],inf);
         gamma = s*sqrt((theta/s)^2 - (dx/s)*(dp/s));
         if (stp < stx) 
             gamma = -gamma;
         end
         p = (gamma - dx) + theta;
         q = ((gamma - dx) + gamma) + dp;
         r = p/q;
         stpc = stx + r*(stp - stx);
         stpq = stx + ((dx/((fx-fp)/(stp-stx)+dx))/2)*(stp - stx);
         if (abs(stpc-stx) < abs(stpq-stx)) 
            stpf = stpc;
         else
           stpf = stpc + (stpq - stpc)/2;
         end 
         brackt = 1;
      elseif (sgnd < 0.0) 
         info = 2;
         bound = 0;
         theta = 3*(fx - fp)/(stp - stx) + dx + dp;

         stpf = stpq;
      end
   else
      if (abs(stp-stpc) > abs(stp-stpq)) 
         stpf = stpc;
      else
         stpf = stpq;
      end 
   end 
else
   info = 4;
   bound = 0;
   if (brackt) 
      theta = 3*(fp - fy)/(sty - stp) + dy + dp;
      s = norm([theta,dy,dp],inf);
      gamma = s*sqrt((theta/s)^2 - (dy/s)*(dp/s));
      if (stp > sty) 
          gamma = -gamma;
      end
      p = (gamma - dp) + theta;
      q = ((gamma - dp) + gamma) + dy;
      r = p/q;
      stpc = stp + r*(sty - stp);
      stpf = stpc;
   elseif (stp > stx)
      stpf = stpmax;
   else
      stpf = stpmin;
   end 
end 
if (fp > fx) 
   sty = stp;
   fy = fp;
   dy = dp;
else
   if (sgnd < 0.0)
      sty = stx;
      fy = fx;
      dy = dx;
   end 
   stx = stp;
   fx = fp;
   dx = dp;

