    if (fseek(fid, offset, 'bof') == -1)
        fclose(fid);
        error('Cannot go to byte #%d.', offset);
    end
    if (fwrite(fid, str, 'char') < n)
        fclose(fid);
        error('Cannot write data to file.');
    end
end

