xrange(2) = xrange(2) + (xrange(2) - xrange(1)) / expand_ratio;
yrange(1) = yrange(1) - (yrange(2) - yrange(1)) / expand_ratio;
yrange(2) = yrange(2) + (yrange(2) - yrange(1)) / expand_ratio;

