    D1 = -6.*C1(1,:) + 18.*C1(2,:) - 18.*C1(3,:) + 6.*C1(4,:);
    D2 = -6.*C2(1,:) + 18.*C2(2,:) - 18.*C2(3,:) + 6.*C2(4,:);
    D2_sqr_len = sum(D2.*D2,2);
    D1_sqr_len = sum(D1.*D1,2);
    D2_D1 = sum(D2.*D1,2);
    r = D2_D1/D1_sqr_len;
    t = (1 + (r.^(1/3))).^-1;
  end
  C = C_from_t(C1,C2,t);
case 'iterative'
  if isempty(t0)
    ts = matrixnormalize(cumsum([0;spline_arc_lengths([C1;C2],[1 2 3 4;5 6 7 8],'Method','cubic_arc_length','NumQuadrature',20)]));
    t0 = ts(2);
  end
  t1 = t0;
  B = [C1(1,:);C1(1,:);C2(4,:);C2(4,:)];
  B1 = [0 0;(C1(2,:) - C1(1,:));0 0;0 0];
  B2 = [0 0;0 0;(C2(3,:) - C2(4,:));0 0];
  S = [B1(:) B2(:)];

  f = @(t1) objective_t1(C1,C2,t1,B,S);


  [E,C] = f(t1);

function [w1,w2] = weights(t1)
  if weighted
    w1 = 1/(t1)   + 1.0/(1.0-0.0);
    w2 = 1/(1-t1) + 1.0/(1.0-0.0);;
  else
    w1 = 1;
    w2 = 1;
  end
end

function [E,C] = objective_t1(C1,C2,t1,B,S)
  if isfloat(t1) && (t1>1 || t1<0)
    E = inf;
    return;
  end
  C = nan(4,2);
  [~,H,F,c] = objective(C1,C2,C,t1);
  HH = repdiag(H,2);
  V = ((S.'*HH*S)\\(-S.'*F(:)-S.'*HH*B(:)));
  V = max(V,0);
  C = reshape( B(:) + S*V , size(C));
  [E] = objective(C1,C2,C,t1);
end
function [E,H,F,c] = objective(C1,C2,C,t1)
  if isfloat(t1) && (t1>1 || t1<0)
    E = inf;
    return;
  end
  [w1,w2] = weights(t1);

  if nargout == 4
    [H1,F1,c1,E1] = cubic_cubic_integrated_distance( ...
      0,t1, ...
      1/t1,0, ...
      C1, ...
      1,0, ...
      C);
    [H2,F2,c2,E2] = cubic_cubic_integrated_distance( ...
      t1,1, ...
      1/(1-t1),-t1/(1-t1), ...
      C2, ...
      1,0, ...
      C);

