if(numIdx==2&&numDimList(2)==1)
    numIdx=1;
end

binomTable=makeBinomTable(maxDeg);

cumMat=zeros(numDimList);
negCumMomMat=zeros(numDimList);

negCumMomMat(1)=1;
cumMat(1)=0;

for n=1:maxDeg
    cumMat(n+1)=momentMat(n+1);
    for i=1:(n-1)
        cumMat(n+1)=cumMat(n+1)-binomTable(n-1+1,i+1)*cumMat(n-i+1)*momentMat(i+1);
    end

    for i=0:(n-1)
        negCumMomMat(n+1)=negCumMomMat(n+1)+binomTable(n-1+1,i+1)*(-cumMat(n-i+1))*negCumMomMat(i+1);
    end
end

for numNonzeroIdx=2:numIdx
    for nonzeroDegVal=1:maxDeg
        for curDeg=0:(maxDeg-nonzeroDegVal)
            curPart=getNextMPartition(numNonzeroIdx-1+curDeg,numNonzeroIdx-1);

            kIdxVec=r-iVec;

            idx=nDim2Index(maxDim,iVec+1);
            kidx=nDim2Index(maxDim,kIdxVec+1);

            sumVal=sumVal+binomVal*(signMat1*mat1(kidx))*mat2(idx);
        end
        curLevel=curLevel-1;
        isAscending=true;
        continue;
    elseif(isAscending)
        iVec(curLevel)=iVec(curLevel)+1;
        if(iVec(curLevel)<=r(curLevel))
            if(curLevel~=1)
                binomProdVal(curLevel)=binomProdVal(curLevel-1)*binomTable(r(curLevel)+1,iVec(curLevel)+1);
            else
                binomProdVal(curLevel)=binomTable(r(curLevel)+1,iVec(curLevel)+1);
            end
            isAscending=false;
            curLevel=curLevel+1;
            continue;
        else
            curLevel=curLevel-1;
            continue;
        end
    else%We are descending in the sums here.
        iVec(curLevel)=0;
        binomProdVal(curLevel)=binomProdVal(curLevel-1);
        curLevel=curLevel+1;
    end
end

end

function [new_im_dst, chist_dst, chist_ref, map, M] = cumulative_histogram_mapping(im_dst, im_ref, edges)


[N,d] = size(im_ref);

for i=1:d
    cens{i} = (edges{i}(1:end-1)+edges{i}(2:end))/2;    
    chist_dst{i} = compute_cumulative_histogram(im_dst(:,i), edges{i});
    chist_ref{i} = compute_cumulative_histogram(im_ref(:,i), edges{i});

    [map{i}, M{i}] = map_cumulative_histograms(chist_dst{i}, chist_ref{i}, edges{i}, cens{i}, im_ref(:,i));
end

new_im_dst = convert_image(im_dst, map, edges);


function chist = compute_cumulative_histogram(data, edges)

data = double(data(:));

H = histc(data, edges); 
H = H(1:end-1);  % discard the last fake bin
nhist = H/sum(H);  % normalized histogram
chist = cumsum(nhist);


function [map, M] = map_cumulative_histograms(chist_dst, chist_ref, edges, cens, im_ref)

n = length(chist_dst);

M = zeros(n,1);
t = 1;  % searching starting point
for v=1:n
    chist_diff = chist_ref - chist_dst(v);
    idx = find(chist_diff<=0);
    if isempty(idx)
        M(v) = 1;
    else
        M(v) = idx(end);
    end
end

for i=1:n
    map(i) = cens(M(i));
end

im_ref = double(im_ref(:));
data = im_ref(find(edges(1)<=im_ref & im_ref<edges(2)));
St = sum(data)./length(data);
map(find(M==1)) = St;

function [u,ind] = cunion(s,eqfun)

if isempty(s)
	u = [];
    return
else

	if isa(s,'double')
		u = s(1);
    ind = 1;

		for i=1:length(s)
			if ~any(isnull(abs(u-s(i))))
				u = [u,s(i)]; %#ok<AGROW>
        ind = [ind,i];%#ok<AGROW>
			end
		end
	else
		u = s(1);
    ind = 1;
    if nargin == 1, eqfun = @(a,b) isnull(norm(a-b));end

		for i=1:length(s)
			if ~any(eqfun(u,s(i)))
				u = [u,s(i)]; %#ok<AGROW>
        ind = [ind,i]; %#ok<AGROW>
			end

