                end
                T_y = cross(T_z, T_x);

                T = [T_x, T_y, T_z, T_t; 0, 0, 0, 1];
            end

            curvilinear = curvilinear@Shape(T, s, varargin{:});

            if isnumeric(radius)
                if isscalar(radius)
                    curvilinear.radius = radius;


