function [stp,x,inform] = cvsrch(fcn,x,s,stp,params)
      p5 = .5;
      p66 = .66;
      xtrapf = 4;
      inform.info = 0;
      infoc = 1;

      if (length(x.p) <= 0 | stp <= 0.0 | params.ftol < 0.0 |  ...
          params.gtol < 0.0 | params.xtol < 0.0 | params.stpmin < 0.0  ...
          | params.stpmax < params.stpmin | params.maxfev <= 0) 
         return
      end
      dginit = x.g'*s;
      if (dginit >= 0.0) 
          return
      end
      brackt = 0;
      stage1 = 1;
      inform.nfev = 0;
      finit = x.f;
      dgtest = params.ftol*dginit;
      width = params.stpmax - params.stpmin;
      width1 = 2*width;
      wa = x.p;
      stx = 0.0;
      fx = finit;
      dgx = dginit;
      sty = 0.0;
      fy = finit;
      dgy = dginit;

    end
    if (stage1 & x.f <= ftest1 & dg >= min(params.ftol,params.gtol)*dginit) 
           stage1 = 0;
    end
    if (stage1 & x.f <= fx & x.f > ftest1) 
       fm = x.f - stp*dgtest;
       fxm = fx - stx*dgtest;
       fym = fy - sty*dgtest;
       dgm = dg - dgtest;
       dgxm = dgx - dgtest;
       dgym = dgy - dgtest;
       [stx,fxm,dgxm,sty,fym,dgym,stp,fm,dgm,brackt,infoc] ...
        = cstep(stx,fxm,dgxm,sty,fym,dgym,stp,fm,dgm, ...
                brackt,stmin,stmax);
       fx = fxm + stx*dgtest;
       fy = fym + sty*dgtest;
       dgx = dgxm + dgtest;
       dgy = dgym + dgtest;
    else
       [stx,fx,dgx,sty,fy,dgy,stp,x.f,dg,brackt,infoc] ...
        = cstep(stx,fx,dgx,sty,fy,dgy,stp,x.f,dg, ...
                brackt,stmin,stmax);
    end
    if (brackt) 
       if (abs(sty-stx) >= p66*width1) 
         stp = stx + p5*(sty - stx);
       end
       width1 = width;
       width = abs(sty-stx);
    end
end

function  [stx,fx,dx,sty,fy,dy,stp,fp,dp,brackt,info] ...
  = cstep(stx,fx,dx,sty,fy,dy,stp,fp,dp,brackt,stpmin,stpmax)
 p66 = 0.66;
 info = 0;
 if ((brackt & (stp <= min(stx,sty) | ...
     stp >= max(stx,sty))) | ...
     dx*(stp-stx) >= 0.0 | stpmax < stpmin) 
    return
 end
 sgnd = dp*(dx/abs(dx));
 if (fp > fx) 
    info = 1;
    bound = 1;
    theta = 3*(fx - fp)/(stp - stx) + dx + dp;

s = norm([theta,dx,dp],inf);
gamma = s*sqrt(max(0.,(theta/s)^2 - (dx/s)*(dp/s)));
if (stp > stx) 
    gamma = -gamma;
end
p = (gamma - dp) + theta;
q = (gamma + (dx - dp)) + gamma;
r = p/q;
if (r < 0.0 & gamma ~= 0.0)
   stpc = stp + r*(stx - stp);
elseif (stp > stx)
   stpc = stpmax;
else
   stpc = stpmin;
end 
stpq = stp + (dp/(dp-dx))*(stx - stp);
if (brackt) 
   if (abs(stp-stpc) < abs(stp-stpq)) 
      stpf = stpc;
   else
      stpf = stpq;
   end
else
   if (abs(stp-stpc) > abs(stp-stpq)) 
      stpf = stpc;
   else
      stpf = stpq;
   end

