function [model] = d2c(varargin)
	if(isempty(varargin{1}))
		error ('Missing model')
	end
	if(strcmp(varargin{1}.type, 'SS' ))
		A = varargin{1}.A;
		B = varargin{1}.B;
		C = varargin{1}.C;
		D = varargin{1}.D;
		delay = varargin{1}.delay;
		sampleTime = varargin{1}.sampleTime;
		a1 = size(A,2) + size(B,2) - size(A,1);
		b1 = size(A,2);
		a2 = size(A,2) + size(B,2) - size(B,1);
		b2 = size(B,2);
		M = [A B; zeros(a1, b1)	eye(a2, b2)];
		M = round(logm(M)*1/sampleTime*1/1e-6)*1e-6; % Very important to remove small numbers!!
		M(abs(M) < 1e-6) = 0; % Very importat to turn -0 to 0.
		A = M(1:size(A,1), 1:size(A,2));
		B = M(1:size(B,1), (size(A,2) + 1):(size(A,2) + size(B,2)));
		model = ss(delay, A, B, C, D);
		model.sampleTime = 0;
	elseif(strcmp(varargin{1}.type, 'TF' ))
		sysd = tf2ss(varargin{1}, 'OCF');
		G = d2c(sysd);
		model = ss2tf(G);
	else
		error('No state space model or transfer function')
	end
end

function [H11, H12, H21, H22] = d2Ibr_dV2(Ybr, V, mu, vcart)


if nargin < 4
    vcart = 0;      %% default to polar coordinates
end

nb = length(V);

if vcart
    H11 = sparse(nb, nb);
    H12 = H11;
    H21 = H11;
    H22 = H11;
else
    diagInvVm = sparse(1:nb, 1:nb, ones(nb, 1)./abs(V), nb, nb);

    H11 = sparse(1:nb, 1:nb, -(Ybr.' * mu) .* V, nb, nb);
    H21 = -1j * H11 * diagInvVm;
    H12 = H21;
    H22 = sparse(nb, nb);

function Gsv = d2Imis_dVdSg(Cg, V, lam, vcart)


if nargin < 4
    vcart = 0;      %% default to polar coordinates
end

nb = length(V);

if vcart
    D = Cg' * sparse(1:nb,1:nb, lam./conj(V.^2), nb, nb);

    G_Pg_Vr = D;
    G_Pg_Vi = -1j * D;
    G_Qg_Vr = G_Pg_Vi;
    G_Qg_Vi = -D;

    Gsv = [ G_Pg_Vr G_Pg_Vi;
            G_Qg_Vr G_Qg_Vi ];
else
    D = sparse(1:nb, 1:nb, 1./abs(V), nb, nb);
    E = sparse(1:nb, 1:nb, lam./conj(V), nb, nb);
    K = Cg' * E;
    L = K * D;

    G_Pg_Va = -1j * K;
    G_Pg_Vm = L;
    G_Qg_Va = -K;
    G_Qg_Vm = -1j * L;

    Gsv = [ G_Pg_Va G_Pg_Vm;
            G_Qg_Va G_Qg_Vm ];
end

