function nImage = set_criteria(rLimit, periodicType, inputLatt)
    rCutoff = sqrt(rLimit);
    lattice = inputLatt;
    cross23 = cross(lattice(2, :), lattice(3, :));
    cross31 = cross(lattice(3, :), lattice(1, :));
