            nStre = size(fun,1);
            dfun  = cell(3,3);
            ddfun = cell(3,3);
            for i=1:nStre
                for j=1:nStre
                    dfun{i,j} = diff(fun{i,j});
                    ddfun{i,j} = diff(dfun{i,j});
                end
            end

