       s(:,1) = (x+2).^2 + y.^2;
       s(:,2) = 1;
    end
    function s = exactp(pt)
       x = pt(:,1); y = pt(:,2);
       s = x.^3.*y + y.^4 + sin(pi*x).*cos(pi*y);
    end
    function s = gradp(pt)
       x = pt(:,1); y = pt(:,2);
       s(:,2) = x.^3 + 4*y.^3 - pi*sin(pi*x).*sin(pi*y);
       s(:,1) = 3*x.^2.*y + pi*cos(pi*x).*cos(pi*y);       
    end
    function s = exactu(pt)
       Dp = -gradp(pt);  % u = - K*grad(p)
       K = K(pt);
       s(:,2) = K(:,3).*Dp(:,1) + K(:,2).*Dp(:,2);
       s(:,1) = K(:,1).*Dp(:,1) + K(:,3).*Dp(:,2);
    end
    function s = f(pt)
        x = pt(:,1); y = pt(:,2);
        s = sin(2*pi*x).*cos(2*pi*y);
    end
    function s = g_D(pt)
       s = exactp(pt); 
    end
    function s = g_N(pt,n)
       s = dot(exactu(pt),n,2); 
    end
end

function [p,u,eqn,info] = DarcyRT0(node,elem,bdFlag,pde,option)


if ~exist('option','var'), option = []; end

