[nobs, nvar] = size(DATA);
OUT = nan(nobs,nvar);

if vtreat==0
    OUT = DATA;

elseif vtreat==1
    if ~isempty(DATA<0), warning('Negative numbers set to NaN before taking logs'), end
    DATA(DATA<0) = NaN;
    OUT = log(DATA);

elseif vtreat==2
    OUT(nlag+1:end,:) = DATA(1+nlag:end,:) - DATA(1:end-nlag,:);

elseif vtreat==3
    if ~isempty(DATA<0), warning('Negative numbers set to NaN before taking logs'), end
    DATA(DATA<0) = NaN;
    OUT(nlag+1:end,:) = log(DATA(1+nlag:end,:))-log(DATA(1:end-nlag,:));

