        while k<=r
            pdc(k)=sum(x(bcp5u(k,1):bct5u(k+1,1),1)-x(bcp5u(k,1),1));
            k=k+1;
        end


    end


    if bct5u(1,1) < bcp5u(1,1)       %  Troughs are first

        r   = npk;
        td  = bcp5u(1:r,1)-bct5u(1:r,1);
