if rem(num_coefs,2)
   error( 'Error: NUM_COEFS must be even!!!')
end

N=num_coefs/2;


poly=trigpol(N);    %Calculate trigonometric polynomial 


zeros=roots(poly);  %Calculate roots


modulus=abs(zeros);

j=1;
for i=1:(2*(N-1))
	if (modulus(i)<1)
		zerosinside(j)=zeros(i);
		j=j+1;
	end;
end;

if j ~= N
	error('Error!!!'); % The number of zeros inside the unit circle
end

An=poly(1);

realzeros=[];
imagzeros=[];
numrealzeros=0;
numimagzeros=0;

for i=1:(N-1)
	if (imag(zerosinside(i))==0)
		numrealzeros=numrealzeros+1;
		realzeros(numrealzeros)=zerosinside(i);
	else
		numimagzeros=numimagzeros+1;
		imagzeros(numimagzeros)=zerosinside(i);	

	end;

end;

function [h_0,h_1] = daubcqf(N,TYPE)

if(nargin < 2),
  TYPE = 'min';
end;
if(rem(N,2) ~= 0),
  error('No Daubechies filter exists for ODD length');
end;
K = N/2;
a = 1;
p = 1;
q = 1;
h_0 = [1 1];
for j  = 1:K-1,
  a = -a * 0.25 * (j + K - 1)/j;
  h_0 = [0 h_0] + [h_0 0];
  p = [0 -p] + [p 0];
  p = [0 -p] + [p 0];
  q = [0 q 0] + a*p;
end;
q = sort(roots(q));
qt = q(1:K-1);
if TYPE=='mid',
  if rem(K,2)==1,  
    qt = q([1:4:N-2 2:4:N-2]);
  else
    qt = q([1 4:4:K-1 5:4:K-1 N-3:-4:K N-4:-4:K]);
  end;
end;
h_0 = conv(h_0,real(poly(qt)));

