    return
end
if (nargin < 2) || isempty(isUpdate)
    isUpdate = 1;
end
ProtocolInfo = bst_get('ProtocolInfo');

isProgressBar = ~bst_progress('isVisible');
if isProgressBar
    bst_progress('start', 'Reload datasets', 'Reloading datasets...', 0, 100 * length(iStudies));
end
for iStudy = iStudies
    sStudy = bst_get('Study', iStudy);
    if isempty(sStudy)
        continue;
    end
    studySubDir = bst_fileparts(sStudy.FileName);
    if ~file_exist(bst_fullfile(ProtocolInfo.STUDIES, studySubDir))
        db_fix_protocol();
        bst_progress('stop');
        return
    end
    sStudyNew = db_parse_study(ProtocolInfo.STUDIES, studySubDir, 100);
    if isempty(sStudyNew)
        db_fix_protocol();
        bst_progress('stop');
        return
    end
    if ~isempty(sStudy.HeadModel) && ~isempty(sStudy.iHeadModel) && ~isempty(sStudyNew.HeadModel)
        sStudyNew.iHeadModel = find(strcmp(sStudy.HeadModel(sStudy.iHeadModel).FileName, {sStudyNew.HeadModel.FileName}));
    end
    if ~isempty(sStudy.iHeadModel) && (sStudy.iHeadModel <= length(sStudyNew.HeadModel)) && isempty(sStudyNew.iHeadModel)
        sStudyNew.iHeadModel = sStudy.iHeadModel;
    end
    bst_set('Study', iStudy, sStudyNew);

