        end
        isFirstWarning = 0;
    end

    bst_progress('start', 'Update database', 'Updating database structure...');
    for ip = 1:length(ProtocolsListStudies)
        if isempty(ProtocolsListStudies(ip).Study)
            ProtocolsListStudies(ip).Study(1).Comment = 'update';
