            if opt.mode>glc.PMODE_DGNSS
                if f<=nf
                    rtk.sat(sat(i)).vsat(f)=1;
                    rtk.sat(sat(j)).vsat(f)=1;
                end
            else
                rtk.sat(sat(i)).vsat(f-nf)=1;
