            end

            if f<=nf,kk3=0;else,kk3=1;end
            vflag(nv+1)=bitshift(sat(i),16)|bitshift(sat(j),8)|bitshift(kk3,4)|rem(f-1,nf);
            nv=nv+1;
            nb(b+1)=nb(b+1)+1;
        end
        b=b+1;
    end
end

v(nv+1:end)=[]; H(nv+1:end,:)=[]; Ri(nv+1:end,:)=[]; Rj(nv+1:end,:)=[];

R=ddcov(nb,b,Ri,Rj,nv);

return

