function [x_final,MSE] = Deblurring_GSR(i,path,y,Opts)

mu = Opts.mu;
x_org = Opts.org;
IterNums = Opts.IterNums;
initial = Opts.initial;

x = initial;

c = zeros(size(y));

MSE = zeros(1,IterNums+1);

MSE(1) = sum(sum((x-x_org).^2))/numel(x);

fprintf('Initial PSNR = %f\\n',csnr(x,x_org,0,0));

result=fopen(strcat(path,'\\data.txt'),'a+');
for Outloop = 1:IterNums

    w = GSR_Solver_Deblur(x-c,Opts);

    r = y + mu*(w+c);
    x = r/(mu+1);

    c = c + (w - x);

    x_resid = x - x_org;
    MSE(Outloop+1) =  (x_resid(:)'*x_resid(:))/numel(x);

    Final_Name_GSR = strcat('_IterNum_',num2str(Outloop),'_PSNR_',num2str(csnr(x,x_org,0,0)));
    fprintf('iter number = %d, PSNR = %f\\n',Outloop,csnr(x,x_org,0,0));
    fprintf(result,'IterNum = %d, PSNR = %0.5f\\r\\n',Outloop,csnr(x,x_org,0,0));
end

x_final = x;

fprintf('Final PSNR = %f\\n',csnr(x_final,x_org,0,0));

fprintf(result,'\\r\\n\\r\\n');
fclose('all');
if mod(i,10)==0
    save(strcat(path,'\\',Final_Name_GSR,'.mat'),'x_final');
end

function [u]= Deblur_L1mL2smooth(f, A, lambda, mu, alpha, delta)

    rho = 1.25;

    [rows,cols] = size(f);

    u0 = ones(rows,cols);

    u= u0;

    wx = u0;
    wy = u0;

    zx = u0;
    zy = u0;

    uker = zeros(rows,cols);
    uker(1,1) = 4;uker(1,2)=-1;uker(2,1)=-1;uker(rows,1)=-1;uker(1,cols)=-1;

    [xLen_flt, yLen_flt] = size(A);
    ope_blur=zeros(rows,cols);
    ope_blur(1:xLen_flt,1:yLen_flt)=A;

    xLen_flt_1=floor(xLen_flt/2);yLen_flt_1=floor(yLen_flt/2);
    ope_blur_1=padarray(ope_blur,[rows,cols],'circular','pre');
    ope_blur_1=ope_blur_1(xLen_flt_1+1:rows+xLen_flt_1,yLen_flt_1+1:cols+yLen_flt_1);

    rhslfft=lambda.*conj(fft2(ope_blur_1)).*fft2(f);

    for i=1:300

        u0 = u;

        new_uker = lambda*conj(fft2(ope_blur_1)).*fft2(ope_blur_1)+(mu+delta)*fft2(uker);

        rhs2 = delta*Dxt(wx-zx/delta)+delta*Dyt(wy-zy/delta);
        rhsfft = rhslfft + fft2(rhs2);

        u = ifft2(rhsfft./new_uker);

        err=norm(u-u0,'fro')/norm(u, 'fro');

        if mod(i,10)==0
            disp(['iterations: ' num2str(i) '!  ' 'error is:   ' num2str(err)]);
        end

        if err<10^(-4)
            break;
        end

function [result, idx] = Deblur_L1mL2_SLaT(f, A, lambda, mu, alpha, k)
    f = rescale_color_image(f);

    uu = zeros(size(f));

    zLen = size(uu,3);

    parfor i = 1:zLen
        uu(:,:,i) = Deblur_L1mL2smooth(f(:,:,i), A, lambda, mu, alpha, 2);
    end

    cform = makecform('srgb2lab');
    g = double(applycform(uint8(uu*255),cform))/255;
    uu(:,:,4:6) = rescale_color_image(g);

    [m,n,~] = size(uu);
    u_vector = reshape(uu, m*n, 6);
    idx = kmeans(u_vector, k, 'Replicates', 50, 'Options',statset('UseParallel',1));
    idx = reshape(idx, m,n);

    mean_c = zeros(k,3);
    result = zeros(m,n,3);
    for i = 1:k
        region_channel1 = double(i==idx).*uu(:,:,1);
        region_channel2 = double(i==idx).*uu(:,:,2);
        region_channel3 = double(i==idx).*uu(:,:,3);

        mean_c(i,:) = [sum(region_channel1(:))/(sum(region_channel1(:)>0)),...
            sum(region_channel2(:))/(sum(region_channel2(:)>0)),...
            sum(region_channel3(:))/(sum(region_channel3(:)>0))];

        result(:,:,1) = result(:,:,1) +  mean_c(i,1)*double(i==idx);
        result(:,:,2) = result(:,:,2) +  mean_c(i,2)*double(i==idx);
        result(:,:,3) = result(:,:,3) +  mean_c(i,3)*double(i==idx);
    end
end

