function Population = DecompositionSelection(Global,Population,associate,Cosinemax)



    np = length(Population);
    Obj = Population.objs;
    Obj = (Obj-repmat(min(Obj),np,1))./(repmat(max(Obj),np,1)-repmat(min(Obj),np,1));

    list = unique(associate)';
    Next = zeros(length(list),1);
    t = 1;
    for i = list
        current = find(associate == i);
        dist = pdist2(Obj(current,:),zeros(1,Global.M),'Euclidean');
        Fan = Cosinemax(current)./dist;
        [~,best] = max(Fan);
        Next(t)  = current(best);
        t = t +1;
    end
    Population = Population(Next);
end

function [Oqeggmess, f0mess, npicferms, npicouvers, atimes] = decom_sig(s, fs, f0s, method)

    if nargin<3; f0s=[]; f0=[]; end
    if nargin<4; method = []; end

    winLen=2*round(20/1000*fs /2)+1;
    winShift=round(5/1000*fs);

    start=1;
    stop=start+winLen-1;
    cnt=1;

    while stop <= length(s)

        x_frame = s(start:stop);
        atimes(cnt) = (0.5*(stop+start))/fs;

        if ~isempty(f0s) && size(f0s,2)>1
            f0 = interp1(f0s(:,1), f0s(:,2), atimes(cnt), 'nearest', 'extrap');
        end

        [Oqeggmess(cnt), f0mess(cnt), npicferms(cnt), npicouvers(cnt)] = decom(x_frame, fs, f0, method);

        start=start+winShift-1;
        stop=start+winLen-1;
        cnt=cnt+1;
    end

return

