if ( strcmp(type, 'L2') )
    for rCounter = 1:length(r)
        normFun = normFun*norm(u-rBlocks{rCounter}, 'fro')^2;
    end
else
    for rCounter = 1:length(r)
        ur = u - rBlocks{rCounter};
        normFun = normFun*(norm(ur,'fro')^2 + norm(diff(ur), 'fro')^2);
    end
end

