function Dhat = demodulate_in_frequency_combine(p, G, x, pilot_set, norm_factor)
M = p.M; K = p.K;
L = length(G) / M;
LL = p.L;

indices = 1:M;
indices(pilot_set) = [];

pilot_subcar = p.Kset(1)+1:p.Delta_k:p.Kset(end)+1;
data_subcar = p.Kset+1;
data_subcar(pilot_subcar) = [];

Xhat = fft(x);
Dhat = zeros(K, M);
for k = pilot_subcar
    carrier = circshift(Xhat, ceil(L*M/2) - M*(k-1));
    carrier = fftshift(carrier(1:L*M));
    carrierMatched = carrier .* (G.*norm_factor);
    dhat = (sum(reshape(carrierMatched,M,L),2)/L);%M samples ifft
    dhat(indices) = ifft(dhat(indices));%*sqrt(M-1)/sqrt(M);
    Dhat(k,:) = dhat;
end
Dhat(pilot_subcar,pilot_set) = zeros(length(pilot_subcar),length(pilot_set)); %abs(Dhat(pilot_subcar,pilot_set)) > 0.01;

function Dhat = demodulate_oqam(p, x)
K = p.K; M = p.M;
N = M*K;
g = get_transmitter_pulse(p);

useXia = ~isempty(strfind(p.pulse,'xia'));

useReversed = ~isempty(strfind(p.pulse,'_td'));

Dhat=zeros(K,M);
if ~isfield(p, 'cache.go')
    if useReversed
        go = g.*exp(1i*2*pi*0.5/K*(0:N-1)');
    else
        go = circshift(g, p.K/2);
    end
else
    go = p.cache.go;
end

Dhat1 = demodulate_in_frequency(p, conj(fft(g)), x);
Dhat2 = demodulate_in_frequency(p, conj(fft(go)), x);

if useXia
     Dhat = real(Dhat1) + 1i*imag(Dhat2);
else
     if useReversed
         Dhat(:,1:2:end) = real(Dhat1(:,1:2:end)) + 1i*imag(Dhat2(:,1:2:end));
         Dhat(:,2:2:end) = real(Dhat2(:,2:2:end)) + 1i*imag(Dhat1(:,2:2:end));
     else
         Dhat(1:2:end,:) = real(Dhat1(1:2:end,:)) + 1i*imag(Dhat2(1:2:end,:));
         Dhat(2:2:end,:) = real(Dhat2(2:2:end,:)) + 1i*imag(Dhat1(2:2:end,:));
     end
end


end

