function gx = g_source1 (~, phi, ut, ~)
    gx = - phi(1) * ut + phi(2);
end

function gx = g_source2 (~, phi, ut, ~)
    gx = VBA_sigmoid(ut, 'slope', phi(1), 'center', phi(2));
end

function gx = g_source3 (~, phi, ut, ~)
    ratings = - 2 : 2;
    gx = exp (- phi(1) * (ut - ratings - phi(2)) .^ 2);
    gx = gx(:) / sum (gx);
end



