function [dn,z,x,y] = demprofile(DEM,n,x,y)



if nargin <= 2;
    h = imagesc(DEM);
    ax = get(h,'Parent');

    [x, y] = getline(ax);
    do = getdistance(x,y);

    if nargin == 1;
        n = ceil(do(end)/DEM.cellsize)*2;
    end

    dn = linspace(0,do(end),n);
    dn = dn(:);
    xy = interp1(do,[x y],dn,'linear');

    x  = xy(:,1);
    y  = xy(:,2);

else
    if n ~= numel(x);
        x = x(:);
        y = y(:);
        do = getdistance(x,y);
        dn = linspace(0,do(end),n);
        dn = dn(:);
        xy = interp1(do,[x y],dn,'linear');

        x  = xy(:,1);
        y  = xy(:,2);
    else

        dn = getdistance(x,y);
    end
end

