    D0.M(1).E.s = 0;
    D0          = spm_DEM(D0);

    e_x      = spm_ekf(DEM.M,DEM.Y);
    d_x      = DEM.qU.x{1};
    t_x      = DEM.pU.x{1};
    i_x      = D0.qU.x{1};

