Df = @(x,v,P,G) [-P(1) P(1) 0; P(3) -1 -x(1); x(2) 0 P(2)]/64 + ...
                [0 0 0; -x(3) 0 0; 0 x(1) 0]/64;

G.x  = [1; 1; 24];
G.f  = f;

b     = 32;                         % number of bins for density estimation
