function [HB,HBH,IBH] = spm_G(A,lnpH,lnpA)


n     = size(A,2);
m     = size(A,3);
pH    = spm_softmax(lnpH);
pA    = spm_softmax(lnpA);

ln    = @(p)log(spm_vec(p) + 1e-16);
H     = @(p)-spm_vec(p)'*ln(p);

for i = 1:n
    for j = 1:m
        pSxHxA(:,i,j) = A(:,i,j)*pH(i)*pA(j);
    end
end

pB    = spm_vec(sum(pSxHxA,2));
HB    = H(pB);
if nargout > 1
    IBH = H(pB) + H(pH) - H(pSxHxA);
    HBH = HB - IBH;
end

return

