function X = denseSolve(N, f, m, n)


[bctype, g] = chebop2.checkBC(N, m, n);
if ( isPoisson(N) && bctype == 1 )
    u = chebfun2.poisson(f+N.rhs, g, m, n);
    X = coeffs2(u, m, n);
else

    [CC, RHS, bb, gg, Px, Py, xsplit, ysplit] =...
        chebop2.discretize(N, f, m, n); 

    if ( size(CC, 1) == 1 )  
        A = CC{1,1}; 
        B = CC{1,2};
        Y = A \\ RHS;
        X = (B \\ Y.').';
        X = imposeBoundaryConditions(X, bb, gg, Px, Py, m, n);

    elseif ( size(CC, 1) == 2 )
        A = CC{1,1}; 
        B = CC{1,2}; 
        C = CC{2,1}; 
        D = CC{2,2};

        if ( min(size(bb{1})) > 1 || min(size(bb{2}))>1 ||...
                min(size(bb{3}))>1 || min(size(bb{4}))>1 )
            xsplit = 0; 
            ysplit = 0;
        end

        try
            if ( xsplit || ysplit )
                X = chebop2.bartelsStewart(A, B, C, D, RHS, xsplit, ysplit);       
            else
                X = lyap(C\\A,(B\\D).', -(B\\(C\\RHS).').');
            end
        catch

end

function X = imposeBoundaryConditions(X, bb, gg, Px, Py, m, n)

cs = size(bb{3}, 2) + size(bb{4}, 2);
rs = size(bb{1}, 2) + size(bb{2}, 2);
By = [ bb{3}.'; bb{4}.' ].'; 
Gy = [ gg{3}.'; gg{4}.' ].';

if ( ~isempty(By) )
    By = Py.' * By; % Gy = Gy * Py;
    X12 = By(1:cs,:).' \\ (Gy(rs+1:size(X, 2)+rs,:).' - By(cs+1:size(X, 1)+cs,:).'*X);
    X = [ X12; X ];
end

Bx = [bb{1}.' ; bb{2}.'].'; Gx = [gg{1}.' ; gg{2}.'].';

if ( ~isempty(Bx) )
    Bx = Px.' * Bx; %Gx = Px.' * Gx;
    X2 = (Bx(1:rs,:).' \\ ( Gx(1:size(X, 1),:).' - Bx(rs+1:size(X, 2)+rs,:).'*X.')).';
    X = [ X2, X ];
end

if ( size(X, 1) < m )
    X(size(X, 1)+1:m,:) = 0;
end
if ( size(X, 2) < n )
    X(:,size(X, 2)+1:n) = 0;
end

if ( ~isempty(Px) )
    X = X * Px.';
end
if ( ~isempty(Py) )
    X = Py * X;
end

function [out mD]=dense_depth_map(Pts,n, m,grid)

ng=2*grid+1;

linearindex = sub2ind([n m], round(Pts(:,2)), round(Pts(:,1)));

mX=inf([n m]);
mX(linearindex)=Pts(:,1)-round(Pts(:,1));
mY=inf([n m]);
mY(linearindex)=Pts(:,2)-round(Pts(:,2));
mD=zeros([n m]);
mD(linearindex)=Pts(:,3);

for i=1:ng
    for j=1:ng
        KmX{i,j}=mX(i:n-ng+i,j:m-ng+j)-grid-1+i;
        KmY{i,j}=mY(i:n-ng+i,j:m-ng+j)-grid-1+j;
        KmD{i,j}=mD(i:n-ng+i,j:m-ng+j);
    end
end

S=zeros(size(KmD{1,1}));
Y=zeros(size(KmD{1,1}));
for i=1:ng
    for j=1:ng
        s=1./sqrt(KmX{i,j}.*KmX{i,j}+KmY{i,j}.*KmY{i,j});
        Y=Y+s.*KmD{i,j};
        S=S+s;  
    end
end
S(S==0)=1;
out=zeros(n,m);
out(grid+1:end-grid,grid+1:end-grid)=Y./S;

