function k=deriv2(x,y,d)




xd=str2double(d(1));
yd=str2double(d(2));

switch xd,
  case 0,
    xterm=1;
  case 2,
    xterm=x.^2-1;
  case 4,
    xterm=x.^4-6*x.^2+3;
  case 6,
    xterm=x.^6-15*x.^4+45*x.^2-15;
  case 8,
    xterm=x.^8-28*x.^6+210*x.^4-420*x.^2+105;
  otherwise
   error('Unsupported order of derivative')     
end;
switch yd,
  case 0,
    yterm=1;
  case 2,
    yterm=y.^2-1;
  case 4,
    yterm=y.^4-6*y.^2+3;
  case 6,
    yterm=y.^6-15*y.^4+45*y.^2-15;
  case 8,
    yterm=y.^8-28*y.^6+210*y.^4-420*y.^2+105;
  otherwise
    error('Unsupported order of derivative')
end;

