                || ((MAP(neb_ind, 6) ~= MAP(cur_ind, 1) || MAP(neb_ind, 7) ~= MAP(cur_ind, 2)) && MAP(neb_ind, 4) > MAP(cur_ind, 4) + neighbors(i, 4))
