function [Sigma,x0] = covcma(X,y,x0,d,frac)

if nargin < 3; x0 = []; end
if nargin < 4 || isempty(d); d = 'descend'; end
if nargin < 5 || isempty(frac); frac = 0.5; end

[N,D] = size(X);

mu = frac*N;
weights = zeros(1,1,floor(mu));
weights(1,1,:) = log(mu+1/2)-log(1:floor(mu));
weights = weights./sum(weights);

[~,index] = sort(y,d);

if isempty(x0)
    x0 = sum(bsxfun(@times,weights(:),X(index(1:floor(mu)),:)),1);
end

topx = bsxfun(@minus,X(index(1:floor(mu)),:),x0);
Sigma = sum(bsxfun(@times,weights,topx'*topx),3);


end

function M = convectionTermSpherical1D(u)

Nr = u.domain.dims(1);
G = 1:Nr+2;
DXe = u.domain.cellsize.x(3:end);
DXw = u.domain.cellsize.x(1:end-2);
DXp = u.domain.cellsize.x(2:end-1);
rf = u.domain.facecenters.x;

iix = zeros(3*(Nr+2),1);
jjx = zeros(3*(Nr+2),1);
sx = zeros(3*(Nr+2),1);

ue = u.xvalue(2:Nr+1).*DXp./(DXp+DXe).*rf(2:Nr+1).^2./(1/3*(rf(2:Nr+1).^3-rf(1:Nr).^3));
uw = u.xvalue(1:Nr).*DXp./(DXp+DXw).*rf(1:Nr).^2./(1/3*(rf(2:Nr+1).^3-rf(1:Nr).^3));

AE = reshape(ue,Nr,1);
AW = reshape(-uw,Nr,1);
APx = reshape((ue.*DXe-uw.*DXw)./DXp,Nr,1);

rowx_index = reshape(G(2:Nr+1),Nr,1); % main diagonal x
iix(1:3*Nr) = repmat(rowx_index,3,1);
jjx(1:3*Nr) = [reshape(G(1:Nr),Nr,1); ...
		reshape(G(2:Nr+1),Nr,1); reshape(G(3:Nr+2),Nr,1)];
sx(1:3*Nr) = [AW; APx; AE];

kx = 3*Nr;
M = sparse(iix(1:kx), jjx(1:kx), sx(1:kx), Nr+2, Nr+2);

clear
close all

