function [KP, KQ] = knlPQ(XPs, XQs, Egs, alg)

n1 = size(XPs{1}, 2);
n2 = size(XPs{2}, 2);
m1 = size(XQs{1}, 2);
m2 = size(XQs{2}, 2);

if strcmp(alg, 'toy')
    KP = zeros(n1, n2);

    DQ = conDst(XQs{1}(1 : 2, :), XQs{2}(1 : 2, :));
    KQ = exp(-DQ / .15);

elseif strcmp(alg, 'shp1')
    KP = zeros(n1, n2);

    X1 = XQs{1}(3 : end, :);
    X2 = XQs{2}(3 : end, :);
    X1 = X1 ./ repmat(sum(X1 .^ 2, 1), 2, 1);
    X2 = X2 ./ repmat(sum(X2 .^ 2, 1), 2, 1);    

    KQ = X1' * X2;

elseif strcmp(alg, 'shp2')
    KP = zeros(n1, n2);

    I21 = repmat(Eg2(1, :), m1, 1);
    I22 = repmat(Eg2(2, :), m1, 1);
    Nor1 = abs(XP1(I11) - XP2(I21));
    Nor2 = abs(XP1(I12) - XP2(I22));

    Dst1 = repmat(XQs{1}(1, :)', 1, m2);
    Dst2 = repmat(XQs{2}(1, :), m1, 1);
    Dst = abs(Dst1 - Dst2) ./ (min(Dst1, Dst2) + eps);

    Ang1 = repmat(XQs{1}(2, :)', 1, m2);
    Ang2 = repmat(XQs{2}(2, :), m1, 1);
    Ang = abs(Ang1 - Ang2);

    KQ = exp(-(Nor1 + Nor2 + Dst + Ang) / 4);

elseif strcmp(alg, 'pas2')
    KP = zeros(n1, n2);

    Dst1 = repmat(XQs{1}(1, :)', 1, m2);
    Dst2 = repmat(XQs{2}(1, :), m1, 1);
    Dst = abs(Dst1 - Dst2) ./ (min(Dst1, Dst2) + eps);

    Ang1 = repmat(XQs{1}(2, :)', 1, m2);
    Ang2 = repmat(XQs{2}(2, :), m1, 1);
    Ang = abs(Ang1 - Ang2);

    KQ = exp(-(Dst + Ang) / 2);

elseif strcmp(alg, 'pas3')
    DP = conDst(XPs{1}, XPs{2});
    KP = exp(-real(sqrt(DP)));

    Dst1 = repmat(XQs{1}(1, :)', 1, m2);
    Dst2 = repmat(XQs{2}(1, :), m1, 1);
    Dst = abs(Dst1 - Dst2) ./ (min(Dst1, Dst2) + eps);

    Ang1 = repmat(XQs{1}(2, :)', 1, m2);
    Ang2 = repmat(XQs{2}(2, :), m1, 1);
    Ang = abs(Ang1 - Ang2);

    KQ = exp(-(Dst + Ang) / 2);

else
    error('unknown algorithm: %s', alg);

function [ offspring ] = DE_current_to_rand_1(Problem, Population, popsize)



    Fm  = [0.6,0.8,1.0];
    CRm = [0.1,0.2,1.0];
    lu  = [Problem.lower;Problem.upper];

    index = randi([1,length(Fm)],popsize,1);
    F     = Fm(index);
    F     = F';
    index = randi([1,length(CRm)],popsize,1);

    permutation = randperm(Problem.N);
    r0          = permutation;
    [r1, r2,r3] = gnR1R2R3(Problem.N,  r0);

    array = permutation(1:popsize);
    pop   = Population.decs;

    pop1 = pop(1:popsize,:);

    vi = pop1 +  repmat(rand(popsize,1),1,Problem.D) .*(pop(r1(array),:) - pop1 ) + F(:, ones(1, Problem.D)) .*(pop(r2(array),:) - pop(r3(array),:));
    vi = boundConstraint(vi, pop1, lu);
    u  = vi;

    offspring = Problem.Evaluation(u);
end

