function [P_smt, Cen_smt, h_smt, Vn_smt, qbn_smt, imu_smt, dxSmt]=combine_2filt(fwdnav, fwdcov, Cen_bck, h_bck, Vn_bck, qbn_bck, dzBck, PbckInv)

