function doublepeaks = detectmult(TGEI,maxF)


doublepeaks(length(TGEI(:,1))) = 0;

if length(TGEI(:,1)) > 1
	for z = 1: length(TGEI(:,1)) - 1
        if 1 / ( TGEI(z + 1,3) - TGEI(z,3) ) > maxF
            if z == 1
                doublepeaks(z) = 1;
                doublepeaks(z + 1) = 3;
            elseif ismember(doublepeaks(z - 1),[0 3])
                doublepeaks(z) = 1;
                doublepeaks(z + 1) = 3;
            elseif ismember(doublepeaks(z - 1),[1 2])
                doublepeaks(z) = 2;
                doublepeaks(z + 1) = 3;
            end

        end

	end

end

function A_xyz = computeVelCoeffsMtx(sectorOrder)

Ns = sectorOrder;
Nxyz = Ns+1;

x1 = sqrt(2*pi/3);
x3 = -sqrt(2*pi/3);
y1 = 1i*sqrt(2*pi/3);
y3 = 1i*sqrt(2*pi/3);
z2  = sqrt(4*pi/3);

A_xyz = zeros((Nxyz+1)^2, (Ns+1)^2, 3);

G_mtx = gaunt_mtx(Ns, 1, Nxyz);

for ii=1:(Nxyz+1)^2
    for jj=1:(Ns+1)^2

        A_xyz(ii,jj,1) = x1*G_mtx(jj,2,ii) + x3*G_mtx(jj,4,ii);
        A_xyz(ii,jj,2) = y1*G_mtx(jj,2,ii) + y3*G_mtx(jj,4,ii);
        A_xyz(ii,jj,3) = z2*G_mtx(jj,3,ii);
    end
end

function [R1,T1]=Deconvolue(R,T,i0,i1,reg)

R1=[];
T1=[];

for i=1:1:size(R,1)

    SignalCut=R(i,i0:1:i1); % deconvolution window
    A1=mt_spiking(SignalCut,reg); % compute filter


    C1=conv(R(i,:),A1);  % data filter
    comp=C1(1:1:length(R(i,:))); % resize data
    MAX=max(abs(comp)); % Normalization coeff
    R1=[R1;comp/MAX];  % store deconvolued trace


    C1=conv(T(i,:),A1);  % data filter
    comp=C1(1:1:length(R(i,:))); % resize data
    T1=[T1;comp/MAX];
end

function features = ComputeUnconditionedPairFeatures (len, modelParams)

if (len < 2)
    features = [];
    return;
end

K = modelParams.numHiddenStates;
nPairFeatures = (len - 1) * K * K;

features(nPairFeatures) = EmptyFeatureStruct();

featureIdx = 0;
for s1 = 1:K
    for s2 = 1:K
        paramVal = sub2ind([K K], s2, s1);
        for v = 1:(len - 1)
            featureIdx = featureIdx + 1;
            features(featureIdx).var = [v v+1];
            features(featureIdx).assignment = [s1 s2];
            features(featureIdx).paramIdx = paramVal;
        end
    end
end


end

