function dataOut = collapseSmallEdges(dataIn, epsilon)
    v = dataIn.Node;
    e = dataIn.Elem;

    B = dataIn.NodeB;

    U = dataIn.NodeU;
    V = dataIn.NodeV;

    dim = size(v, 2);

    if dim == 3
        EC = dataIn.Elem(dataIn.ElemC, :);
        F = accumarray(EC(:), 1) > 0;
        F = [F; false(numel(B) - numel(F), 1)];
        W = dataIn.NodeW;
        EC = dataIn.ElemC;
        deg = accumarray([e(EC, 1); e(EC, 2)], 1);
        deg = [deg; zeros(size(v, 1) - numel(deg), 1)];
        C = deg > 0;
    else
        C = false(size(B));
        F = C;
    end

    eLen = sqrt( sum( (v(e(:, 1), :) - v(e(:, 2), :)).^2, 2 ) );

    while min(eLen) < epsilon
        [~, idx] = min(eLen);
        pt = e(idx, :);
        e(idx, :) = [];
        if dim==3
            EC(idx, :) = [];
        end


        if C(pt(1)) && ~C(pt(2))
            v(pt(2), :) = v(pt(1), :);
            U(pt(1)) = max(U(pt));

        V(pt(1)) = max(V(pt));
        B(pt(1)) = max(B(pt));
        if dim == 3
            C(pt(1)) = max(C(pt));
            W(pt(1)) = max(W(pt));
        end
        e(e==pt(2)) = pt(1);
    elseif B(pt(2)) && ~B(pt(1))
        v(pt(1), :) = v(pt(2), :);
        U(pt(2)) = max(U(pt));
        V(pt(2)) = max(V(pt));
        B(pt(2)) = max(B(pt));
        if dim == 3
            C(pt(2)) = max(C(pt));
            W(pt(2)) = max(W(pt));
        end
        e(e==pt(1)) = pt(2);
    else
        v(pt(1), :) = (v(pt(1), :) + v(pt(2), :))/2;
        U(pt(2)) = max(U(pt));
        V(pt(2)) = max(V(pt));
        B(pt(2)) = max(B(pt));
        if dim == 3
            C(pt(2)) = max(C(pt));
            W(pt(2)) = max(W(pt));
        end
        e(e==pt(1)) = pt(2);
    end

    eLen = sqrt( sum( (v(e(:, 1), :) - v(e(:, 2), :)).^2, 2 ) );
end

