function out = crop_scale_sample(im, pos, base_target_sz, scaleFactors, scale_window, scale_model_sz)


nScales = length(scaleFactors);

for s = 1:nScales
    patch_sz = floor(base_target_sz * scaleFactors(s));

    xs = floor(pos(2)) + (1:patch_sz(2)) - floor(patch_sz(2)/2);
    ys = floor(pos(1)) + (1:patch_sz(1)) - floor(patch_sz(1)/2);

    xs(xs < 1) = 1;
    ys(ys < 1) = 1;
    xs(xs > size(im,2)) = size(im,2);
    ys(ys > size(im,1)) = size(im,1);

    im_patch = im(ys, xs, :);

    im_patch_resized = mexResize(im_patch, scale_model_sz, 'auto');

    temp_hog = fhog(single(im_patch_resized), 4);
    temp = temp_hog(:,:,1:31);

    if s == 1
        out = zeros(numel(temp), nScales, 'single');
    end

    out(:,s) = temp(:) * scale_window(s);
end

function [dx, dxGrad] = cstDyn(x,u)

dq = x(2,:);   %Velocity
ddq = u(1,:);  %Acceleration

dx = [dq;ddq];   %Pack up derivative of state

if nargout == 2   % Analytic gradients
    nTime = length(u);

    dqGrad = zeros(1,6,nTime); %6 = [time + pos + vel + force + slack];
    dqGrad(1,3,:) = 1; %gradient dq wrt dq

    ddqGrad = zeros(1,6,nTime);  %6 = [time + angle + rate +  force + slack];
    ddqGrad(1,4,:) = 1;  %gradient ddq wrt u

    dxGrad = cat(1, dqGrad, ddqGrad);

end

end

