                KB(end + 1).clauses = i;
            end
        else 
            for i = length(KB):-1:1
                KB_clause = KB(i).clauses;
                if length(KB_clause) == 1 && abs(clause) == abs(KB_clause)
                    KB(i) = [];
                end
            end
        end
    end
