function [f]=comp_idgtreal_fb(coef,g,L,a,M)


N=L/a;
b=L/M;

W = size(coef,3);

N=L/a;
b=L/M;

gl=length(g);
glh=floor(gl/2);  % gl-half


coef=ifftreal(coef,M)*sqrt(M);


g=fftshift(g);

f=zeros(L,W,assert_classname(coef,g));

gw=repmat(g,1,W);

ff=zeros(gl,1,assert_classname(coef,g));


for w=1:W


  for n=0:ceil(glh/a)-1
    delay=mod(-n*a+glh,M);
    for ii=0:gl/M-1
      for m=0:delay-1
        ff(m+ii*M+1)=coef(M-delay+m+1,n+1,w)*g(m+ii*M+1);
      end;
      for m=0:M-delay-1
        ff(m+ii*M+delay+1)=coef(m+1,n+1,w)*g(m+delay+ii*M+1);

delta = 1e-3; %penalty parameter for ADMM
peak = 55;


I = imread('Images/river.jpg');
I = double(I);
rng(1234);

Q = max(max(I)) /peak;
I = I / Q;
I(I == 0) = min(min(I(I > 0)));
u0 = imnoise(uint8(I),'poisson');
u0 = double(u0);

noisy_psnr = psnr(u0*Q, I*Q, 255);
noisy_ssim = ssim(uint8(u0*Q), uint8(I*Q));

lambda = 8;
alpha = 0.1;
uAITV = Poisson_L1mL2(u0, lambda, alpha, delta);
aitv_psnr = psnr(uAITV*Q, I*Q, 255);
